/* ════════════════ إنشاء الجداول ════════════════ */
function ensureTables(PDO $pdo): void
{
    // المستخدمون (مدير + موظفين بصلاحيات مخصصة)
    $pdo->exec("CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL UNIQUE,
        password_hash TEXT NOT NULL,
        full_name TEXT NOT NULL DEFAULT '',
        role TEXT NOT NULL DEFAULT 'employee' CHECK(role IN ('owner','employee')),
        permissions TEXT NOT NULL DEFAULT '{}',
        is_active INTEGER NOT NULL DEFAULT 1,
        avatar_color TEXT DEFAULT '#6C43FF',
        last_login TEXT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )");

    // الزبائن
    $pdo->exec("CREATE TABLE IF NOT EXISTS customers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        full_name TEXT NOT NULL,
        phone TEXT DEFAULT '',
        address TEXT DEFAULT '',
        notes TEXT DEFAULT '',
        is_blocked INTEGER NOT NULL DEFAULT 0,
        created_by INTEGER,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL
    )");

    // فئات/أنواع البطاقات (المخزون يُدار حسب الفئة)
    $pdo->exec("CREATE TABLE IF NOT EXISTS card_categories (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        default_buy_price REAL NOT NULL DEFAULT 0,
        default_sell_price REAL NOT NULL DEFAULT 0,
        quantity_available INTEGER NOT NULL DEFAULT 0,
        low_stock_threshold INTEGER NOT NULL DEFAULT 5,
        color TEXT DEFAULT '#6C43FF',
        icon TEXT DEFAULT 'ph-wifi-high',
        is_active INTEGER NOT NULL DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )");

    // حركات المخزون (وارد / تسوية يدوية) — سجل تدقيق للكمية
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_movements (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        category_id INTEGER NOT NULL,
        movement_type TEXT NOT NULL CHECK(movement_type IN ('in','adjustment','sale_out')),
        quantity INTEGER NOT NULL,
        note TEXT DEFAULT '',
        user_id INTEGER,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(category_id) REFERENCES card_categories(id) ON DELETE CASCADE,
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
    )");

    // المبيعات (بيع بطاقة لزبون)
    $pdo->exec("CREATE TABLE IF NOT EXISTS sales (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_no TEXT NOT NULL UNIQUE,
        customer_id INTEGER NULL,
        category_id INTEGER NOT NULL,
        quantity INTEGER NOT NULL DEFAULT 1,
        buy_price REAL NOT NULL DEFAULT 0,
        sell_price REAL NOT NULL DEFAULT 0,
        total_cost REAL NOT NULL DEFAULT 0,
        total_sell REAL NOT NULL DEFAULT 0,
        profit REAL NOT NULL DEFAULT 0,
        payment_status TEXT NOT NULL DEFAULT 'paid' CHECK(payment_status IN ('paid','debt','partial')),
        amount_paid REAL NOT NULL DEFAULT 0,
        notes TEXT DEFAULT '',
        user_id INTEGER,
        sold_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,
        FOREIGN KEY(category_id) REFERENCES card_categories(id) ON DELETE RESTRICT,
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
    )");

    // الديون (مرتبطة بزبون؛ قد تنشأ من عملية بيع أو يدوياً)
    $pdo->exec("CREATE TABLE IF NOT EXISTS debts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL,
        sale_id INTEGER NULL,
        original_amount REAL NOT NULL DEFAULT 0,
        remaining_amount REAL NOT NULL DEFAULT 0,
        due_date TEXT NULL,
        status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','paid','overdue')),
        note TEXT DEFAULT '',
        user_id INTEGER,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,
        FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE SET NULL,
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
    )");

    // تسديدات الديون (دعم تسديد جزئي متعدد الدفعات)
    $pdo->exec("CREATE TABLE IF NOT EXISTS debt_payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        debt_id INTEGER NOT NULL,
        amount REAL NOT NULL DEFAULT 0,
        note TEXT DEFAULT '',
        user_id INTEGER,
        paid_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(debt_id) REFERENCES debts(id) ON DELETE CASCADE,
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
    )");

    // المصاريف
    $pdo->exec("CREATE TABLE IF NOT EXISTS expenses (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        amount REAL NOT NULL DEFAULT 0,
        category TEXT DEFAULT 'عام',
        note TEXT DEFAULT '',
        user_id INTEGER,
        expense_date TEXT DEFAULT CURRENT_TIMESTAMP,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
    )");

    // سجل تدقيق عام (Audit Log)
    $pdo->exec("CREATE TABLE IF NOT EXISTS audit_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT DEFAULT '',
        details TEXT DEFAULT '',
        user_name TEXT DEFAULT 'نظام',
        ip_address TEXT DEFAULT '',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )");

    // إعدادات عامة (مفتاح/قيمة)
    $pdo->exec("CREATE TABLE IF NOT EXISTS settings (
        key TEXT PRIMARY KEY,
        value TEXT DEFAULT ''
    )");

    // فهارس لتسريع الاستعلامات الشائعة
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_sales_customer ON sales(customer_id)");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(sold_at)");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_debts_customer ON debts(customer_id)");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_debts_status ON debts(status)");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_expenses_date ON expenses(expense_date)");
}
ensureTables($pdo);

/* ════════════════ مخطط بوابة الزبائن (هجرة تلقائية آمنة) ════════════════ */
function columnExists(PDO $pdo, string $table, string $col): bool
{
    $cols = $pdo->query("PRAGMA table_info($table)")->fetchAll();
    foreach ($cols as $c) if ($c['name'] === $col) return true;
    return false;
}

function ensurePortalSchema(PDO $pdo): void
{
    // أعمدة حساب البوابة على جدول الزبائن (تُضاف مرة واحدة فقط)
    $newCols = [
        'username'          => "TEXT",
        'password_hash'     => "TEXT",
        'portal_block_debt' => "INTEGER NOT NULL DEFAULT 0",
        'registered_at'     => "TEXT",
        'balance'           => "REAL NOT NULL DEFAULT 0",
    ];
    foreach ($newCols as $col => $type) {
        if (!columnExists($pdo, 'customers', $col)) {
            $pdo->exec("ALTER TABLE customers ADD COLUMN $col $type");
        }
    }
    $pdo->exec("CREATE UNIQUE INDEX IF NOT EXISTS idx_customers_username ON customers(username) WHERE username IS NOT NULL");

    // مخزن أرقام البطاقات (يرفعها المالك ويرسلها للزبائن)
    $pdo->exec("CREATE TABLE IF NOT EXISTS cards_pool (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        card_number TEXT NOT NULL,
        category_id INTEGER NULL,
        status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','sent')),
        sent_to_customer_id INTEGER NULL,
        sent_at TEXT NULL,
        sent_by INTEGER NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(category_id) REFERENCES card_categories(id) ON DELETE SET NULL,
        FOREIGN KEY(sent_to_customer_id) REFERENCES customers(id) ON DELETE SET NULL,
        FOREIGN KEY(sent_by) REFERENCES users(id) ON DELETE SET NULL
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_cards_pool_status ON cards_pool(status)");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_cards_pool_customer ON cards_pool(sent_to_customer_id)");

    // إيصالات الدفع المرفوعة من الزبائن (الصورة كـ BLOB)
    $pdo->exec("CREATE TABLE IF NOT EXISTS payment_receipts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL,
        method TEXT NOT NULL CHECK(method IN ('palpay','jawwalpay')),
        amount REAL NOT NULL DEFAULT 0,
        note TEXT DEFAULT '',
        image_data BLOB NULL,
        image_mime TEXT DEFAULT 'image/jpeg',
        status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),
        reviewed_by INTEGER NULL,
        reviewed_at TEXT NULL,
        review_note TEXT DEFAULT '',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,
        FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_receipts_status ON payment_receipts(status)");

    // طلبات شراء البطاقات من الزبائن
    $pdo->exec("CREATE TABLE IF NOT EXISTS purchase_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL,
        category_id INTEGER NULL,
        quantity INTEGER NOT NULL DEFAULT 1,
        note TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','done')),
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        handled_by INTEGER NULL,
        handled_at TEXT NULL,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,
        FOREIGN KEY(category_id) REFERENCES card_categories(id) ON DELETE SET NULL,
        FOREIGN KEY(handled_by) REFERENCES users(id) ON DELETE SET NULL
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_requests_status ON purchase_requests(status)");

    // إشعارات الزبائن (تُعرض داخل البوابة + تُرسل Push)
    $pdo->exec("CREATE TABLE IF NOT EXISTS customer_notifications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        body TEXT DEFAULT '',
        is_read INTEGER NOT NULL DEFAULT 0,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_cnotif_customer ON customer_notifications(customer_id, is_read)");

    // اشتراكات Web Push (للزبائن)
    $pdo->exec("CREATE TABLE IF NOT EXISTS push_subscriptions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL,
        endpoint TEXT NOT NULL UNIQUE,
        p256dh TEXT NOT NULL,
        auth TEXT NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE
    )");

    // حركات رصيد الزبون (شحن من الإدارة / قبول إيصال / شراء بطاقة من البوابة) — سجل تدقيق كامل
    $pdo->exec("CREATE TABLE IF NOT EXISTS balance_transactions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL,
        type TEXT NOT NULL CHECK(type IN ('recharge','purchase','refund','receipt_credit')),
        amount REAL NOT NULL DEFAULT 0,
        balance_after REAL NOT NULL DEFAULT 0,
        note TEXT DEFAULT '',
        ref_sale_id INTEGER NULL,
        ref_receipt_id INTEGER NULL,
        user_id INTEGER NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,
        FOREIGN KEY(ref_sale_id) REFERENCES sales(id) ON DELETE SET NULL,
        FOREIGN KEY(ref_receipt_id) REFERENCES payment_receipts(id) ON DELETE SET NULL,
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_balance_tx_customer ON balance_transactions(customer_id, created_at)");

    // عمود على مخزن البطاقات: هل بيعت عبر البوابة بالرصيد (لتمييزها عن الإرسال اليدوي)
    if (!columnExists($pdo, 'cards_pool', 'sold_via_portal')) {
        $pdo->exec("ALTER TABLE cards_pool ADD COLUMN sold_via_portal INTEGER NOT NULL DEFAULT 0");
    }
    if (!columnExists($pdo, 'cards_pool', 'sale_price')) {
        $pdo->exec("ALTER TABLE cards_pool ADD COLUMN sale_price REAL NULL");
    }

    // إظهار الدين للزبون في البوابة: مخفي افتراضياً حتى يفعّله المالك لكل زبون
    if (!columnExists($pdo, 'customers', 'portal_show_debt')) {
        $pdo->exec("ALTER TABLE customers ADD COLUMN portal_show_debt INTEGER NOT NULL DEFAULT 0");
    }

    // فهرس فريد على رقم البطاقة: يمنع تكرار نفس الرقم في المخزن نهائياً
    try {
        $pdo->exec("CREATE UNIQUE INDEX IF NOT EXISTS ux_cards_pool_number ON cards_pool(card_number)");
    } catch (Exception $e) { /* توجد تكرارات قديمة — الفهرس سيُنشأ بعد تنظيفها */ }
}
ensurePortalSchema($pdo);

/* ════════════════ مخطط الإصدار الثاني: الدعم الفني + سحب البطاقات + الخصم الإداري ════════════════ */
function ensureV2Schema(PDO $pdo): void
{
    // تذاكر الدعم الفني (كل تذكرة = محادثة مثل واتساب)
    $pdo->exec("CREATE TABLE IF NOT EXISTS support_tickets (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL,
        subject TEXT NOT NULL DEFAULT '',
        status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),
        unread_admin INTEGER NOT NULL DEFAULT 0,
        unread_customer INTEGER NOT NULL DEFAULT 0,
        last_msg_at TEXT DEFAULT CURRENT_TIMESTAMP,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        closed_at TEXT NULL,
        FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_tickets_customer ON support_tickets(customer_id, status)");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_tickets_last ON support_tickets(status, last_msg_at)");

    $pdo->exec("CREATE TABLE IF NOT EXISTS ticket_messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ticket_id INTEGER NOT NULL,
        sender TEXT NOT NULL CHECK(sender IN ('customer','staff','system')),
        sender_name TEXT DEFAULT '',
        body TEXT NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(ticket_id) REFERENCES support_tickets(id) ON DELETE CASCADE
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_tmsgs_ticket ON ticket_messages(ticket_id, id)");

    // سجل سحب البطاقات من الزبائن (يبقى محفوظاً حتى لو حُذفت البطاقة نفسها)
    $pdo->exec("CREATE TABLE IF NOT EXISTS card_withdrawals (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        card_id INTEGER NULL,
        card_number TEXT NOT NULL,
        category_name TEXT DEFAULT '',
        customer_id INTEGER NULL,
        customer_name TEXT DEFAULT '',
        returned_to_pool INTEGER NOT NULL DEFAULT 1,
        note TEXT DEFAULT '',
        withdrawn_by INTEGER NULL,
        withdrawn_by_name TEXT DEFAULT '',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )");
    $pdo->exec("CREATE INDEX IF NOT EXISTS idx_withdrawals_number ON card_withdrawals(card_number)");

    // توسيع أنواع حركات الرصيد لإضافة الخصم الإداري (deduct) — SQLite يتطلب إعادة بناء الجدول لتعديل CHECK
    try {
        $row = $pdo->query("SELECT sql FROM sqlite_master WHERE type='table' AND name='balance_transactions'")->fetch();
        if ($row && strpos($row['sql'], "'deduct'") === false) {
            $pdo->exec('PRAGMA foreign_keys = OFF');
            $pdo->exec('BEGIN');
            $pdo->exec("ALTER TABLE balance_transactions RENAME TO balance_transactions_old");
            $pdo->exec("CREATE TABLE balance_transactions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id INTEGER NOT NULL,
                type TEXT NOT NULL CHECK(type IN ('recharge','purchase','refund','receipt_credit','deduct')),
                amount REAL NOT NULL DEFAULT 0,
                balance_after REAL NOT NULL DEFAULT 0,
                note TEXT DEFAULT '',
                ref_sale_id INTEGER NULL,
                ref_receipt_id INTEGER NULL,
                user_id INTEGER NULL,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,
                FOREIGN KEY(ref_sale_id) REFERENCES sales(id) ON DELETE SET NULL,
                FOREIGN KEY(ref_receipt_id) REFERENCES payment_receipts(id) ON DELETE SET NULL,
                FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
            )");
            $pdo->exec("INSERT INTO balance_transactions (id, customer_id, type, amount, balance_after, note, ref_sale_id, ref_receipt_id, user_id, created_at)
                        SELECT id, customer_id, type, amount, balance_after, note, ref_sale_id, ref_receipt_id, user_id, created_at FROM balance_transactions_old");
            $pdo->exec("DROP TABLE balance_transactions_old");
            $pdo->exec("CREATE INDEX IF NOT EXISTS idx_balance_tx_customer ON balance_transactions(customer_id, created_at)");
            $pdo->exec('COMMIT');
            $pdo->exec('PRAGMA foreign_keys = ON');
        }
    } catch (Exception $e) {
        try { $pdo->exec('ROLLBACK'); } catch (Exception $e2) { /* صامت */ }
        try { $pdo->exec('PRAGMA foreign_keys = ON'); } catch (Exception $e3) { /* صامت */ }
    }

    // مدة صلاحية البطاقة بالساعات (لبدء العد التنازلي عند الدخول) — 0 يعني يُستنتج من اسم الفئة
    if (!columnExists($pdo, 'card_categories', 'duration_hours')) {
        $pdo->exec("ALTER TABLE card_categories ADD COLUMN duration_hours REAL NOT NULL DEFAULT 0");
    }
    // لحظة تفعيل البطاقة (أول ضغط على زر الدخول المباشر) — يبدأ منها العد التنازلي
    if (!columnExists($pdo, 'cards_pool', 'activated_at')) {
        $pdo->exec("ALTER TABLE cards_pool ADD COLUMN activated_at TEXT NULL");
    }
}
ensureV2Schema($pdo);

/* ════════════════ إعداد أولي (أول تشغيل: إنشاء حساب المالك) ════════════════ */
function ownerExists(PDO $pdo): bool
{
    $c = $pdo->query("SELECT COUNT(*) c FROM users WHERE role='owner'")->fetch();
    return intval($c['c'] ?? 0) > 0;
}

/* ════════════════ دوال مساعدة عامة ════════════════ */
function getClientIP(): string
{
    if (!empty($_SERVER['HTTP_CLIENT_IP'])) return $_SERVER['HTTP_CLIENT_IP'];
    if (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) return trim(explode(',', $_SERVER['HTTP_X_FORWARDED_FOR'])[0]);
    return $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
}

function sanitizeInput($data): string
{
    return htmlspecialchars(trim((string)$data), ENT_QUOTES, 'UTF-8');
}

function jsonResponse($data, $statusCode = 200): void
{
    http_response_code($statusCode);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($data, JSON_UNESCAPED_UNICODE);
    exit;
}

function money($n): string
{
    $n = floatval($n);
    return number_format($n, ($n == floor($n)) ? 0 : 2) . ' ' . CURRENCY;
}

function addAuditLog(PDO $pdo, string $action, string $details = ''): void
{
    try {
        $userName = $_SESSION['user']['full_name'] ?? 'نظام';
        $stmt = $pdo->prepare("INSERT INTO audit_logs (action, details, user_name, ip_address, created_at) VALUES (?, ?, ?, ?, ?)");
        $stmt->execute([$action, $details, $userName, getClientIP(), date('Y-m-d H:i:s')]);
    } catch (Exception $e) { /* صامت */ }
}

function generateInvoiceNo(PDO $pdo): string
{
    $y = date('y');
    $m = date('m');
    $prefix = "AN{$y}{$m}";
    $stmt = $pdo->prepare("SELECT invoice_no FROM sales WHERE invoice_no LIKE ? ORDER BY id DESC LIMIT 1");
    $stmt->execute([$prefix . '%']);
    $last = $stmt->fetch();
    $seq = 1;
    if ($last) {
        $seq = intval(substr($last['invoice_no'], strlen($prefix))) + 1;
    }
    return $prefix . str_pad((string)$seq, 4, '0', STR_PAD_LEFT);
}

/* ════════════════ Web Push (VAPID) — تنفيذ PHP خالص ════════════════ */
function b64url_encode(string $data): string
{
    return rtrim(strtr(base64_encode($data), '+/', '-_'), '=');
}
function b64url_decode(string $data): string
{
    return base64_decode(strtr($data, '-_', '+/') . str_repeat('=', (4 - strlen($data) % 4) % 4));
}

function getSetting(PDO $pdo, string $key, string $default = ''): string
{
    $stmt = $pdo->prepare("SELECT value FROM settings WHERE key = ?");
    $stmt->execute([$key]);
    $row = $stmt->fetch();
    return $row ? $row['value'] : $default;
}
function setSetting(PDO $pdo, string $key, string $value): void
{
    $stmt = $pdo->prepare("INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value");
    $stmt->execute([$key, $value]);
}

/* ════════════════ وضع الصيانة ════════════════ */
function isMaintenanceOn(PDO $pdo): bool
{
    return getSetting($pdo, 'maintenance_mode', '0') === '1';
}
function maintenanceMessage(PDO $pdo): string
{
    $m = trim(getSetting($pdo, 'maintenance_message', ''));
    return $m !== '' ? $m : 'نقوم حالياً ببعض أعمال الصيانة والتطوير — نعود إليكم قريباً بإذن الله 🛠️';
}
/** شاشة الصيانة الكاملة (تظهر لزبائن البوابة فقط — النظام يبقى متاحاً للموظفين) */
