/** توليد مفاتيح VAPID مرة واحدة وتخزينها في الإعدادات */
function ensureVapidKeys(PDO $pdo): array
{
    $pub = getSetting($pdo, 'vapid_public');
    $privPem = getSetting($pdo, 'vapid_private_pem');
    if ($pub !== '' && $privPem !== '') {
        return ['public' => $pub, 'private_pem' => $privPem];
    }
    $res = openssl_pkey_new(['curve_name' => 'prime256v1', 'private_key_type' => OPENSSL_KEYTYPE_EC]);
    if ($res === false) return ['public' => '', 'private_pem' => ''];
    openssl_pkey_export($res, $privPem);
    $details = openssl_pkey_get_details($res);
    // النقطة العامة غير المضغوطة: 0x04 || X(32) || Y(32)
    $x = str_pad($details['ec']['x'], 32, "\0", STR_PAD_LEFT);
    $y = str_pad($details['ec']['y'], 32, "\0", STR_PAD_LEFT);
    $pub = b64url_encode("\x04" . $x . $y);
    setSetting($pdo, 'vapid_public', $pub);
    setSetting($pdo, 'vapid_private_pem', $privPem);
    return ['public' => $pub, 'private_pem' => $privPem];
}

/** تحويل توقيع DER إلى صيغة raw r||s (64 بايت) المطلوبة في ES256 */
function derSigToRaw(string $der): string
{
    $offset = 2;
    if (ord($der[1]) & 0x80) $offset += ord($der[1]) & 0x7F;
    // r
    $offset += 1; // 0x02
    $rLen = ord($der[$offset]); $offset += 1;
    $r = substr($der, $offset, $rLen); $offset += $rLen;
    // s
    $offset += 1; // 0x02
    $sLen = ord($der[$offset]); $offset += 1;
    $s = substr($der, $offset, $sLen);
    $r = ltrim($r, "\0"); $s = ltrim($s, "\0");
    return str_pad($r, 32, "\0", STR_PAD_LEFT) . str_pad($s, 32, "\0", STR_PAD_LEFT);
}

/** JWT موقّع ES256 لترويسة VAPID */
function vapidJWT(string $audience, string $privPem, string $subject = 'mailto:admin@ansnet.local'): string
{
    $header = b64url_encode(json_encode(['typ' => 'JWT', 'alg' => 'ES256']));
    $payload = b64url_encode(json_encode([
        'aud' => $audience,
        'exp' => time() + 12 * 3600,
        'sub' => $subject,
    ]));
    $unsigned = $header . '.' . $payload;
    openssl_sign($unsigned, $sig, $privPem, OPENSSL_ALGO_SHA256);
    return $unsigned . '.' . b64url_encode(derSigToRaw($sig));
}

function hkdf_sha256(string $salt, string $ikm, string $info, int $length): string
{
    return hash_hkdf('sha256', $ikm, $length, $info, $salt);
}

/** تشفير حمولة الإشعار حسب RFC 8291 (aes128gcm) */
function encryptPushPayload(string $payload, string $clientP256dhB64, string $clientAuthB64): ?array
{
    $clientPub = b64url_decode($clientP256dhB64);   // 65 بايت نقطة غير مضغوطة
    $authSecret = b64url_decode($clientAuthB64);     // 16 بايت

    // مفتاح مؤقت للخادم
    $eph = openssl_pkey_new(['curve_name' => 'prime256v1', 'private_key_type' => OPENSSL_KEYTYPE_EC]);
    if ($eph === false) return null;
    $ephDetails = openssl_pkey_get_details($eph);
    $ephPub = "\x04" . str_pad($ephDetails['ec']['x'], 32, "\0", STR_PAD_LEFT) . str_pad($ephDetails['ec']['y'], 32, "\0", STR_PAD_LEFT);

    // مفتاح الزبون العام كـ PEM لاستخدامه في ECDH
    $x = substr($clientPub, 1, 32); $y = substr($clientPub, 33, 32);
    $derPrefix = hex2bin('3059301306072a8648ce3d020106082a8648ce3d030107034200');
    $clientPem = "-----BEGIN PUBLIC KEY-----\n" . chunk_split(base64_encode($derPrefix . "\x04" . $x . $y), 64, "\n") . "-----END PUBLIC KEY-----\n";

    $sharedSecret = openssl_pkey_derive(openssl_pkey_get_public($clientPem), $eph, 32);
    if ($sharedSecret === false) return null;

    // اشتقاق المفاتيح حسب RFC 8291
    $ikm = hkdf_sha256($authSecret, $sharedSecret, "WebPush: info\x00" . $clientPub . $ephPub, 32);
    $salt = random_bytes(16);
    $cek = hkdf_sha256($salt, $ikm, "Content-Encoding: aes128gcm\x00", 16);
    $nonce = hkdf_sha256($salt, $ikm, "Content-Encoding: nonce\x00", 12);

    // الحشو: بايت 0x02 يحدد نهاية السجل الأخير
    $plaintext = $payload . "\x02";
    $tag = '';
    $ciphertext = openssl_encrypt($plaintext, 'aes-128-gcm', $cek, OPENSSL_RAW_DATA, $nonce, $tag);
    if ($ciphertext === false) return null;

    // ترويسة الجسم: salt(16) | rs(4) | idlen(1) | keyid(65)
    $body = $salt . pack('N', 4096) . chr(65) . $ephPub . $ciphertext . $tag;
    return ['body' => $body];
}

/** إرسال إشعار Push لاشتراك واحد. يعيد true عند النجاح، و'gone' إذا انتهى الاشتراك */
function sendWebPush(PDO $pdo, array $subscription, array $notification)
{
    if (!function_exists('curl_init') || !function_exists('openssl_pkey_derive')) return false;
    $keys = ensureVapidKeys($pdo);
    if ($keys['public'] === '') return false;

    $endpoint = $subscription['endpoint'];
    $parts = parse_url($endpoint);
    $audience = $parts['scheme'] . '://' . $parts['host'];

    $payload = json_encode($notification, JSON_UNESCAPED_UNICODE);
    $enc = encryptPushPayload($payload, $subscription['p256dh'], $subscription['auth']);
    if ($enc === null) return false;

    $jwt = vapidJWT($audience, $keys['private_pem']);

    $ch = curl_init($endpoint);
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => $enc['body'],
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 10,
        CURLOPT_HTTPHEADER => [
            'TTL: 86400',
            'Content-Encoding: aes128gcm',
            'Content-Type: application/octet-stream',
            'Content-Length: ' . strlen($enc['body']),
            'Authorization: vapid t=' . $jwt . ', k=' . $keys['public'],
            'Urgency: high',
        ],
    ]);
    curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    if ($code === 404 || $code === 410) return 'gone';
    return $code >= 200 && $code < 300;
}

/** إنشاء إشعار داخلي لزبون + محاولة إرساله Push لكل أجهزته */
function notifyCustomer(PDO $pdo, int $customerId, string $title, string $body = ''): void
{
    $stmt = $pdo->prepare("INSERT INTO customer_notifications (customer_id, title, body, created_at) VALUES (?, ?, ?, ?)");
    $stmt->execute([$customerId, $title, $body, date('Y-m-d H:i:s')]);

    try {
        $subs = $pdo->prepare("SELECT * FROM push_subscriptions WHERE customer_id = ?");
        $subs->execute([$customerId]);
        foreach ($subs->fetchAll() as $sub) {
            $result = sendWebPush($pdo, $sub, ['title' => $title, 'body' => $body]);
            if ($result === 'gone') {
                $pdo->prepare("DELETE FROM push_subscriptions WHERE id = ?")->execute([$sub['id']]);
            }
        }
    } catch (Exception $e) { /* الإشعار الداخلي محفوظ حتى لو فشل الـ Push */ }
}

/**
 * تعديل رصيد زبون بأمان (شحن أو خصم) مع تسجيل الحركة بالكامل.
 * $amount موجب دائماً؛ $type يحدد إن كانت إضافة (recharge/refund/receipt_credit) أو خصم (purchase).
 * يجب استدعاؤها داخل transaction عند استخدامها ضمن عملية أكبر (مثل الشراء).
 * ترجع الرصيد الجديد، أو تطلق Exception إذا كان الخصم سيجعل الرصيد سالباً.
 */
function adjustCustomerBalance(PDO $pdo, int $customerId, string $type, float $amount, string $note = '', ?int $userId = null, ?int $refSaleId = null, ?int $refReceiptId = null): float
{
    $amount = round($amount, 2);
    if ($amount <= 0) throw new InvalidArgumentException('المبلغ يجب أن يكون أكبر من صفر');

    $isDebit = ($type === 'purchase' || $type === 'deduct');
    $signed = $isDebit ? -$amount : $amount;

    // قفل صف الزبون ضمن نفس المعاملة لمنع تعارض السباق (Race Condition)
    $row = $pdo->prepare("SELECT balance FROM customers WHERE id = ?");
    $row->execute([$customerId]);
    $cur = $row->fetch();
    if (!$cur) throw new RuntimeException('الزبون غير موجود');

    $newBalance = round(floatval($cur['balance']) + $signed, 2);
    if ($newBalance < -0.009) {
        throw new RuntimeException('الرصيد غير كافٍ');
    }

    $pdo->prepare("UPDATE customers SET balance = ? WHERE id = ?")->execute([$newBalance, $customerId]);
    $pdo->prepare("INSERT INTO balance_transactions (customer_id, type, amount, balance_after, note, ref_sale_id, ref_receipt_id, user_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
        ->execute([$customerId, $type, $amount, $newBalance, $note, $refSaleId, $refReceiptId, $userId, date('Y-m-d H:i:s')]);

    return $newBalance;
}

