function customerOpenDebt(PDO $pdo, int $customerId): float
{
    $stmt = $pdo->prepare("SELECT COALESCE(SUM(remaining_amount),0) t FROM debts WHERE customer_id = ? AND status != 'paid'");
    $stmt->execute([$customerId]);
    return floatval($stmt->fetch()['t'] ?? 0);
}

