/**
 * قائمة كل الصلاحيات القابلة للتفعيل لكل موظف على حدة.
 * المالك (owner) دائماً يملك كل الصلاحيات بلا استثناء.
 */
const ALL_PERMISSIONS = [
    'sales.create'      => 'تسجيل عمليات بيع جديدة',
    'sales.view'        => 'عرض سجل المبيعات',
    'sales.delete'      => 'حذف/تعديل عمليات بيع',
    'customers.manage'  => 'إدارة الزبائن (إضافة/تعديل)',
    'customers.view'    => 'عرض قائمة الزبائن',
    'debts.manage'      => 'إدارة الديون والتسديدات',
    'debts.view'        => 'عرض سجل الديون',
    'expenses.manage'   => 'تسجيل المصاريف',
    'expenses.view'     => 'عرض المصاريف',
    'inventory.manage'  => 'إدارة المخزون والفئات',
    'inventory.view'    => 'عرض المخزون',
    'reports.view'      => 'عرض التقارير والأرباح',
    'employees.manage'  => 'إدارة الموظفين وصلاحياتهم',
    'settings.manage'   => 'تعديل إعدادات النظام',
    'support.manage'    => 'الدعم الفني والرد على تذاكر الزبائن',
];

function getUserPermissions(array $user): array
{
    if (($user['role'] ?? '') === 'owner') {
        return array_fill_keys(array_keys(ALL_PERMISSIONS), true);
    }
    $perms = json_decode($user['permissions'] ?? '{}', true);
    return is_array($perms) ? $perms : [];
}

function can(string $permKey): bool
{
    if (empty($_SESSION['user'])) return false;
    $perms = getUserPermissions($_SESSION['user']);
    return !empty($perms[$permKey]);
}

function requirePermission(string $permKey): void
{
    if (!can($permKey)) {
        jsonResponse(['success' => false, 'message' => 'ليس لديك صلاحية لتنفيذ هذا الإجراء'], 403);
    }
}

/* ════════════════ المصادقة (Auth) ════════════════ */
function isLoggedIn(): bool
{
    return !empty($_SESSION['user']) && !empty($_SESSION['user']['id']);
}

function currentUser(): ?array
{
    return $_SESSION['user'] ?? null;
}

function loginUser(PDO $pdo, string $username, string $password): array
{
    $stmt = $pdo->prepare("SELECT * FROM users WHERE username = ? LIMIT 1");
    $stmt->execute([$username]);
    $user = $stmt->fetch();
    if (!$user) return ['success' => false, 'message' => 'اسم المستخدم أو كلمة المرور غير صحيحة'];
    if (!intval($user['is_active'])) return ['success' => false, 'message' => 'هذا الحساب موقوف. تواصل مع المالك'];
    if (!password_verify($password, $user['password_hash'])) {
        return ['success' => false, 'message' => 'اسم المستخدم أو كلمة المرور غير صحيحة'];
    }
    $upd = $pdo->prepare("UPDATE users SET last_login = ? WHERE id = ?");
    $upd->execute([date('Y-m-d H:i:s'), $user['id']]);
    unset($user['password_hash']);
    $_SESSION['user'] = $user;
    addAuditLog($pdo, 'تسجيل دخول', $user['full_name']);
    return ['success' => true, 'user' => $user];
}

function logoutUser(PDO $pdo): void
{
    if (!empty($_SESSION['user'])) {
        addAuditLog($pdo, 'تسجيل خروج', $_SESSION['user']['full_name'] ?? '');
    }
    $_SESSION = [];
    if (ini_get("session.use_cookies")) {
        $p = session_get_cookie_params();
        setcookie(session_name(), '', time() - 42000, $p["path"], $p["domain"], $p["secure"], $p["httponly"]);
    }
    session_destroy();
}

/* استنتاج مدة البطاقة بالساعات من اسم الفئة عند عدم ضبطها يدوياً (مثال: «بطاقة 24 ساعة»، «10 ساعات»، «يوم»، «30 دقيقة») */
function parseDurationHours(string $name): float
{
    // تحويل الأرقام العربية إلى إنجليزية
    $name = strtr($name, ['٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']);
    if (preg_match('/(\d+(?:\.\d+)?)\s*(دقيقة|دقايق|دقائق|min|m\b)/u', $name, $m)) return round(((float)$m[1]) / 60, 4);
    if (preg_match('/(\d+(?:\.\d+)?)\s*(ساعة|ساعه|ساعات|hr|hour|h\b)/u', $name, $m)) return (float)$m[1];
    if (preg_match('/(\d+(?:\.\d+)?)\s*(يوم|ايام|أيام|day|d\b)/u', $name, $m)) return ((float)$m[1]) * 24;
    if (preg_match('/(\d+(?:\.\d+)?)\s*(اسبوع|أسبوع|week|w\b)/u', $name, $m)) return ((float)$m[1]) * 24 * 7;
    if (preg_match('/(\d+(?:\.\d+)?)\s*(شهر|شهور|month)/u', $name, $m)) return ((float)$m[1]) * 24 * 30;
    // اسم يحوي رقماً فقط بلا وحدة → يُعتبر ساعات
    if (preg_match('/(?<!\d)(\d{1,3})(?!\d)/', $name, $m)) return (float)$m[1];
    return 0;
}

/* المدة الفعلية للبطاقة: القيمة المضبوطة يدوياً وإلا المُستنتجة من الاسم */
function effectiveDurationHours($durationHours, string $categoryName): float
{
    $d = (float)$durationHours;
    if ($d > 0) return $d;
    return parseDurationHours($categoryName);
}

/* هل يوجد شعار مخصّص رفعه المالك؟ */
function hasCustomIcon(PDO $pdo): bool
{
    return getSetting($pdo, 'custom_icon', '') !== '';
}

/* شعار العلامة الظاهر في الواجهة: صورة المالك المرفوعة إن وُجدت، وإلا أيقونة افتراضية */
function brandMark(PDO $pdo, string $glyph): string
{
    if (hasCustomIcon($pdo)) {
        $iconV = getSetting($pdo, 'icon_version', '1');
        return '<img src="?action=icon&s=192&v=' . htmlspecialchars($iconV, ENT_QUOTES) . '" alt="" style="width:100%;height:100%;object-fit:contain;border-radius:inherit;display:block;">';
    }
    return '<i class="ph-duotone ' . htmlspecialchars($glyph, ENT_QUOTES) . '"></i>';
}

/* ════════════════ توجيه الصفحات والـ API ════════════════ */
$action = $_GET['action'] ?? $_POST['action'] ?? '';
$page = $_GET['page'] ?? 'dashboard';

/* ─── نقاط الـ API (JSON) ─── */
if ($action !== '') {
    /* ════════ محتوى الـ API مدموج هنا ════════ */

/* ─── أيقونة التطبيق PNG (مطلوبة ليُثبَّت كتطبيق حقيقي على أندرويد وiOS) ─── */
if ($action === 'icon') {
    $size = intval($_GET['s'] ?? 192);
    if ($size < 48 || $size > 1024) $size = 192;
    header('Cache-Control: public, max-age=86400');

    // شارة الإشعارات أحادية اللون (أندرويد) — Silhouette بيضاء شفافة
    if (intval($_GET['badge'] ?? 0) === 1) {
        header('Content-Type: image/png');
        echo base64_decode(APP_BADGE_B64);
        exit;
    }

    // أولوية 1: أيقونة مخصّصة رفعها المالك من جهازه · أولوية 2: شعار Cards Sohaib المدمج
    $custom = getSetting($pdo, 'custom_icon', '');
    $mime = 'image/png';
    $raw = false;
    if ($custom !== '') {
        $raw = base64_decode($custom, true);
        $mime = getSetting($pdo, 'custom_icon_mime', 'image/png') ?: 'image/png';
    }
    if ($raw === false || $raw === '' || $custom === '') {
        $raw = base64_decode(APP_LOGO_B64);
        $mime = 'image/png';
    }

    // تحجيم بالمقاس المطلوب مع الحفاظ على النسبة (إن توفرت مكتبة GD)
    if (function_exists('imagecreatefromstring')) {
        $srcImg = @imagecreatefromstring($raw);
        if ($srcImg !== false) {
            $w = imagesx($srcImg); $h = imagesy($srcImg);
            $dst = imagecreatetruecolor($size, $size);
            imagesavealpha($dst, true);
            imagealphablending($dst, false);
            $transparent = imagecolorallocatealpha($dst, 0, 0, 0, 127);
            imagefill($dst, 0, 0, $transparent);
            imagealphablending($dst, true);
            $scale = min($size / max(1, $w), $size / max(1, $h));
            $nw = max(1, (int)round($w * $scale)); $nh = max(1, (int)round($h * $scale));
            imagecopyresampled($dst, $srcImg, (int)(($size - $nw) / 2), (int)(($size - $nh) / 2), 0, 0, $nw, $nh, $w, $h);
            header('Content-Type: image/png');
            imagepng($dst);
            imagedestroy($dst); imagedestroy($srcImg);
            exit;
        }
    }
    header('Content-Type: ' . $mime);
    echo $raw;
    exit;
}

