/* ─── Service Worker (يُقدَّم كجافاسكريبت من نفس الملف) ─── */
if ($action === 'sw') {
    header('Content-Type: application/javascript; charset=utf-8');
    header('Service-Worker-Allowed: ./');
    $iconV = getSetting($pdo, 'icon_version', '1');
    ?>
// اسم الكاش يحمل نسخة الأيقونة: أي تغيير للشعار يُبطل الكاش القديم تلقائياً فيظهر الشعار الجديد فوراً
const CACHE_NAME = 'ansnet-v5-icon<?php echo preg_replace('/[^0-9]/', '', $iconV) ?: '1'; ?>';
const CDN_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com'];
const PRECACHE = ['./', '?action=manifest', '?action=icon&s=192&v=<?php echo (int)$iconV; ?>', '?action=icon&s=512&v=<?php echo (int)$iconV; ?>'];

self.addEventListener('install', (event) => {
    event.waitUntil((async () => {
        try {
            const cache = await caches.open(CACHE_NAME);
            await Promise.all(PRECACHE.map(u => cache.add(u).catch(() => {})));
        } catch (e) {}
        await self.skipWaiting();
    })());
});

self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
        const keys = await caches.keys();
        await Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)));
        await self.clients.claim();
    })());
});

self.addEventListener('fetch', (event) => {
    const req = event.request;
    const url = new URL(req.url);

    // لا نتدخل في طلبات POST (عمليات الحفظ) — تُدار من طابور المزامنة في الواجهة
    if (req.method !== 'GET') return;

    // موارد CDN (خطوط/أيقونات): كاش أولاً — أساس العمل بدون نت
    if (CDN_HOSTS.includes(url.hostname)) {
        event.respondWith((async () => {
            const cached = await caches.match(req);
            if (cached) return cached;
            try {
                const res = await fetch(req);
                if (res && (res.ok || res.type === 'opaque')) {
                    const cache = await caches.open(CACHE_NAME);
                    cache.put(req, res.clone());
                }
                return res;
            } catch (e) {
                return cached || Response.error();
            }
        })());
        return;
    }

    // تنقّل الصفحات: شبكة أولاً مع الرجوع للكاش عند انقطاع النت
    if (req.mode === 'navigate') {
        event.respondWith((async () => {
            try {
                const res = await fetch(req);
                const cache = await caches.open(CACHE_NAME);
                cache.put(req, res.clone());
                return res;
            } catch (e) {
                const cached = await caches.match(req) || await caches.match('./');
                return cached || new Response('<h1 dir="rtl">لا يوجد اتصال ولا نسخة محفوظة بعد — افتح التطبيق مرة واحدة وأنت متصل</h1>', { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
            }
        })());
        return;
    }

    // طلبات القراءة من الـ API (قوائم): شبكة أولاً مع كاش احتياطي
    if (url.searchParams.has('action')) {
        event.respondWith((async () => {
            try {
                const res = await fetch(req);
                if (res.ok) {
                    const cache = await caches.open(CACHE_NAME);
                    cache.put(req, res.clone());
                }
                return res;
            } catch (e) {
                const cached = await caches.match(req);
                return cached || new Response(JSON.stringify({ success: false, offline: true, message: 'أنت بدون اتصال' }), { headers: { 'Content-Type': 'application/json' } });
            }
        })());
        return;
    }
});

// استقبال إشعارات Push وعرضها حتى والتطبيق مغلق
self.addEventListener('push', (event) => {
    let data = { title: 'إشعار جديد', body: '' };
    try { data = event.data.json(); } catch (e) {}
    event.waitUntil(self.registration.showNotification(data.title || 'إشعار', {
        body: data.body || '',
        icon: './?action=icon&s=192',
        badge: './?action=icon&badge=1',
        dir: 'rtl',
        lang: 'ar',
        vibrate: [200, 100, 200],
        data: { url: './?page=portal' },
    }));
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    event.waitUntil((async () => {
        const all = await clients.matchAll({ type: 'window', includeUncontrolled: true });
        for (const c of all) { if ('focus' in c) return c.focus(); }
        return clients.openWindow(event.notification.data?.url || './');
    })());
});
    <?php
    exit;
}

