header('Content-Type: application/json; charset=utf-8');

/* ─── الإعداد الأولي: إنشاء حساب المالك (متاح مرة واحدة فقط) ─── */
if ($action === 'setup_owner') {
    if (ownerExists($pdo)) jsonResponse(['success' => false, 'message' => 'تم إعداد النظام مسبقاً'], 400);
    $fullName = sanitizeInput($_POST['full_name'] ?? '');
    $username = trim($_POST['username'] ?? '');
    $password = (string)($_POST['password'] ?? '');
    if ($fullName === '' || $username === '' || strlen($password) < 4) {
        jsonResponse(['success' => false, 'message' => 'يرجى تعبئة جميع الحقول (كلمة المرور 4 أحرف على الأقل)'], 400);
    }
    $hash = password_hash($password, PASSWORD_DEFAULT);
    $stmt = $pdo->prepare("INSERT INTO users (username, password_hash, full_name, role, permissions, avatar_color) VALUES (?, ?, ?, 'owner', '{}', '#6C43FF')");
    try {
        $stmt->execute([$username, $hash, $fullName]);
    } catch (PDOException $e) {
        jsonResponse(['success' => false, 'message' => 'اسم المستخدم هذا محجوز بالفعل'], 400);
    }
    // إعدادات افتراضية
    $pdo->prepare("INSERT OR IGNORE INTO settings (key, value) VALUES ('shop_name', ?)")->execute([APP_NAME]);
    loginUser($pdo, $username, $password);
    addAuditLog($pdo, 'إعداد النظام', 'تم إنشاء حساب المالك الأول');
    jsonResponse(['success' => true]);
}

/* ─── تسجيل الدخول الموحّد: موظف/مالك أولاً، وإن لم يوجد → حساب زبون ─── */
if ($action === 'login') {
    $username = trim($_POST['username'] ?? '');
    $password = (string)($_POST['password'] ?? '');
    if ($username === '' || $password === '') {
        jsonResponse(['success' => false, 'message' => 'يرجى إدخال اسم المستخدم وكلمة المرور'], 400);
    }
    // 1) محاولة كموظف/مالك
    $result = loginUser($pdo, $username, $password);
    if ($result['success']) {
        $result['kind'] = 'staff';
        jsonResponse($result, 200);
    }
    // 2) محاولة كحساب زبون (بوابة) — تُحجب أثناء وضع الصيانة
    $cStmt = $pdo->prepare("SELECT * FROM customers WHERE username = ? LIMIT 1");
    $cStmt->execute([$username]);
    $c = $cStmt->fetch();
    if ($c && !empty($c['password_hash']) && password_verify($password, $c['password_hash'])) {
        if (isMaintenanceOn($pdo)) {
            addAuditLog($pdo, 'دخول زبون مرفوض (صيانة)', $c['full_name'] . ' (@' . $username . ')');
            jsonResponse(['success' => false, 'maintenance' => true, 'message' => maintenanceMessage($pdo)], 503);
        }
        if (intval($c['is_blocked'])) {
            addAuditLog($pdo, 'محاولة دخول لحساب محظور', $c['full_name'] . ' (@' . $username . ')');
            jsonResponse(['success' => false, 'message' => 'هذا الحساب محظور. تواصل مع الإدارة'], 403);
        }
        $_SESSION['customer'] = ['id' => intval($c['id']), 'full_name' => $c['full_name'], 'username' => $c['username'], 'phone' => $c['phone']];
        addAuditLog($pdo, 'دخول زبون (موحّد)', $c['full_name']);
        jsonResponse(['success' => true, 'kind' => 'customer'], 200);
    }
    addAuditLog($pdo, 'محاولة دخول فاشلة', 'اسم المستخدم المُدخل: ' . mb_substr($username, 0, 40));
    jsonResponse(['success' => false, 'message' => 'اسم المستخدم أو كلمة المرور غير صحيحة'], 401);
}

/* ─── تسجيل الخروج ─── */
if ($action === 'logout') {
    logoutUser($pdo);
    jsonResponse(['success' => true]);
}

/* ═══════════════════ بوابة الزبائن: التسجيل والدخول (عام) ═══════════════════ */
if ($action === 'portal_register') {
    if (isMaintenanceOn($pdo)) jsonResponse(['success' => false, 'maintenance' => true, 'message' => maintenanceMessage($pdo)], 503);
    $fullName = sanitizeInput($_POST['full_name'] ?? '');
    $username = trim($_POST['username'] ?? '');
    $phone = preg_replace('/[^0-9]/', '', $_POST['phone'] ?? '');
    $password = (string)($_POST['password'] ?? '');
    $passwordConfirm = (string)($_POST['password_confirm'] ?? '');

    // الاسم رباعي: أربع كلمات على الأقل
    $nameParts = preg_split('/\s+/', trim($fullName), -1, PREG_SPLIT_NO_EMPTY);
    if (count($nameParts) < 4) {
        jsonResponse(['success' => false, 'message' => 'يرجى كتابة الاسم الرباعي كاملاً (أربع كلمات على الأقل)'], 400);
    }
    if (!preg_match('/^[a-zA-Z0-9_.]{3,30}$/', $username)) {
        jsonResponse(['success' => false, 'message' => 'اسم المستخدم: أحرف إنجليزية وأرقام فقط (3 أحرف على الأقل)'], 400);
    }
    // رقم واتساب بالمقدمة الدولية: لا يبدأ بصفر، 10-15 رقم
    if (strlen($phone) < 10 || strlen($phone) > 15 || $phone[0] === '0') {
        jsonResponse(['success' => false, 'message' => 'رقم الواتساب يجب أن يكون بالمقدمة الدولية (مثال: 970599XXXXXX)'], 400);
    }
    if (strlen($password) < 4) {
        jsonResponse(['success' => false, 'message' => 'كلمة المرور يجب أن تكون 4 أحرف على الأقل'], 400);
    }
    if ($password !== $passwordConfirm) {
        jsonResponse(['success' => false, 'message' => 'كلمتا المرور غير متطابقتين'], 400);
    }

    $exists = $pdo->prepare("SELECT id FROM customers WHERE username = ?");
    $exists->execute([$username]);
    if ($exists->fetch()) {
        jsonResponse(['success' => false, 'message' => 'اسم المستخدم هذا محجوز، اختر غيره'], 400);
    }

    $hash = password_hash($password, PASSWORD_DEFAULT);
    $stmt = $pdo->prepare("INSERT INTO customers (full_name, phone, username, password_hash, registered_at, created_at) VALUES (?, ?, ?, ?, ?, ?)");
    $now = date('Y-m-d H:i:s');
    $stmt->execute([$fullName, $phone, $username, $hash, $now, $now]);
    $newId = intval($pdo->lastInsertId());

    $_SESSION['customer'] = ['id' => $newId, 'full_name' => $fullName, 'username' => $username, 'phone' => $phone];
    addAuditLog($pdo, 'تسجيل زبون جديد (بوابة)', $fullName);
    jsonResponse(['success' => true]);
}

if ($action === 'portal_login') {
    $username = trim($_POST['username'] ?? '');
    $password = (string)($_POST['password'] ?? '');
    if ($username === '' || $password === '') {
        jsonResponse(['success' => false, 'message' => 'يرجى إدخال اسم المستخدم وكلمة المرور'], 400);
    }
    if (isMaintenanceOn($pdo)) jsonResponse(['success' => false, 'maintenance' => true, 'message' => maintenanceMessage($pdo)], 503);
    $stmt = $pdo->prepare("SELECT * FROM customers WHERE username = ? LIMIT 1");
    $stmt->execute([$username]);
    $c = $stmt->fetch();
    if (!$c || empty($c['password_hash']) || !password_verify($password, $c['password_hash'])) {
        addAuditLog($pdo, 'محاولة دخول فاشلة (بوابة)', 'اسم المستخدم المُدخل: ' . mb_substr($username, 0, 40));
        jsonResponse(['success' => false, 'message' => 'اسم المستخدم أو كلمة المرور غير صحيحة'], 401);
    }
    if (intval($c['is_blocked'])) {
        addAuditLog($pdo, 'محاولة دخول لحساب محظور (بوابة)', $c['full_name'] . ' (@' . $username . ')');
        jsonResponse(['success' => false, 'message' => 'هذا الحساب محظور. تواصل مع الإدارة'], 403);
    }
    $_SESSION['customer'] = ['id' => intval($c['id']), 'full_name' => $c['full_name'], 'username' => $c['username'], 'phone' => $c['phone']];
    addAuditLog($pdo, 'دخول زبون (بوابة)', $c['full_name']);
    jsonResponse(['success' => true]);
}

if ($action === 'portal_logout') {
    unset($_SESSION['customer']);
    jsonResponse(['success' => true]);
}

/* ═══════════════════ بوابة الزبائن: يتطلب جلسة زبون ═══════════════════ */
if (strpos($action, 'portal_') === 0) {
    if (!isCustomerLoggedIn()) {
        jsonResponse(['success' => false, 'message' => 'الرجاء تسجيل الدخول أولاً'], 401);
    }
    $customer = currentCustomer();
    $customerId = intval($customer['id']);

    /* — وضع الصيانة: تُوقَف كل خدمات البوابة مؤقتاً — */
    if (isMaintenanceOn($pdo)) {
        jsonResponse(['success' => false, 'maintenance' => true, 'message' => maintenanceMessage($pdo)], 503);
    }

    /* — ملخص الزبون الكامل: الدين، البطاقات، الإشعارات، أرقام الدفع، حالة الحجب — */
    if ($action === 'portal_me') {
        $cRow = $pdo->prepare("SELECT id, full_name, username, phone, portal_block_debt, portal_show_debt, is_blocked, balance FROM customers WHERE id = ?");
        $cRow->execute([$customerId]);
        $me = $cRow->fetch();
        if (!$me) jsonResponse(['success' => false, 'message' => 'الحساب غير موجود'], 404);

        $openDebt = customerOpenDebt($pdo, $customerId);

        $debts = $pdo->prepare("SELECT id, original_amount, remaining_amount, due_date, status, note, created_at FROM debts WHERE customer_id = ? AND status != 'paid' ORDER BY created_at DESC");
        $debts->execute([$customerId]);

        $cards = $pdo->prepare("SELECT cp.id, cp.card_number, cp.sent_at, cp.activated_at, cc.name AS category_name, cc.color AS category_color, cc.duration_hours
                                FROM cards_pool cp LEFT JOIN card_categories cc ON cc.id = cp.category_id
                                WHERE cp.sent_to_customer_id = ? ORDER BY cp.sent_at DESC LIMIT 100");
        $cards->execute([$customerId]);
        // تجهيز البطاقات: احتساب المدة الفعلية ولحظة الانتهاء، وإخفاء المنتهية منذ أكثر من 72 ساعة
        $cardsOut = [];
        $nowTs = time();
        foreach ($cards->fetchAll() as $cd) {
            $durHours = effectiveDurationHours($cd['duration_hours'] ?? 0, (string)($cd['category_name'] ?? ''));
            $activatedTs = !empty($cd['activated_at']) ? strtotime($cd['activated_at']) : 0;
            $expiresTs = ($activatedTs && $durHours > 0) ? ($activatedTs + (int)round($durHours * 3600)) : 0;
            // إخفاء البطاقة نهائياً بعد مرور 72 ساعة على انتهائها
            if ($expiresTs && $nowTs > ($expiresTs + 72 * 3600)) continue;
            $cardsOut[] = [
                'id'            => (int)$cd['id'],
                'card_number'   => $cd['card_number'],
                'sent_at'       => $cd['sent_at'],
                'category_name' => $cd['category_name'],
                'category_color'=> $cd['category_color'],
                'duration_hours'=> $durHours,
                'activated_at'  => $cd['activated_at'],
                'expires_ts'    => $expiresTs, // بالثواني (توقيت الخادم) — 0 يعني غير مُفعّلة أو بلا مدة
                'server_now'    => $nowTs,
            ];
        }

        $notifs = $pdo->prepare("SELECT id, title, body, is_read, created_at FROM customer_notifications WHERE customer_id = ? ORDER BY created_at DESC LIMIT 50");
        $notifs->execute([$customerId]);

        $requests = $pdo->prepare("SELECT pr.id, pr.quantity, pr.note, pr.status, pr.created_at, cc.name AS category_name
                                   FROM purchase_requests pr LEFT JOIN card_categories cc ON cc.id = pr.category_id
                                   WHERE pr.customer_id = ? ORDER BY pr.created_at DESC LIMIT 30");
        $requests->execute([$customerId]);

        $receipts = $pdo->prepare("SELECT id, method, amount, status, review_note, created_at FROM payment_receipts WHERE customer_id = ? ORDER BY created_at DESC LIMIT 30");
        $receipts->execute([$customerId]);

        $cats = $pdo->query("SELECT cc.id, cc.name, cc.default_sell_price, cc.color, cc.icon,
                                    (SELECT COUNT(*) FROM cards_pool WHERE category_id = cc.id AND status = 'available') AS stock_available
                             FROM card_categories cc WHERE cc.is_active = 1 ORDER BY cc.name");

        $balanceTx = $pdo->prepare("SELECT type, amount, balance_after, note, created_at FROM balance_transactions WHERE customer_id = ? ORDER BY id DESC LIMIT 30");
        $balanceTx->execute([$customerId]);

        $tickets = $pdo->prepare("SELECT t.id, t.subject, t.status, t.unread_customer, t.last_msg_at, t.created_at,
                                         (SELECT body FROM ticket_messages WHERE ticket_id = t.id ORDER BY id DESC LIMIT 1) AS last_body,
                                         (SELECT sender FROM ticket_messages WHERE ticket_id = t.id ORDER BY id DESC LIMIT 1) AS last_sender
                                  FROM support_tickets t WHERE t.customer_id = ? ORDER BY t.last_msg_at DESC LIMIT 50");
        $tickets->execute([$customerId]);

        $blockedForDebt = intval($me['portal_block_debt']) === 1 && $openDebt > 0;

        jsonResponse([
            'success' => true,
            'me' => ['id' => $me['id'], 'full_name' => $me['full_name'], 'username' => $me['username'], 'phone' => $me['phone']],
            'balance' => floatval($me['balance']),
            'open_debt' => $openDebt,
            'blocked_for_debt' => $blockedForDebt,
            'show_debt' => intval($me['portal_show_debt'] ?? 0),
            'debts' => $debts->fetchAll(),
            'cards' => $cardsOut,
            'server_now' => $nowTs,
            'notifications' => $notifs->fetchAll(),
            'requests' => $requests->fetchAll(),
            'receipts' => $receipts->fetchAll(),
            'categories' => $cats->fetchAll(),
            'balance_transactions' => $balanceTx->fetchAll(),
            'tickets' => $tickets->fetchAll(),
            'payment_methods' => [
                ['method' => 'palpay', 'label' => 'محفظة PalPay', 'number' => '0599038268', 'note' => 'حوّل عبر تطبيق محفظتي PalPay ثم ارفق صورة الإشعار'],
                ['method' => 'jawwalpay', 'label' => 'محفظة Jawwal Pay', 'number' => '0597035178', 'note' => 'حوّل عبر تطبيق Jawwal Pay ثم ارفق صورة الإشعار'],
            ],
            'vapid_public' => ensureVapidKeys($pdo)['public'],
        ]);
    }

    /* — تفعيل بطاقة: يُسجّل لحظة أول ضغط على «دخول مباشر» ليبدأ منها العد التنازلي (مرة واحدة فقط) — */
    if ($action === 'portal_activate_card') {
        $cardId = intval($_POST['card_id'] ?? 0);
        if ($cardId <= 0) jsonResponse(['success' => false, 'message' => 'بطاقة غير صالحة'], 400);
        // التفعيل يحدث مرة واحدة فقط ولا يُعاد ضبطه عند الضغط لاحقاً
        $stmt = $pdo->prepare("UPDATE cards_pool SET activated_at = ? WHERE id = ? AND sent_to_customer_id = ? AND activated_at IS NULL");
        $stmt->execute([date('Y-m-d H:i:s'), $cardId, $customerId]);
        // نُرجع لحظة التفعيل الحالية (سواء فُعّلت الآن أو سابقاً)
        $row = $pdo->prepare("SELECT activated_at FROM cards_pool WHERE id = ? AND sent_to_customer_id = ?");
        $row->execute([$cardId, $customerId]);
        $r = $row->fetch();
        jsonResponse(['success' => true, 'activated_at' => $r['activated_at'] ?? null, 'server_now' => time()]);
    }

    /* — شراء بطاقة مباشرة بالرصيد: يخصم الرصيد فوراً ويسلّم رقم بطاقة حقيقي من المخزن — */
    if ($action === 'portal_buy_card') {
        $categoryId = intval($_POST['category_id'] ?? 0);
        $qty = max(1, min(10, intval($_POST['quantity'] ?? 1)));
        if ($categoryId <= 0) jsonResponse(['success' => false, 'message' => 'اختر نوع البطاقة'], 400);

        // تحقّق من الحجب بسبب الدين
        $blockRow = $pdo->prepare("SELECT portal_block_debt FROM customers WHERE id = ?");
        $blockRow->execute([$customerId]);
        $blockVal = $blockRow->fetch();
        if ($blockVal && intval($blockVal['portal_block_debt']) === 1 && customerOpenDebt($pdo, $customerId) > 0) {
            jsonResponse(['success' => false, 'message' => 'حسابك محجوب حتى سداد الدين المستحق'], 403);
        }

        $cat = $pdo->prepare("SELECT * FROM card_categories WHERE id = ? AND is_active = 1");
        $cat->execute([$categoryId]);
        $category = $cat->fetch();
        if (!$category) jsonResponse(['success' => false, 'message' => 'هذا النوع غير متاح حالياً'], 404);

        $unitPrice = floatval($category['default_sell_price']);
        if ($unitPrice <= 0) jsonResponse(['success' => false, 'message' => 'سعر هذه الفئة غير مُهيّأ، تواصل مع الإدارة'], 400);
        $totalPrice = round($unitPrice * $qty, 2);

        $custRow = $pdo->prepare("SELECT balance FROM customers WHERE id = ?");
        $custRow->execute([$customerId]);
        $curBalance = floatval(($custRow->fetch() ?: ['balance' => 0])['balance']);
        if ($curBalance + 0.009 < $totalPrice) {
            jsonResponse(['success' => false, 'message' => 'رصيدك غير كافٍ لإتمام الشراء. رصيدك الحالي: ' . money($curBalance) . '، المطلوب: ' . money($totalPrice) . '. الرجاء شحن رصيدك أولاً من تبويب الدفع'], 400);
        }

        $pdo->beginTransaction();
        try {
            // حجز الكمية المطلوبة من المخزن المتاح لنفس الفئة (FIFO) مع قفل ضد التعارض
            $pick = $pdo->prepare("SELECT * FROM cards_pool WHERE status = 'available' AND category_id = ? ORDER BY id ASC LIMIT " . intval($qty));
            $pick->execute([$categoryId]);
            $picked = $pick->fetchAll();
            if (count($picked) < $qty) {
                $pdo->rollBack();
                jsonResponse(['success' => false, 'message' => 'الكمية المتوفرة من هذا النوع غير كافية حالياً (المتاح: ' . count($picked) . '). حاول لاحقاً أو قلّل الكمية'], 400);
            }

            $now = date('Y-m-d H:i:s');
            $upd = $pdo->prepare("UPDATE cards_pool SET status = 'sent', sent_to_customer_id = ?, sent_at = ?, sold_via_portal = 1, sale_price = ? WHERE id = ? AND status = 'available'");
            $numbers = [];
            foreach ($picked as $card) {
                $upd->execute([$customerId, $now, $unitPrice, $card['id']]);
                if ($upd->rowCount() !== 1) {
                    $pdo->rollBack();
                    jsonResponse(['success' => false, 'message' => 'أحد الأرقام تم بيعه للتو، أعد المحاولة'], 409);
                }
                $numbers[] = $card['card_number'];
            }

            // خصم الرصيد وتسجيل الحركة
            $newBalance = adjustCustomerBalance($pdo, $customerId, 'purchase', $totalPrice, "شراء {$qty} × {$category['name']}", null);

            // تسجيل عملية بيع رسمية في سجل المبيعات (بدون ربطها بموظف — بيع ذاتي عبر البوابة)
            $invoiceNo = 'PRT-' . date('YmdHis') . '-' . $customerId;
            $catRow = $pdo->prepare("SELECT default_buy_price FROM card_categories WHERE id = ?");
            $catRow->execute([$categoryId]);
            $buyPrice = floatval(($catRow->fetch() ?: ['default_buy_price' => 0])['default_buy_price']);
            $saleStmt = $pdo->prepare("INSERT INTO sales (invoice_no, customer_id, category_id, quantity, buy_price, sell_price, total_cost, total_sell, profit, payment_status, amount_paid, notes, user_id, sold_at)
                                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'paid', ?, ?, NULL, ?)");
            $totalCost = round($buyPrice * $qty, 2);
            $profit = round($totalPrice - $totalCost, 2);
            $saleStmt->execute([$invoiceNo, $customerId, $categoryId, $qty, $buyPrice, $unitPrice, $totalCost, $totalPrice, $profit, $totalPrice, 'شراء ذاتي عبر بوابة الزبون', $now]);
            $saleId = intval($pdo->lastInsertId());

            $pdo->commit();
        } catch (Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            jsonResponse(['success' => false, 'message' => 'تعذر إتمام عملية الشراء، لم يُخصم أي مبلغ'], 500);
        }

        $count = count($numbers);
        $title = $count === 1 ? '🎉 تم شراء بطاقتك بنجاح' : "🎉 تم شراء {$count} بطاقات بنجاح";
        $body = 'تم خصم ' . money($totalPrice) . ' من رصيدك. رصيدك الحالي: ' . money($newBalance);
        notifyCustomer($pdo, $customerId, $title, $body);
        addAuditLog($pdo, 'شراء بطاقة عبر البوابة', $customer['full_name'] . " — {$category['name']} × {$count} — " . money($totalPrice));

        jsonResponse(['success' => true, 'numbers' => $numbers, 'new_balance' => $newBalance, 'total_paid' => $totalPrice]);
    }

    /* — رفع إيصال دفع (صورة + مبلغ + طريقة) — */
    if ($action === 'portal_upload_receipt') {
        $method = in_array($_POST['method'] ?? '', ['palpay', 'jawwalpay'], true) ? $_POST['method'] : '';
        $amount = floatval($_POST['amount'] ?? 0);
        $note = sanitizeInput($_POST['note'] ?? '');
        $imageB64 = $_POST['image'] ?? '';

        if ($method === '') jsonResponse(['success' => false, 'message' => 'اختر طريقة التحويل'], 400);
        if ($amount <= 0) jsonResponse(['success' => false, 'message' => 'أدخل المبلغ المحوَّل'], 400);
        if ($imageB64 === '') jsonResponse(['success' => false, 'message' => 'أرفق صورة إشعار التحويل'], 400);

        // فك الصورة من data URL
        if (preg_match('/^data:(image\/(?:jpeg|png|webp));base64,(.+)$/', $imageB64, $m)) {
            $mime = $m[1];
            $binary = base64_decode($m[2], true);
        } else {
            jsonResponse(['success' => false, 'message' => 'صيغة الصورة غير مدعومة'], 400);
        }
        if ($binary === false || strlen($binary) < 100) {
            jsonResponse(['success' => false, 'message' => 'تعذر قراءة الصورة'], 400);
        }
        if (strlen($binary) > 2 * 1024 * 1024) {
            jsonResponse(['success' => false, 'message' => 'حجم الصورة كبير جداً (الحد 2MB)'], 400);
        }

        $stmt = $pdo->prepare("INSERT INTO payment_receipts (customer_id, method, amount, note, image_data, image_mime, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)");
        $stmt->bindValue(1, $customerId, PDO::PARAM_INT);
        $stmt->bindValue(2, $method);
        $stmt->bindValue(3, $amount);
        $stmt->bindValue(4, $note);
        $stmt->bindValue(5, $binary, PDO::PARAM_LOB);
        $stmt->bindValue(6, $mime);
        $stmt->bindValue(7, date('Y-m-d H:i:s'));
        $stmt->execute();

        addAuditLog($pdo, 'إيصال دفع جديد من زبون', $customer['full_name'] . ' — ' . money($amount));
        jsonResponse(['success' => true, 'id' => $pdo->lastInsertId()]);
    }

    /* — إرسال طلب شراء بطاقات — */
    if ($action === 'portal_purchase_request') {
        $catId = intval($_POST['category_id'] ?? 0) ?: null;
        $qty = max(1, intval($_POST['quantity'] ?? 1));
        $note = sanitizeInput($_POST['note'] ?? '');
        $stmt = $pdo->prepare("INSERT INTO purchase_requests (customer_id, category_id, quantity, note, created_at) VALUES (?, ?, ?, ?, ?)");
        $stmt->execute([$customerId, $catId, $qty, $note, date('Y-m-d H:i:s')]);
        addAuditLog($pdo, 'طلب شراء من زبون', $customer['full_name'] . " — كمية: $qty");
        jsonResponse(['success' => true, 'id' => $pdo->lastInsertId()]);
    }

    /* — حفظ اشتراك الإشعارات (Push) — */
    if ($action === 'portal_subscribe_push') {
        $endpoint = trim($_POST['endpoint'] ?? '');
        $p256dh = trim($_POST['p256dh'] ?? '');
        $auth = trim($_POST['auth'] ?? '');
        if ($endpoint === '' || $p256dh === '' || $auth === '') {
            jsonResponse(['success' => false, 'message' => 'بيانات الاشتراك ناقصة'], 400);
        }
        $stmt = $pdo->prepare("INSERT INTO push_subscriptions (customer_id, endpoint, p256dh, auth, created_at) VALUES (?, ?, ?, ?, ?)
                               ON CONFLICT(endpoint) DO UPDATE SET customer_id = excluded.customer_id, p256dh = excluded.p256dh, auth = excluded.auth");
        $stmt->execute([$customerId, $endpoint, $p256dh, $auth, date('Y-m-d H:i:s')]);
        jsonResponse(['success' => true]);
    }

    /* — تعليم الإشعارات كمقروءة — */
    if ($action === 'portal_notifications_read') {
        $pdo->prepare("UPDATE customer_notifications SET is_read = 1 WHERE customer_id = ?")->execute([$customerId]);
        jsonResponse(['success' => true]);
    }

    /* — فتح تذكرة دعم جديدة (شكوى/استفسار) + رد تلقائي فوري — */
    if ($action === 'portal_ticket_create') {
        $subject = sanitizeInput($_POST['subject'] ?? '');
        $body = trim((string)($_POST['body'] ?? ''));
        if ($body === '') jsonResponse(['success' => false, 'message' => 'اكتب رسالتك أولاً'], 400);
        if (mb_strlen($body) > 2000) jsonResponse(['success' => false, 'message' => 'الرسالة طويلة جداً (بحد أقصى 2000 حرف)'], 400);
        if ($subject === '') $subject = mb_substr($body, 0, 40) . (mb_strlen($body) > 40 ? '…' : '');
        $openCnt = $pdo->prepare("SELECT COUNT(*) c FROM support_tickets WHERE customer_id = ? AND status = 'open'");
        $openCnt->execute([$customerId]);
        if (intval($openCnt->fetch()['c']) >= 10) {
            jsonResponse(['success' => false, 'message' => 'لديك 10 تذاكر مفتوحة — انتظر ردنا عليها أولاً'], 429);
        }
        $now = date('Y-m-d H:i:s');
        $pdo->prepare("INSERT INTO support_tickets (customer_id, subject, status, unread_admin, last_msg_at, created_at) VALUES (?, ?, 'open', 1, ?, ?)")
            ->execute([$customerId, $subject, $now, $now]);
        $tid = intval($pdo->lastInsertId());
        $pdo->prepare("INSERT INTO ticket_messages (ticket_id, sender, sender_name, body, created_at) VALUES (?, 'customer', ?, ?, ?)")
            ->execute([$tid, $customer['full_name'], $body, $now]);
        // الرد التلقائي: يظهر داخل المحادثة فوراً
        $auto = 'أهلاً بك 👋 وصلتنا رسالتك بنجاح، وسيتم الرد عليك في أقرب وقت ممكن. شكراً لتواصلك معنا 💜';
        $pdo->prepare("INSERT INTO ticket_messages (ticket_id, sender, sender_name, body, created_at) VALUES (?, 'system', 'الرد التلقائي', ?, ?)")
            ->execute([$tid, $auto, date('Y-m-d H:i:s')]);
        // إشعار داخلي + Push حتى خارج التطبيق
        notifyCustomer($pdo, $customerId, '🎫 استلمنا تذكرتك #' . $tid, 'سيتم الرد عليك في أقرب وقت ممكن');
        addAuditLog($pdo, 'تذكرة دعم جديدة', 'تذكرة #' . $tid . ' من ' . $customer['full_name'] . ' — ' . $subject);
        jsonResponse(['success' => true, 'ticket_id' => $tid]);
    }

    /* — تذاكري — */
    if ($action === 'portal_tickets_list') {
        $stmt = $pdo->prepare("SELECT t.id, t.subject, t.status, t.unread_customer, t.last_msg_at, t.created_at,
                                      (SELECT body FROM ticket_messages WHERE ticket_id = t.id ORDER BY id DESC LIMIT 1) AS last_body,
                                      (SELECT sender FROM ticket_messages WHERE ticket_id = t.id ORDER BY id DESC LIMIT 1) AS last_sender
                               FROM support_tickets t WHERE t.customer_id = ? ORDER BY t.last_msg_at DESC LIMIT 50");
        $stmt->execute([$customerId]);
        jsonResponse(['success' => true, 'data' => $stmt->fetchAll()]);
    }

    /* — رسائل تذكرة (مع تعليم رسائل الإدارة كمقروءة) — */
    if ($action === 'portal_ticket_messages') {
        $tid = intval($_GET['ticket_id'] ?? 0);
        $afterId = intval($_GET['after_id'] ?? 0);
        $t = $pdo->prepare("SELECT * FROM support_tickets WHERE id = ? AND customer_id = ?");
        $t->execute([$tid, $customerId]);
        $ticket = $t->fetch();
        if (!$ticket) jsonResponse(['success' => false, 'message' => 'التذكرة غير موجودة'], 404);
        $m = $pdo->prepare("SELECT id, sender, sender_name, body, created_at FROM ticket_messages WHERE ticket_id = ? AND id > ? ORDER BY id ASC LIMIT 500");
        $m->execute([$tid, $afterId]);
        $pdo->prepare("UPDATE support_tickets SET unread_customer = 0 WHERE id = ?")->execute([$tid]);
        jsonResponse(['success' => true, 'ticket' => ['id' => intval($ticket['id']), 'subject' => $ticket['subject'], 'status' => $ticket['status']], 'messages' => $m->fetchAll()]);
    }

    /* — إرسال رسالة داخل تذكرة (إرسالها على تذكرة مغلقة يعيد فتحها) — */
    if ($action === 'portal_ticket_send') {
        $tid = intval($_POST['ticket_id'] ?? 0);
        $body = trim((string)($_POST['body'] ?? ''));
        if ($body === '') jsonResponse(['success' => false, 'message' => 'اكتب رسالتك أولاً'], 400);
        if (mb_strlen($body) > 2000) jsonResponse(['success' => false, 'message' => 'الرسالة طويلة جداً (بحد أقصى 2000 حرف)'], 400);
        $t = $pdo->prepare("SELECT * FROM support_tickets WHERE id = ? AND customer_id = ?");
        $t->execute([$tid, $customerId]);
        if (!$t->fetch()) jsonResponse(['success' => false, 'message' => 'التذكرة غير موجودة'], 404);
        $now = date('Y-m-d H:i:s');
        $pdo->prepare("INSERT INTO ticket_messages (ticket_id, sender, sender_name, body, created_at) VALUES (?, 'customer', ?, ?, ?)")
            ->execute([$tid, $customer['full_name'], $body, $now]);
        $pdo->prepare("UPDATE support_tickets SET last_msg_at = ?, unread_admin = unread_admin + 1, status = 'open', closed_at = NULL WHERE id = ?")
            ->execute([$now, $tid]);
        jsonResponse(['success' => true]);
    }

    jsonResponse(['success' => false, 'message' => 'إجراء بوابة غير معروف'], 400);
}

/* ═══════════════════ من هنا فصاعداً: تسجيل الدخول مطلوب ═══════════════════ */
if (!isLoggedIn()) {
    jsonResponse(['success' => false, 'message' => 'الرجاء تسجيل الدخول أولاً'], 401);
}

$user = currentUser();

/* ─────────────────────────────────────────────────────────
   الزبائن
   ───────────────────────────────────────────────────────── */
if ($action === 'customer_create' || $action === 'customer_update') {
    requirePermission('customers.manage');
    $id = intval($_POST['id'] ?? 0);
    $name = sanitizeInput($_POST['full_name'] ?? '');
    $phone = sanitizeInput($_POST['phone'] ?? '');
    $address = sanitizeInput($_POST['address'] ?? '');
    $notes = sanitizeInput($_POST['notes'] ?? '');
    if ($name === '') jsonResponse(['success' => false, 'message' => 'اسم الزبون مطلوب'], 400);

    // بيانات دخول البوابة (اختيارية): تغيير اسم المستخدم و/أو كلمة المرور، أو إنشاء حساب بوابة لزبون بدونه
    $portalUsername = trim($_POST['portal_username'] ?? '');
    $portalPassword = (string)($_POST['portal_password'] ?? '');
    if ($portalUsername !== '' && !preg_match('/^[a-zA-Z0-9_.]{3,30}$/', $portalUsername)) {
        jsonResponse(['success' => false, 'message' => 'اسم مستخدم البوابة: أحرف إنجليزية وأرقام فقط (3-30 حرف)'], 400);
    }
    if ($portalPassword !== '' && strlen($portalPassword) < 4) {
        jsonResponse(['success' => false, 'message' => 'كلمة مرور البوابة: 4 أحرف على الأقل'], 400);
    }
    if ($portalUsername !== '') {
        $ex = $pdo->prepare("SELECT id FROM customers WHERE username = ? AND id != ?");
        $ex->execute([$portalUsername, $id]);
        if ($ex->fetch()) jsonResponse(['success' => false, 'message' => 'اسم المستخدم هذا محجوز لزبون آخر'], 400);
    }

    if ($id > 0) {
        $curStmt = $pdo->prepare("SELECT username, password_hash FROM customers WHERE id = ?");
        $curStmt->execute([$id]);
        $cur = $curStmt->fetch();
        if (!$cur) jsonResponse(['success' => false, 'message' => 'الزبون غير موجود'], 404);
        if ($portalPassword === '' && $portalUsername !== '' && empty($cur['password_hash'])) {
            jsonResponse(['success' => false, 'message' => 'لإنشاء حساب بوابة جديد لهذا الزبون: عبِّئ كلمة المرور أيضاً'], 400);
        }
        $stmt = $pdo->prepare("UPDATE customers SET full_name=?, phone=?, address=?, notes=?, updated_at=CURRENT_TIMESTAMP WHERE id=?");
        $stmt->execute([$name, $phone, $address, $notes, $id]);
        if ($portalUsername !== '' && $portalUsername !== ($cur['username'] ?? '')) {
            $pdo->prepare("UPDATE customers SET username = ?, registered_at = COALESCE(registered_at, ?) WHERE id = ?")
                ->execute([$portalUsername, date('Y-m-d H:i:s'), $id]);
            addAuditLog($pdo, 'تغيير اسم مستخدم زبون', $name . ' → @' . $portalUsername);
        }
        if ($portalPassword !== '') {
            $pdo->prepare("UPDATE customers SET password_hash = ? WHERE id = ?")
                ->execute([password_hash($portalPassword, PASSWORD_DEFAULT), $id]);
            addAuditLog($pdo, 'تغيير كلمة مرور زبون', $name);
        }
        addAuditLog($pdo, 'تعديل زبون', $name);
        jsonResponse(['success' => true, 'id' => $id]);
    } else {
        if ($portalUsername !== '' && $portalPassword === '') {
            jsonResponse(['success' => false, 'message' => 'لإنشاء حساب بوابة للزبون الجديد: عبِّئ كلمة المرور أيضاً'], 400);
        }
        $stmt = $pdo->prepare("INSERT INTO customers (full_name, phone, address, notes, created_by) VALUES (?, ?, ?, ?, ?)");
        $stmt->execute([$name, $phone, $address, $notes, $user['id']]);
        $newId = intval($pdo->lastInsertId());
        if ($portalUsername !== '' && $portalPassword !== '') {
            $pdo->prepare("UPDATE customers SET username = ?, password_hash = ?, registered_at = ? WHERE id = ?")
                ->execute([$portalUsername, password_hash($portalPassword, PASSWORD_DEFAULT), date('Y-m-d H:i:s'), $newId]);
            addAuditLog($pdo, 'إنشاء حساب بوابة لزبون', $name . ' → @' . $portalUsername);
        }
        addAuditLog($pdo, 'إضافة زبون', $name);
        jsonResponse(['success' => true, 'id' => $newId]);
    }
}

if ($action === 'customer_toggle_block') {
    requirePermission('customers.manage');
    $id = intval($_POST['id'] ?? 0);
    $stmt = $pdo->prepare("UPDATE customers SET is_blocked = 1 - is_blocked WHERE id = ?");
    $stmt->execute([$id]);
    addAuditLog($pdo, 'تغيير حالة حظر زبون', "ID:$id");
    jsonResponse(['success' => true]);
}

if ($action === 'customer_delete') {
    requirePermission('customers.manage');
    $id = intval($_POST['id'] ?? 0);
    $hasSales = $pdo->prepare("SELECT COUNT(*) c FROM sales WHERE customer_id = ?");
    $hasSales->execute([$id]);
    if (intval($hasSales->fetch()['c']) > 0) {
        jsonResponse(['success' => false, 'message' => 'لا يمكن حذف زبون لديه عمليات بيع مسجلة. يمكنك حظره بدلاً من ذلك'], 400);
    }
    $stmt = $pdo->prepare("DELETE FROM customers WHERE id = ?");
    $stmt->execute([$id]);
    addAuditLog($pdo, 'حذف زبون', "ID:$id");
    jsonResponse(['success' => true]);
}

if ($action === 'customers_list') {
    requirePermission('customers.view');
    $search = trim($_GET['search'] ?? '');
    $sql = "SELECT c.*,
                (SELECT COALESCE(SUM(remaining_amount),0) FROM debts WHERE customer_id = c.id AND status != 'paid') AS total_debt,
                (SELECT COUNT(*) FROM sales WHERE customer_id = c.id) AS total_orders
            FROM customers c";
    $params = [];
    if ($search !== '') {
        $sql .= " WHERE c.full_name LIKE ? OR c.phone LIKE ?";
        $params = ["%$search%", "%$search%"];
    }
    $sql .= " ORDER BY c.created_at DESC";
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    jsonResponse(['success' => true, 'data' => $stmt->fetchAll()]);
}

if ($action === 'customer_detail') {
    requirePermission('customers.view');
    $id = intval($_GET['id'] ?? 0);
    $stmt = $pdo->prepare("SELECT * FROM customers WHERE id = ?");
    $stmt->execute([$id]);
    $customer = $stmt->fetch();
    if (!$customer) jsonResponse(['success' => false, 'message' => 'الزبون غير موجود'], 404);

    $sales = $pdo->prepare("SELECT s.*, cc.name AS category_name FROM sales s LEFT JOIN card_categories cc ON cc.id = s.category_id WHERE s.customer_id = ? ORDER BY s.sold_at DESC");
    $sales->execute([$id]);

    $debts = $pdo->prepare("SELECT * FROM debts WHERE customer_id = ? ORDER BY created_at DESC");
    $debts->execute([$id]);

    $cardsAll = $pdo->prepare("SELECT cp.id, cp.card_number, cp.sale_price, cp.sent_at, cp.sold_via_portal,
                                       cc.name AS category_name, cc.color AS category_color, u.full_name AS sender_name
                                FROM cards_pool cp
                                LEFT JOIN card_categories cc ON cc.id = cp.category_id
                                LEFT JOIN users u ON u.id = cp.sent_by
                                WHERE cp.sent_to_customer_id = ? AND cp.status = 'sent' ORDER BY cp.sent_at DESC LIMIT 150");
    $cardsAll->execute([$id]);

    jsonResponse([
        'success' => true,
        'customer' => $customer,
        'sales' => $sales->fetchAll(),
        'debts' => $debts->fetchAll(),
        'cards' => $cardsAll->fetchAll(),
    ]);
}

/* ─────────────────────────────────────────────────────────
   فئات البطاقات والمخزون
   ───────────────────────────────────────────────────────── */
if ($action === 'category_create' || $action === 'category_update') {
    requirePermission('inventory.manage');
    $id = intval($_POST['id'] ?? 0);
    $name = sanitizeInput($_POST['name'] ?? '');
    $buyPrice = floatval($_POST['default_buy_price'] ?? 0);
    $sellPrice = floatval($_POST['default_sell_price'] ?? 0);
    $threshold = intval($_POST['low_stock_threshold'] ?? 5);
    $color = sanitizeInput($_POST['color'] ?? '#6C43FF');
    $icon = sanitizeInput($_POST['icon'] ?? 'ph-wifi-high');
    $durationHours = max(0, floatval($_POST['duration_hours'] ?? 0)); // 0 = يُستنتج من الاسم
    if ($name === '') jsonResponse(['success' => false, 'message' => 'اسم الفئة مطلوب'], 400);

    if ($id > 0) {
        $stmt = $pdo->prepare("UPDATE card_categories SET name=?, default_buy_price=?, default_sell_price=?, low_stock_threshold=?, color=?, icon=?, duration_hours=? WHERE id=?");
        $stmt->execute([$name, $buyPrice, $sellPrice, $threshold, $color, $icon, $durationHours, $id]);
        addAuditLog($pdo, 'تعديل فئة بطاقات', $name);
        jsonResponse(['success' => true, 'id' => $id]);
    } else {
        $stmt = $pdo->prepare("INSERT INTO card_categories (name, default_buy_price, default_sell_price, low_stock_threshold, color, icon, duration_hours) VALUES (?, ?, ?, ?, ?, ?, ?)");
        $stmt->execute([$name, $buyPrice, $sellPrice, $threshold, $color, $icon, $durationHours]);
        $newId = $pdo->lastInsertId();
        addAuditLog($pdo, 'إضافة فئة بطاقات', $name);
        jsonResponse(['success' => true, 'id' => $newId]);
    }
}

