if ($action === 'stock_add') {
    requirePermission('inventory.manage');
    $categoryId = intval($_POST['category_id'] ?? 0);
    $qty = intval($_POST['quantity'] ?? 0);
    $note = sanitizeInput($_POST['note'] ?? '');
    if ($categoryId <= 0 || $qty === 0) jsonResponse(['success' => false, 'message' => 'بيانات غير صحيحة'], 400);

    $pdo->beginTransaction();
    try {
        // منع الخصم اليدوي بما يتجاوز الكمية المتوفرة
        $curStmt = $pdo->prepare("SELECT quantity_available FROM card_categories WHERE id = ?");
        $curStmt->execute([$categoryId]);
        $cur = $curStmt->fetch();
        if (!$cur) {
            $pdo->rollBack();
            jsonResponse(['success' => false, 'message' => 'الفئة غير موجودة'], 404);
        }
        if ($qty < 0 && (intval($cur['quantity_available']) + $qty) < 0) {
            $pdo->rollBack();
            jsonResponse(['success' => false, 'message' => 'لا يمكن خصم كمية أكبر من المتوفر (' . $cur['quantity_available'] . ')'], 400);
        }

        $stmt = $pdo->prepare("UPDATE card_categories SET quantity_available = quantity_available + ? WHERE id = ?");
        $stmt->execute([$qty, $categoryId]);
        $movType = $qty > 0 ? 'in' : 'adjustment';
        $log = $pdo->prepare("INSERT INTO stock_movements (category_id, movement_type, quantity, note, user_id, created_at) VALUES (?, ?, ?, ?, ?, ?)");
        $log->execute([$categoryId, $movType, $qty, $note, $user['id'], date('Y-m-d H:i:s')]);
        $pdo->commit();
        addAuditLog($pdo, 'تحديث المخزون', "فئة:$categoryId كمية:$qty");
        jsonResponse(['success' => true]);
    } catch (Exception $e) {
        $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر تحديث المخزون'], 500);
    }
}

