if ($action === 'sale_create') {
    requirePermission('sales.create');
    $customerId = intval($_POST['customer_id'] ?? 0) ?: null;
    $categoryId = intval($_POST['category_id'] ?? 0);
    $qty = max(1, intval($_POST['quantity'] ?? 1));
    $buyPrice = floatval($_POST['buy_price'] ?? 0);
    $sellPrice = floatval($_POST['sell_price'] ?? 0);
    $paymentStatus = in_array($_POST['payment_status'] ?? 'paid', ['paid', 'debt', 'partial'], true) ? $_POST['payment_status'] : 'paid';
    $amountPaid = floatval($_POST['amount_paid'] ?? 0);
    $notes = sanitizeInput($_POST['notes'] ?? '');
    $dueDate = trim($_POST['due_date'] ?? '') ?: null;

    if ($categoryId <= 0) jsonResponse(['success' => false, 'message' => 'يرجى اختيار فئة البطاقة'], 400);

    $catStmt = $pdo->prepare("SELECT * FROM card_categories WHERE id = ?");
    $catStmt->execute([$categoryId]);
    $category = $catStmt->fetch();
    if (!$category) jsonResponse(['success' => false, 'message' => 'فئة البطاقة غير موجودة'], 404);
    if (intval($category['quantity_available']) < $qty) {
        jsonResponse(['success' => false, 'message' => 'الكمية المتوفرة في المخزون غير كافية (المتوفر: ' . $category['quantity_available'] . ')'], 400);
    }
    if ($customerId === null && $paymentStatus !== 'paid') {
        jsonResponse(['success' => false, 'message' => 'لا يمكن تسجيل دين بدون اختيار زبون'], 400);
    }

    $totalCost = $buyPrice * $qty;
    $totalSell = $sellPrice * $qty;
    $profit = $totalSell - $totalCost;
    if ($paymentStatus === 'paid') $amountPaid = $totalSell;
    if ($paymentStatus === 'debt') $amountPaid = 0;
    $amountPaid = min($amountPaid, $totalSell);

    $pdo->beginTransaction();
    try {
        $nowLocal = date('Y-m-d H:i:s');
        $invoiceNo = generateInvoiceNo($pdo);
        $stmt = $pdo->prepare("INSERT INTO sales
            (invoice_no, customer_id, category_id, quantity, buy_price, sell_price, total_cost, total_sell, profit, payment_status, amount_paid, notes, user_id, sold_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        $stmt->execute([$invoiceNo, $customerId, $categoryId, $qty, $buyPrice, $sellPrice, $totalCost, $totalSell, $profit, $paymentStatus, $amountPaid, $notes, $user['id'], $nowLocal]);
        $saleId = $pdo->lastInsertId();

        // خصم من المخزون
        $upd = $pdo->prepare("UPDATE card_categories SET quantity_available = quantity_available - ? WHERE id = ?");
        $upd->execute([$qty, $categoryId]);
        $mov = $pdo->prepare("INSERT INTO stock_movements (category_id, movement_type, quantity, note, user_id, created_at) VALUES (?, 'sale_out', ?, ?, ?, ?)");
        $mov->execute([$categoryId, -$qty, "بيع فاتورة $invoiceNo", $user['id'], $nowLocal]);

        // إن كانت العملية دين أو جزئي، أنشئ سجل دين
        if ($paymentStatus !== 'paid' && $customerId !== null) {
            $remaining = $totalSell - $amountPaid;
            if ($remaining > 0) {
                $debtStmt = $pdo->prepare("INSERT INTO debts (customer_id, sale_id, original_amount, remaining_amount, due_date, note, user_id) VALUES (?, ?, ?, ?, ?, ?, ?)");
                $debtStmt->execute([$customerId, $saleId, $totalSell, $remaining, $dueDate, "فاتورة $invoiceNo", $user['id']]);
            }
        }

        $pdo->commit();
        addAuditLog($pdo, 'عملية بيع جديدة', "فاتورة $invoiceNo - " . money($totalSell));
        jsonResponse(['success' => true, 'invoice_no' => $invoiceNo, 'sale_id' => $saleId]);
    } catch (Exception $e) {
        $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر إتمام عملية البيع'], 500);
    }
}

if ($action === 'sale_delete') {
    requirePermission('sales.delete');
    $id = intval($_POST['id'] ?? 0);
    $stmt = $pdo->prepare("SELECT * FROM sales WHERE id = ?");
    $stmt->execute([$id]);
    $sale = $stmt->fetch();
    if (!$sale) jsonResponse(['success' => false, 'message' => 'العملية غير موجودة'], 404);

    $isPortalPurchase = strpos((string)$sale['invoice_no'], 'PRT-') === 0;

    $pdo->beginTransaction();
    try {
        if ($isPortalPurchase) {
            // عملية شراء ذاتي من البوابة: أعد البطاقات إلى المخزن المتاح واسترجع المبلغ لرصيد الزبون
            $cards = $pdo->prepare("SELECT id, sale_price FROM cards_pool WHERE sent_to_customer_id = ? AND category_id = ? AND sold_via_portal = 1 AND sent_at IS NOT NULL ORDER BY id DESC LIMIT " . intval($sale['quantity']));
            $cards->execute([$sale['customer_id'], $sale['category_id']]);
            $poolRows = $cards->fetchAll();
            $revertUpd = $pdo->prepare("UPDATE cards_pool SET status = 'available', sent_to_customer_id = NULL, sent_at = NULL, sent_by = NULL, sold_via_portal = 0, sale_price = NULL WHERE id = ?");
            foreach ($poolRows as $pr) {
                $revertUpd->execute([$pr['id']]);
            }
            if (floatval($sale['total_sell']) > 0 && $sale['customer_id']) {
                adjustCustomerBalance($pdo, intval($sale['customer_id']), 'refund', floatval($sale['total_sell']), 'استرجاع بعد حذف فاتورة ' . $sale['invoice_no'], $user['id'], $id);
            }
        } else {
            // بيع عادي عبر نقطة البيع: أعد الكمية إلى عداد المخزون اليدوي
            $upd = $pdo->prepare("UPDATE card_categories SET quantity_available = quantity_available + ? WHERE id = ?");
            $upd->execute([$sale['quantity'], $sale['category_id']]);
            $mov = $pdo->prepare("INSERT INTO stock_movements (category_id, movement_type, quantity, note, user_id, created_at) VALUES (?, 'adjustment', ?, ?, ?, ?)");
            $mov->execute([$sale['category_id'], $sale['quantity'], "إلغاء فاتورة " . $sale['invoice_no'], $user['id'], date('Y-m-d H:i:s')]);
        }

        // حذف الديون المرتبطة (والتسديدات تُحذف تلقائياً بواسطة CASCADE)
        $pdo->prepare("DELETE FROM debts WHERE sale_id = ?")->execute([$id]);
        $pdo->prepare("DELETE FROM sales WHERE id = ?")->execute([$id]);

        $pdo->commit();
        addAuditLog($pdo, 'حذف عملية بيع', $sale['invoice_no'] . ($isPortalPurchase ? ' (شراء بوابة — أُعيد للمخزن واسترُجع الرصيد)' : ''));
        jsonResponse(['success' => true]);
    } catch (Exception $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر حذف العملية'], 500);
    }
}

