if ($action === 'debt_pay') {
    requirePermission('debts.manage');
    $debtId = intval($_POST['debt_id'] ?? 0);
    $amount = floatval($_POST['amount'] ?? 0);
    $note = sanitizeInput($_POST['note'] ?? '');
    if ($debtId <= 0 || $amount <= 0) jsonResponse(['success' => false, 'message' => 'مبلغ غير صحيح'], 400);

    $stmt = $pdo->prepare("SELECT * FROM debts WHERE id = ?");
    $stmt->execute([$debtId]);
    $debt = $stmt->fetch();
    if (!$debt) jsonResponse(['success' => false, 'message' => 'الدين غير موجود'], 404);
    if ($amount > floatval($debt['remaining_amount'])) {
        jsonResponse(['success' => false, 'message' => 'المبلغ أكبر من المتبقي (' . money($debt['remaining_amount']) . ')'], 400);
    }

    $pdo->beginTransaction();
    try {
        $pay = $pdo->prepare("INSERT INTO debt_payments (debt_id, amount, note, user_id, paid_at) VALUES (?, ?, ?, ?, ?)");
        $pay->execute([$debtId, $amount, $note, $user['id'], date('Y-m-d H:i:s')]);

        $newRemaining = floatval($debt['remaining_amount']) - $amount;
        $newStatus = $newRemaining <= 0.009 ? 'paid' : 'open';
        $upd = $pdo->prepare("UPDATE debts SET remaining_amount = ?, status = ? WHERE id = ?");
        $upd->execute([max(0, $newRemaining), $newStatus, $debtId]);

        $pdo->commit();
        addAuditLog($pdo, 'تسديد دين', money($amount));
        jsonResponse(['success' => true, 'remaining' => max(0, $newRemaining), 'status' => $newStatus]);
    } catch (Exception $e) {
        $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر تسجيل التسديد'], 500);
    }
}

if ($action === 'debts_list') {
    requirePermission('debts.view');
    $status = trim($_GET['status'] ?? '');
    $search = trim($_GET['search'] ?? '');
    $sql = "SELECT d.*, c.full_name AS customer_name, c.phone AS customer_phone
            FROM debts d
            LEFT JOIN customers c ON c.id = d.customer_id
            WHERE 1=1";
    $params = [];
    if ($status !== '') {
        if ($status === 'open') { $sql .= " AND d.status IN ('open','overdue')"; }
        else { $sql .= " AND d.status = ?"; $params[] = $status; }
    }
    if ($search !== '') { $sql .= " AND c.full_name LIKE ?"; $params[] = "%$search%"; }
    $sql .= " ORDER BY (d.status='paid') ASC, d.due_date IS NULL, d.due_date ASC, d.created_at DESC";
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    $debts = $stmt->fetchAll();

    // تحديث حالة "متأخر" ديناميكياً للعرض (دون تعديل قاعدة البيانات الفعلية إلا عند اللزوم)
    $today = date('Y-m-d');
    foreach ($debts as &$d) {
        if ($d['status'] === 'open' && !empty($d['due_date']) && $d['due_date'] < $today) {
            $d['status'] = 'overdue';
        }
    }
    unset($d);

    jsonResponse(['success' => true, 'data' => $debts]);
}

