        'month' => ['sales' => floatval($monthSales['s']), 'profit' => floatval($monthSales['p']), 'count' => intval($monthSales['c']), 'expenses' => floatval($monthExpenses['t'])],
        'total_debt' => floatval($totalDebt['t']),
        'low_stock_count' => intval($lowStock['c']),
