    ]);
}

if ($action === 'reports_range') {
    requirePermission('reports.view');
    $period = trim($_GET['period'] ?? 'daily'); // daily | monthly | yearly
    $from = trim($_GET['from'] ?? date('Y-m-d', strtotime('-30 days')));
    $to = trim($_GET['to'] ?? date('Y-m-d'));

    $groupExpr = match ($period) {
        'monthly' => "strftime('%Y-%m', sold_at)",
        'yearly'  => "strftime('%Y', sold_at)",
        default   => "date(sold_at)",
    };
    // نفس تعبير التجميع لكن على عمود تاريخ المصاريف
    $groupExprExp = str_replace('sold_at', 'expense_date', $groupExpr);

    $stmt = $pdo->prepare("
        SELECT $groupExpr AS period_label,
               COALESCE(SUM(total_sell),0) AS revenue,
               COALESCE(SUM(total_cost),0) AS cost,
               COALESCE(SUM(profit),0) AS profit,
               COUNT(*) AS orders_count,
               COALESCE(SUM(quantity),0) AS cards_sold
        FROM sales
        WHERE date(sold_at) >= date(?) AND date(sold_at) <= date(?)
        GROUP BY period_label
        ORDER BY period_label ASC
    ");
    $stmt->execute([$from, $to]);
    $sales = $stmt->fetchAll();

    $expStmt = $pdo->prepare("
        SELECT $groupExprExp AS period_label, COALESCE(SUM(amount),0) AS total
        FROM expenses
        WHERE date(expense_date) >= date(?) AND date(expense_date) <= date(?)
        GROUP BY period_label
    ");
    $expStmt->execute([$from, $to]);
    $expenseMap = [];
    foreach ($expStmt->fetchAll() as $row) $expenseMap[$row['period_label']] = floatval($row['total']);

    foreach ($sales as &$row) {
        $row['expenses'] = $expenseMap[$row['period_label']] ?? 0;
        $row['net_profit'] = $row['profit'] - $row['expenses'];
    }
    unset($row);

    $totals = [
        'revenue' => array_sum(array_column($sales, 'revenue')),
        'cost' => array_sum(array_column($sales, 'cost')),
        'profit' => array_sum(array_column($sales, 'profit')),
        'expenses' => array_sum($expenseMap),
        'orders_count' => array_sum(array_column($sales, 'orders_count')),
        'cards_sold' => array_sum(array_column($sales, 'cards_sold')),
    ];
    $totals['net_profit'] = $totals['profit'] - $totals['expenses'];

    // أفضل الفئات مبيعاً بالمدة المحددة
    $topCategories = $pdo->prepare("
        SELECT cc.name, cc.color, COALESCE(SUM(s.quantity),0) AS qty, COALESCE(SUM(s.profit),0) AS profit
        FROM sales s JOIN card_categories cc ON cc.id = s.category_id
        WHERE date(s.sold_at) >= date(?) AND date(s.sold_at) <= date(?)
        GROUP BY cc.id ORDER BY qty DESC LIMIT 5
    ");
    $topCategories->execute([$from, $to]);

    jsonResponse(['success' => true, 'rows' => $sales, 'totals' => $totals, 'top_categories' => $topCategories->fetchAll()]);
}

