/* — رفع أيقونة مخصّصة للتطبيق والموقع والإشعارات (من جهاز المالك) — */
if ($action === 'settings_upload_icon') {
    requirePermission('settings.manage');
    if (empty($_FILES['icon']) || $_FILES['icon']['error'] !== UPLOAD_ERR_OK) {
        jsonResponse(['success' => false, 'message' => 'اختر صورة صالحة من جهازك'], 400);
    }
    if ($_FILES['icon']['size'] > 3 * 1024 * 1024) {
        jsonResponse(['success' => false, 'message' => 'الحد الأقصى لحجم الصورة 3 ميجابايت'], 400);
    }
    $raw = file_get_contents($_FILES['icon']['tmp_name']);
    $info = @getimagesizefromstring($raw);
    if ($info === false || !in_array($info['mime'], ['image/png', 'image/jpeg', 'image/webp'], true)) {
        jsonResponse(['success' => false, 'message' => 'الصيغ المدعومة: PNG أو JPG أو WebP'], 400);
    }
    $mime = $info['mime'];
    // تصغير الصورة إلى 512px كحد أقصى لتوفير المساحة (إن توفرت GD)
    if (function_exists('imagecreatefromstring')) {
        $srcImg = @imagecreatefromstring($raw);
        if ($srcImg !== false) {
            $w = imagesx($srcImg); $h = imagesy($srcImg);
            if ($w > 512 || $h > 512) {
                $scale = min(512 / $w, 512 / $h);
                $nw = max(1, (int)round($w * $scale)); $nh = max(1, (int)round($h * $scale));
                $dst = imagecreatetruecolor($nw, $nh);
                imagesavealpha($dst, true);
                imagealphablending($dst, false);
                imagefill($dst, 0, 0, imagecolorallocatealpha($dst, 0, 0, 0, 127));
                imagealphablending($dst, true);
                imagecopyresampled($dst, $srcImg, 0, 0, 0, 0, $nw, $nh, $w, $h);
                ob_start(); imagepng($dst); $raw = ob_get_clean();
                $mime = 'image/png';
                imagedestroy($dst);
            }
            imagedestroy($srcImg);
        }
    }
    setSetting($pdo, 'custom_icon', base64_encode($raw));
    setSetting($pdo, 'custom_icon_mime', $mime);
    $newV = (string)(intval(getSetting($pdo, 'icon_version', '1')) + 1);
    setSetting($pdo, 'icon_version', $newV);
    addAuditLog($pdo, 'تغيير أيقونة التطبيق', 'رُفعت أيقونة مخصّصة (' . $mime . ')');
    jsonResponse(['success' => true, 'v' => $newV]);
}

