/* — رفع دفعة أرقام بطاقات (سطر لكل رقم) — */
if ($action === 'cards_upload') {
    requirePermission('inventory.manage');
    $numbersRaw = (string)($_POST['numbers'] ?? '');
    $categoryId = intval($_POST['category_id'] ?? 0) ?: null;

    $lines = preg_split('/\r\n|\r|\n/', $numbersRaw);
    $numbers = [];
    foreach ($lines as $line) {
        $n = trim($line);
        if ($n !== '' && mb_strlen($n) <= 100) $numbers[$n] = true; // إزالة التكرار داخل الدفعة
    }
    $numbers = array_keys($numbers);
    if (!count($numbers)) jsonResponse(['success' => false, 'message' => 'لم يتم العثور على أي أرقام صالحة'], 400);
    if (count($numbers) > 2000) jsonResponse(['success' => false, 'message' => 'الحد الأقصى 2000 رقم في الدفعة الواحدة'], 400);

    // استبعاد الأرقام الموجودة مسبقاً في المخزن
    $placeholders = implode(',', array_fill(0, count($numbers), '?'));
    $existing = $pdo->prepare("SELECT card_number FROM cards_pool WHERE card_number IN ($placeholders)");
    $existing->execute($numbers);
    $skip = array_column($existing->fetchAll(), 'card_number');
    $skipMap = array_fill_keys($skip, true);

    $now = date('Y-m-d H:i:s');
    // INSERT OR IGNORE + الفهرس الفريد = استحالة دخول رقم مكرر حتى مع رفع متزامن
    $ins = $pdo->prepare("INSERT OR IGNORE INTO cards_pool (card_number, category_id, created_at) VALUES (?, ?, ?)");
    $added = 0;
    $pdo->beginTransaction();
    try {
        foreach ($numbers as $n) {
            if (isset($skipMap[$n])) continue;
            $ins->execute([$n, $categoryId, $now]);
            $added += $ins->rowCount();
        }
        $pdo->commit();
    } catch (Exception $e) {
        $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر حفظ الأرقام'], 500);
    }
    $ignored = count($numbers) - count($skip) - $added; // مكررات صُدَّت بالفهرس الفريد
    addAuditLog($pdo, 'رفع أرقام بطاقات', "أُضيف: $added، مكرر: " . (count($skip) + $ignored));
    jsonResponse(['success' => true, 'added' => $added, 'skipped' => count($skip) + $ignored]);
}

