/* — إرسال بطاقة/بطاقات لزبون (مع إشعار فوري يحمل الأرقام) — */
if ($action === 'card_send') {
    requirePermission('sales.create');
    $targetCustomerId = intval($_POST['customer_id'] ?? 0);
    $cardId = intval($_POST['card_id'] ?? 0);
    $categoryId = intval($_POST['category_id'] ?? 0) ?: null;
    $qty = max(1, min(20, intval($_POST['quantity'] ?? 1)));

    if ($targetCustomerId <= 0) jsonResponse(['success' => false, 'message' => 'اختر الزبون'], 400);
    $cRow = $pdo->prepare("SELECT id, full_name FROM customers WHERE id = ?");
    $cRow->execute([$targetCustomerId]);
    $targetCustomer = $cRow->fetch();
    if (!$targetCustomer) jsonResponse(['success' => false, 'message' => 'الزبون غير موجود'], 404);

    $pdo->beginTransaction();
    try {
        $picked = [];
        if ($cardId > 0) {
            $one = $pdo->prepare("SELECT * FROM cards_pool WHERE id = ? AND status = 'available'");
            $one->execute([$cardId]);
            $card = $one->fetch();
            if (!$card) { $pdo->rollBack(); jsonResponse(['success' => false, 'message' => 'هذه البطاقة غير متاحة (ربما أُرسلت مسبقاً)'], 400); }
            $picked = [$card];
        } else {
            $sql = "SELECT * FROM cards_pool WHERE status = 'available'";
            $params = [];
            if ($categoryId) { $sql .= " AND category_id = ?"; $params[] = $categoryId; }
            $sql .= " ORDER BY id ASC LIMIT " . intval($qty);
            $pick = $pdo->prepare($sql);
            $pick->execute($params);
            $picked = $pick->fetchAll();
            if (count($picked) < $qty) {
                $pdo->rollBack();
                jsonResponse(['success' => false, 'message' => 'العدد المتاح في المخزن غير كافٍ (المتاح: ' . count($picked) . ')'], 400);
            }
        }

        $now = date('Y-m-d H:i:s');
        $upd = $pdo->prepare("UPDATE cards_pool SET status = 'sent', sent_to_customer_id = ?, sent_at = ?, sent_by = ? WHERE id = ? AND status = 'available'");
        $numbers = [];
        foreach ($picked as $card) {
            $upd->execute([$targetCustomerId, $now, $user['id'], $card['id']]);
            if ($upd->rowCount() !== 1) { $pdo->rollBack(); jsonResponse(['success' => false, 'message' => 'تعارض: بطاقة أُرسلت للتو من مستخدم آخر، أعد المحاولة'], 409); }
            $numbers[] = $card['card_number'];
        }
        $pdo->commit();
    } catch (Exception $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر إرسال البطاقة'], 500);
    }

    $count = count($numbers);
    $title = $count === 1 ? '🎫 وصلتك بطاقة جديدة' : "🎫 وصلتك $count بطاقات جديدة";
    $body = ($count === 1 ? 'رقم البطاقة: ' : "أرقام البطاقات:\n") . implode("\n", $numbers);
    notifyCustomer($pdo, $targetCustomerId, $title, $body);
    addAuditLog($pdo, 'إرسال بطاقات لزبون', $targetCustomer['full_name'] . " × $count");
    jsonResponse(['success' => true, 'sent' => $count, 'numbers' => $numbers]);
}

