/* — سجل البطاقات: كل بطاقة وصلت لزبون (شراء ذاتي أو إرسال يدوي) مع الوقت والتاريخ — */
if ($action === 'cards_log_list') {
    requirePermission('sales.view');
    $search = trim($_GET['search'] ?? '');
    $sql = "SELECT cp.id, cp.card_number, cp.sent_at, cp.sold_via_portal, cp.sale_price,
                   cc.name AS category_name, cc.color AS category_color,
                   c.full_name AS customer_name, c.username AS customer_username,
                   u.full_name AS sender_name
            FROM cards_pool cp
            LEFT JOIN card_categories cc ON cc.id = cp.category_id
            LEFT JOIN customers c ON c.id = cp.sent_to_customer_id
            LEFT JOIN users u ON u.id = cp.sent_by
            WHERE cp.status = 'sent'";
    $params = [];
    if ($search !== '') {
        $sql .= " AND (cp.card_number LIKE ? OR c.full_name LIKE ? OR c.username LIKE ?)";
        $params[] = "%$search%"; $params[] = "%$search%"; $params[] = "%$search%";
    }
    $sql .= " ORDER BY cp.sent_at DESC LIMIT 300";
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);

    $todayPrefix = date('Y-m-d');
    $sumStmt = $pdo->prepare("SELECT COUNT(*) AS total,
        SUM(CASE WHEN substr(sent_at, 1, 10) = ? THEN 1 ELSE 0 END) AS today,
        SUM(CASE WHEN sold_via_portal = 1 THEN 1 ELSE 0 END) AS via_portal
        FROM cards_pool WHERE status = 'sent'");
    $sumStmt->execute([$todayPrefix]);
    $summary = $sumStmt->fetch();

    jsonResponse(['success' => true, 'data' => $stmt->fetchAll(), 'summary' => [
        'total' => intval($summary['total'] ?? 0),
        'today' => intval($summary['today'] ?? 0),
        'via_portal' => intval($summary['via_portal'] ?? 0),
    ]]);
}

