/* — مراجعة إيصال: قبول (مع خيار تسديد الدين تلقائياً) أو رفض — */
if ($action === 'receipt_review') {
    requirePermission('debts.manage');
    $id = intval($_POST['id'] ?? 0);
    $decision = $_POST['decision'] ?? '';
    $reviewNote = sanitizeInput($_POST['review_note'] ?? '');
    $applyToDebt = intval($_POST['apply_to_debt'] ?? 0) === 1;
    $applyToBalance = intval($_POST['apply_to_balance'] ?? 0) === 1;

    if (!in_array($decision, ['approved', 'rejected'], true)) {
        jsonResponse(['success' => false, 'message' => 'قرار غير صالح'], 400);
    }
    if ($applyToDebt && $applyToBalance) {
        jsonResponse(['success' => false, 'message' => 'اختر إما تسديد الدين أو شحن الرصيد، وليس الاثنين معاً'], 400);
    }
    $stmt = $pdo->prepare("SELECT * FROM payment_receipts WHERE id = ?");
    $stmt->execute([$id]);
    $receipt = $stmt->fetch();
    if (!$receipt) jsonResponse(['success' => false, 'message' => 'الإيصال غير موجود'], 404);
    if ($receipt['status'] !== 'pending') jsonResponse(['success' => false, 'message' => 'تمت مراجعة هذا الإيصال مسبقاً'], 400);

    $now = date('Y-m-d H:i:s');
    $applied = 0.0;
    $creditedBalance = 0.0;

    $pdo->beginTransaction();
    try {
        $upd = $pdo->prepare("UPDATE payment_receipts SET status = ?, reviewed_by = ?, reviewed_at = ?, review_note = ? WHERE id = ?");
        $upd->execute([$decision, $user['id'], $now, $reviewNote, $id]);

        if ($decision === 'approved' && $applyToDebt) {
            // تطبيق المبلغ على أقدم الديون المفتوحة أولاً
            $remainingToApply = floatval($receipt['amount']);
            $open = $pdo->prepare("SELECT * FROM debts WHERE customer_id = ? AND status != 'paid' ORDER BY created_at ASC");
            $open->execute([$receipt['customer_id']]);
            foreach ($open->fetchAll() as $debt) {
                if ($remainingToApply <= 0.009) break;
                $pay = min($remainingToApply, floatval($debt['remaining_amount']));
                $pdo->prepare("INSERT INTO debt_payments (debt_id, amount, note, user_id, paid_at) VALUES (?, ?, ?, ?, ?)")
                    ->execute([$debt['id'], $pay, 'تسديد عبر إيصال #' . $id, $user['id'], $now]);
                $newRem = floatval($debt['remaining_amount']) - $pay;
                $pdo->prepare("UPDATE debts SET remaining_amount = ?, status = ? WHERE id = ?")
                    ->execute([max(0, $newRem), $newRem <= 0.009 ? 'paid' : 'open', $debt['id']]);
                $remainingToApply -= $pay;
                $applied += $pay;
            }
        }

        if ($decision === 'approved' && $applyToBalance) {
            $creditedBalance = adjustCustomerBalance($pdo, intval($receipt['customer_id']), 'receipt_credit', floatval($receipt['amount']), 'شحن رصيد عبر إيصال #' . $id, $user['id'], null, $id);
        }

        $pdo->commit();
    } catch (Exception $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر حفظ المراجعة'], 500);
    }

    if ($decision === 'approved') {
        $msg = 'تم قبول إيصال الدفع بمبلغ ' . money($receipt['amount']);
        if ($applied > 0) $msg .= " وتم تسديد " . money($applied) . " من دينك";
        if ($applyToBalance) $msg .= " وتم شحن رصيدك. رصيدك الحالي: " . money($creditedBalance);
        notifyCustomer($pdo, intval($receipt['customer_id']), '✅ تم قبول إيصالك', $msg . ($reviewNote ? "\n" . $reviewNote : ''));
    } else {
        notifyCustomer($pdo, intval($receipt['customer_id']), '❌ تم رفض الإيصال', ($reviewNote ?: 'يرجى التواصل مع الإدارة للتوضيح'));
    }
    addAuditLog($pdo, 'مراجعة إيصال دفع', "#$id — $decision" . ($applied > 0 ? ' — سُدد دين: ' . money($applied) : '') . ($applyToBalance ? ' — شُحن رصيد: ' . money($receipt['amount']) : ''));
    jsonResponse(['success' => true, 'applied' => $applied, 'credited_balance' => $creditedBalance]);
}

