/* — سحب بطاقة مُرسلة من زبون: إرجاعها للمخزن أو حذفها نهائياً — */
if ($action === 'card_withdraw') {
    requirePermission('inventory.manage');
    $cardId = intval($_POST['card_id'] ?? 0);
    $mode = ($_POST['mode'] ?? 'pool') === 'delete' ? 'delete' : 'pool';
    $note = sanitizeInput($_POST['note'] ?? '');
    if ($cardId <= 0) jsonResponse(['success' => false, 'message' => 'حدد البطاقة أولاً'], 400);

    $stmt = $pdo->prepare("SELECT cp.*, cc.name AS category_name, c.full_name AS customer_name, c.username AS customer_username
                           FROM cards_pool cp
                           LEFT JOIN card_categories cc ON cc.id = cp.category_id
                           LEFT JOIN customers c ON c.id = cp.sent_to_customer_id
                           WHERE cp.id = ?");
    $stmt->execute([$cardId]);
    $card = $stmt->fetch();
    if (!$card) jsonResponse(['success' => false, 'message' => 'البطاقة غير موجودة'], 404);
    if ($card['status'] !== 'sent') jsonResponse(['success' => false, 'message' => 'هذه البطاقة غير مُرسلة لأي زبون'], 400);

    $custId = intval($card['sent_to_customer_id'] ?? 0) ?: null;
    $pdo->beginTransaction();
    try {
        if ($mode === 'pool') {
            $pdo->prepare("UPDATE cards_pool SET status='available', sent_to_customer_id=NULL, sent_at=NULL, sent_by=NULL, sold_via_portal=0, sale_price=NULL WHERE id = ? AND status='sent'")
                ->execute([$cardId]);
        } else {
            $pdo->prepare("DELETE FROM cards_pool WHERE id = ?")->execute([$cardId]);
        }
        $pdo->prepare("INSERT INTO card_withdrawals (card_id, card_number, category_name, customer_id, customer_name, returned_to_pool, note, withdrawn_by, withdrawn_by_name, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
            ->execute([$mode === 'pool' ? $cardId : null, $card['card_number'], $card['category_name'] ?? '', $custId, $card['customer_name'] ?? '', $mode === 'pool' ? 1 : 0, $note, $user['id'], $user['full_name'] ?? '', date('Y-m-d H:i:s')]);
        $pdo->commit();
    } catch (Exception $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        jsonResponse(['success' => false, 'message' => 'تعذر سحب البطاقة'], 500);
    }

    if ($custId && !empty($card['customer_username'])) {
        notifyCustomer($pdo, $custId, '📤 تم سحب بطاقة من حسابك', 'قامت الإدارة بسحب البطاقة رقم ' . $card['card_number'] . ($note !== '' ? " — السبب: $note" : '') . '. للاستفسار افتح تذكرة دعم من تبويب «الدعم»');
    }
    addAuditLog($pdo, 'سحب بطاقة من زبون', 'البطاقة ' . $card['card_number'] . ' من ' . ($card['customer_name'] ?: '—') . ($mode === 'pool' ? ' (أُعيدت للمخزن)' : ' (حُذفت نهائياً)') . ($note !== '' ? " — $note" : ''));
    jsonResponse(['success' => true, 'returned_to_pool' => $mode === 'pool' ? 1 : 0]);
}

