/* — رد الإدارة على تذكرة: يصل الزبون إشعار Push حتى خارج التطبيق — */
if ($action === 'ticket_reply') {
    requirePermission('support.manage');
    $tid = intval($_POST['ticket_id'] ?? 0);
    $body = trim((string)($_POST['body'] ?? ''));
    if ($body === '') jsonResponse(['success' => false, 'message' => 'اكتب ردك أولاً'], 400);
    if (mb_strlen($body) > 2000) jsonResponse(['success' => false, 'message' => 'الرسالة طويلة جداً (بحد أقصى 2000 حرف)'], 400);
    $t = $pdo->prepare("SELECT t.*, c.full_name AS customer_name FROM support_tickets t JOIN customers c ON c.id = t.customer_id WHERE t.id = ?");
    $t->execute([$tid]);
    $ticket = $t->fetch();
    if (!$ticket) jsonResponse(['success' => false, 'message' => 'التذكرة غير موجودة'], 404);
    $now = date('Y-m-d H:i:s');
    $pdo->prepare("INSERT INTO ticket_messages (ticket_id, sender, sender_name, body, created_at) VALUES (?, 'staff', ?, ?, ?)")
        ->execute([$tid, $user['full_name'] ?? '', $body, $now]);
    $pdo->prepare("UPDATE support_tickets SET last_msg_at = ?, unread_customer = unread_customer + 1, status = 'open', closed_at = NULL WHERE id = ?")
        ->execute([$now, $tid]);
    notifyCustomer($pdo, intval($ticket['customer_id']), '💬 رد جديد من الدعم الفني', mb_substr($body, 0, 140) . (mb_strlen($body) > 140 ? '…' : ''));
    addAuditLog($pdo, 'رد على تذكرة دعم', 'تذكرة #' . $tid . ' — ' . $ticket['customer_name']);
    jsonResponse(['success' => true]);
}

/* — إغلاق/إعادة فتح تذكرة — */
if ($action === 'ticket_set_status') {
    requirePermission('support.manage');
    $tid = intval($_POST['ticket_id'] ?? 0);
    $status = ($_POST['status'] ?? '') === 'closed' ? 'closed' : 'open';
    $t = $pdo->prepare("SELECT t.*, c.full_name AS customer_name FROM support_tickets t JOIN customers c ON c.id = t.customer_id WHERE t.id = ?");
    $t->execute([$tid]);
    $ticket = $t->fetch();
    if (!$ticket) jsonResponse(['success' => false, 'message' => 'التذكرة غير موجودة'], 404);
    $now = date('Y-m-d H:i:s');
    if ($status === 'closed') {
        $pdo->prepare("UPDATE support_tickets SET status = 'closed', closed_at = ? WHERE id = ?")->execute([$now, $tid]);
        $pdo->prepare("INSERT INTO ticket_messages (ticket_id, sender, sender_name, body, created_at) VALUES (?, 'system', 'النظام', 'أُغلقت هذه التذكرة ✅ — يمكنك إرسال رسالة جديدة لإعادة فتحها في أي وقت', ?)")
            ->execute([$tid, $now]);
        notifyCustomer($pdo, intval($ticket['customer_id']), '📁 أُغلقت تذكرتك #' . $tid, 'إذا احتجت شيئاً آخر أرسل رسالة جديدة وسنكون بالخدمة');
        addAuditLog($pdo, 'إغلاق تذكرة دعم', 'تذكرة #' . $tid . ' — ' . $ticket['customer_name']);
    } else {
        $pdo->prepare("UPDATE support_tickets SET status = 'open', closed_at = NULL WHERE id = ?")->execute([$tid]);
        addAuditLog($pdo, 'إعادة فتح تذكرة دعم', 'تذكرة #' . $tid . ' — ' . $ticket['customer_name']);
    }
    jsonResponse(['success' => true]);
}

/* — عدّادات شريط الإدارة (إيصالات وطلبات معلّقة) — */
if ($action === 'staff_portal_summary') {
    $out = ['pending_receipts' => 0, 'pending_requests' => 0, 'support_unread' => 0];
    if (can('support.manage')) {
        $out['support_unread'] = intval($pdo->query("SELECT COALESCE(SUM(unread_admin),0) c FROM support_tickets WHERE status = 'open'")->fetch()['c']);
    }
    if (can('debts.manage')) {
        $out['pending_receipts'] = intval($pdo->query("SELECT COUNT(*) c FROM payment_receipts WHERE status='pending'")->fetch()['c']);
    }
    if (can('sales.view')) {
        $out['pending_requests'] = intval($pdo->query("SELECT COUNT(*) c FROM purchase_requests WHERE status='pending'")->fetch()['c']);
    }
    jsonResponse(['success' => true] + $out);
}

/* ─── لم يتم التعرف على الإجراء ─── */
jsonResponse(['success' => false, 'message' => 'إجراء غير معروف'], 400);

    exit;
}

/* ─── صفحة الإعداد الأولي: لا يوجد مالك بعد ─── */
if (!ownerExists($pdo) && $page !== 'setup') {
    header('Location: ?page=setup');
    exit;
}

/* ─── حماية الصفحات: تسجيل الدخول مطلوب لكل الصفحات عدا الدخول/الإعداد/بوابة الزبائن ─── */
$publicPages = ['login', 'setup', 'portal'];
if (!in_array($page, $publicPages, true) && !isLoggedIn()) {
    header('Location: ?page=login');
    exit;
}
// وضع الصيانة: بوابة الزبائن كاملة تتحول لشاشة الصيانة (النظام يبقى متاحاً للموظفين)
if ($page === 'portal' && isMaintenanceOn($pdo)) {
    renderMaintenanceScreen($pdo);
}
// بوابة الزبائن بدون جلسة زبون → صفحة الدخول الموحّدة (لا توجد صفحة دخول منفصلة للزبائن)
if ($page === 'portal' && !isCustomerLoggedIn() && ownerExists($pdo)) {
    header('Location: ?page=login');
    exit;
}
// زبون مسجّل دخوله يفتح صفحة الدخول → توجيه مباشر للبوابة
if ($page === 'login' && isCustomerLoggedIn() && !isLoggedIn()) {
    header('Location: ?page=portal');
    exit;
}

