    <script>
    /* الوضع الداكن: تطبيق فوري قبل رسم أي شيء لمنع وميض الثيم الفاتح */
    (function () {
        try { if (localStorage.getItem('ansnet_theme') === 'dark') document.documentElement.classList.add('dark'); } catch (e) {}
        function syncThemeMeta() {
            var m = document.getElementById('themeColorMeta');
            if (m) m.setAttribute('content', document.documentElement.classList.contains('dark') ? '#0D0A1C' : '#6C43FF');
        }
        function updateThemeButtons() {
            var dark = document.documentElement.classList.contains('dark');
            document.querySelectorAll('[data-theme-toggle]').forEach(function (btn) {
                var ic = btn.querySelector('i'); if (ic) ic.className = 'ph ' + (dark ? 'ph-sun' : 'ph-moon');
                var lb = btn.querySelector('.theme-label'); if (lb) lb.textContent = dark ? 'الوضع الفاتح' : 'الوضع الداكن';
                btn.title = dark ? 'التبديل للوضع الفاتح' : 'التبديل للوضع الداكن';
            });
        }
        var wiping = false;
        /* التبديل السينمائي: ستارة غروب/شروق تمسح الشاشة ويتبدّل الثيم خلفها */
        window.toggleTheme = function () {
            if (wiping) return;
            var toDark = !document.documentElement.classList.contains('dark');
            var reduce = false;
            try { reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}
            var instant = document.documentElement.classList.contains('lite') || reduce;
            function applyTheme() {
                document.documentElement.classList.toggle('dark', toDark);
                try { localStorage.setItem('ansnet_theme', toDark ? 'dark' : 'light'); } catch (e) {}
                syncThemeMeta(); updateThemeButtons();
            }
            if (instant) { applyTheme(); return; }
            wiping = true;
            var w = document.createElement('div');
            w.className = 'theme-wipe ' + (toDark ? 'to-dark' : 'to-light');
            document.body.appendChild(w);
            setTimeout(applyTheme, 620);
            setTimeout(function () { if (w.parentNode) w.parentNode.removeChild(w); wiping = false; }, 1320);
        };
        window.syncThemeUI = function () { syncThemeMeta(); updateThemeButtons(); };
        document.addEventListener('DOMContentLoaded', function () { syncThemeMeta(); updateThemeButtons(); });
    })();
    </script>
    <script>
    /* وضع الأداء (Lite): تفعيل تلقائي على الأجهزة الضعيفة أو يدوياً — قبل رسم أي شيء */
    (function () {
        try {
            var saved = localStorage.getItem('ansnet_lite');
            var auto = (navigator.deviceMemory && navigator.deviceMemory <= 3)
                || (navigator.hardwareConcurrency && navigator.hardwareConcurrency <= 4)
                || (navigator.connection && navigator.connection.saveData);
            if (saved === '1' || (saved === null && auto)) document.documentElement.classList.add('lite');
        } catch (e) {}
        window.toggleLiteMode = function () {
            var on = document.documentElement.classList.toggle('lite');
            try { localStorage.setItem('ansnet_lite', on ? '1' : '0'); } catch (e) {}
            return on;
        };
    })();
    </script>
