        }
        html.dark .modal-box { background: rgba(23,17,44,0.94); border-color: rgba(150,130,220,0.26); box-shadow: var(--shadow-lg), inset 0 1px 0 rgba(190,170,255,0.1); }
        html.dark .input, html.dark .select, html.dark textarea.input {
            background: rgba(13,10,28,0.55); border-color: rgba(150,130,220,0.26);
            color: var(--text-dark); box-shadow: inset 0 1px 3px rgba(0,0,0,0.35);
        }
        html.dark .input:focus, html.dark .select:focus, html.dark textarea.input:focus {
            background: rgba(13,10,28,0.85); border-color: rgba(139,104,255,0.6); box-shadow: 0 0 0 4px rgba(139,104,255,0.18);
        }
        html.dark .select option { background: #171233; color: #F3EFFF; }
        html.dark .input::placeholder, html.dark textarea.input::placeholder { color: #6F679A; }
        html.dark .toast { background: rgba(24,18,46,0.92); border-color: rgba(150,130,220,0.26); box-shadow: var(--shadow-lg); }
        html.dark .tab-btn.active { background: rgba(139,104,255,0.22); color: var(--text-dark); box-shadow: none; }
        html.dark .btn-outline { background: rgba(24,18,46,0.6); border-color: rgba(139,104,255,0.45); color: var(--primary-light); }
        html.dark .btn-outline.danger { border-color: rgba(255,107,112,0.45); color: var(--danger); }
        html.dark .nav-link:hover, html.dark .user-chip:hover { background: rgba(139,104,255,0.1); }
        html.dark .perm-item { background: rgba(24,18,46,0.55); }
        html.dark .sidebar-overlay { background: rgba(0,0,0,0.62); }
        html.dark .color-dot.selected { border-color: #F3EFFF; }
        html.dark table.data-table thead th { background: rgba(139,104,255,0.08); }
        html.dark table.data-table tbody tr:hover { background: rgba(139,104,255,0.06); }
        html.dark .portal-dock { background: rgba(16,12,36,0.86); border-color: rgba(150,130,220,0.22); }
        html.dark .portal-icon-btn, html.dark .notif-item, html.dark .card-number-item,
        html.dark .pay-method-card, html.dark .buy-card-tile, html.dark .install-hint,
        html.dark .qty-stepper {
            background: rgba(24,18,46,0.7); border-color: rgba(150,130,220,0.2);
        }
        html.dark .notif-item.unread { background: rgba(139,104,255,0.14); }
        html.lite.dark body::before { background: #12102A; }
        html.lite.dark .sidebar, html.lite.dark .portal-dock, html.lite.dark .mobile-topbar { background: rgba(18,14,38,0.98) !important; }
        html.lite.dark .card, html.lite.dark .stat-card, html.lite.dark .modal-box, html.lite.dark .auth-card,
        html.lite.dark .card-number-item, html.lite.dark .pay-method-card, html.lite.dark .notif-item,
        html.lite.dark .buy-card-tile, html.lite.dark .portal-icon-btn { background: #171233 !important; }

        /* زر تبديل الثيم في الشريط الجانبي */
        .theme-btn {
            display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 12px; margin-bottom: 8px;
            border-radius: 14px; border: 1px solid var(--border-light); background: rgba(255,255,255,0.5);
            cursor: pointer; font-family: var(--font-body); font-weight: 700; font-size: 12.5px; color: var(--text-body);
            transition: all 0.25s;
        }
        .theme-btn i { font-size: 16px; color: var(--gold); }
        .theme-btn:hover { border-color: rgba(139,104,255,0.4); color: var(--primary); }
        html.dark .theme-btn { background: rgba(24,18,46,0.6); }

        /* ═══════════════════════ محادثة الدعم الفني (نمط واتساب) ═══════════════════════ */
        .support-layout { display: grid; grid-template-columns: 340px 1fr; gap: 16px; align-items: stretch; }
        .ticket-list-pane, .chat-pane { min-height: 64vh; max-height: 76vh; display: flex; flex-direction: column; }
        .ticket-list-scroll { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 4px; margin-top: 10px; padding-inline-end: 2px; }
        .ticket-item {
            display: flex; align-items: center; gap: 11px; padding: 11px 12px; border-radius: 16px;
            cursor: pointer; border: 1px solid transparent; transition: all 0.2s;
        }
        .ticket-item:hover { background: rgba(108,67,255,0.07); }
        .ticket-item.active { background: var(--primary-soft); border-color: rgba(139,104,255,0.35); }
        .ticket-avatar {
            width: 42px; height: 42px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center;
            background: var(--gold-metal); color: #3A2800; font-weight: 900; font-size: 16px; font-family: var(--font-display);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.5);
        }
        .ticket-item-info { flex: 1; min-width: 0; }
        .ticket-item-name { font-weight: 800; font-size: 13.5px; color: var(--text-dark); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .ticket-item-snippet { font-size: 12px; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 2px; }
        .ticket-item-meta { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; flex-shrink: 0; }
        .ticket-item-time { font-size: 10.5px; color: var(--text-muted); }
        .ticket-unread {
            min-width: 19px; height: 19px; padding: 0 5px; border-radius: 10px; background: var(--success); color: #fff;
            font-size: 11px; font-weight: 800; display: flex; align-items: center; justify-content: center;
        }
        .ticket-status-chip { font-size: 10px; font-weight: 800; padding: 2px 8px; border-radius: 999px; }
        .ticket-status-chip.open { background: var(--success-soft); color: var(--success); }
        .ticket-status-chip.closed { background: var(--danger-soft); color: var(--danger); }
        .chat-head { display: flex; align-items: center; gap: 11px; padding-bottom: 12px; border-bottom: 1px solid var(--border-light); flex-wrap: wrap; }
        .chat-head-info { flex: 1; min-width: 0; }
        .chat-head-name { font-weight: 800; font-size: 14.5px; color: var(--text-dark); }
        .chat-head-sub { font-size: 11.5px; color: var(--text-muted); direction: ltr; text-align: right; }
        .chat-back-btn { display: none; }
        .chat-body { flex: 1; overflow-y: auto; padding: 15px 4px; display: flex; flex-direction: column; gap: 9px; }
        .chat-bubble {
            max-width: 80%; padding: 10px 14px; border-radius: 18px; font-size: 13.5px; line-height: 1.7;
            word-break: break-word; white-space: pre-wrap; position: relative; box-shadow: var(--shadow-sm);
        }
        .chat-bubble .cb-meta { display: flex; gap: 6px; align-items: center; font-size: 10px; opacity: 0.75; margin-top: 4px; font-weight: 600; }
        .chat-bubble.cb-me {
            align-self: flex-end; color: #fff; border-bottom-left-radius: 6px;
            background: linear-gradient(140deg, #7A52FF 0%, #A66BF2 100%);
        }
        .chat-bubble.cb-them {
            align-self: flex-start; color: var(--text-dark); border-bottom-right-radius: 6px;
            background: rgba(255,255,255,0.85); border: 1px solid var(--border-light);
        }
        html.dark .chat-bubble.cb-them { background: rgba(30,23,56,0.9); }
        .chat-bubble.cb-system {
            align-self: center; max-width: 92%; text-align: center; font-size: 12px; font-weight: 700;
            background: var(--gold-soft); color: var(--gold); border: 1px dashed rgba(201,138,27,0.4);
            border-radius: 999px; padding: 7px 16px; box-shadow: none;
        }
        html.dark .chat-bubble.cb-system { color: var(--gold-light); border-color: rgba(232,180,74,0.4); }
        .chat-input-row { display: flex; gap: 10px; align-items: flex-end; padding-top: 12px; border-top: 1px solid var(--border-light); }
        .chat-input-row textarea { flex: 1; resize: none; min-height: 46px; max-height: 120px; }
        .chat-send-btn {
            width: 46px; height: 46px; border-radius: 50%; border: none; cursor: pointer; flex-shrink: 0;
            display: flex; align-items: center; justify-content: center; font-size: 18px; color: #fff;
