            .support-layout.show-chat .ticket-list-pane { display: none; }
            .chat-back-btn { display: inline-flex; }
            .ticket-list-pane, .chat-pane { min-height: 58vh; max-height: none; }
        }

        /* ═══════════════════════ سجل التدقيق ═══════════════════════ */
        .audit-row { display: flex; gap: 12px; padding: 12px 4px; border-bottom: 1px dashed var(--border-soft); align-items: flex-start; }
        .audit-row:last-child { border-bottom: none; }
