        .audit-action { font-weight: 800; font-size: 13.5px; color: var(--text-dark); }
        .audit-details { font-size: 12.5px; color: var(--text-body); margin-top: 2px; line-height: 1.6; word-break: break-word; }
        .audit-meta { display: flex; gap: 12px; flex-wrap: wrap; font-size: 11px; color: var(--text-muted); margin-top: 5px; }
        .audit-meta span { display: inline-flex; align-items: center; gap: 4px; }

        /* ═══════════════════════ صفحة فحص البطاقة ═══════════════════════ */
        .cc-search-wrap { position: relative; }
        .cc-search-wrap > i { position: absolute; top: 50%; transform: translateY(-50%); inset-inline-start: 16px; font-size: 18px; color: var(--text-muted); pointer-events: none; }
        .cc-search-input { padding-inline-start: 46px !important; font-size: 15.5px !important; height: 54px; border-radius: 18px !important; }
        .cc-card {
            border: 1px solid var(--border-light); border-radius: 18px; padding: 14px;
            background: rgba(255,255,255,0.55); margin-bottom: 11px;
        }
        html.dark .cc-card { background: rgba(24,18,46,0.6); }
        .cc-top { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
        .cc-num { font-weight: 800; font-size: 15.5px; letter-spacing: 1px; direction: ltr; color: var(--text-dark); font-family: 'Courier New', monospace; }
        .cc-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px 14px; margin-top: 11px; }
        .cc-field { font-size: 12px; color: var(--text-muted); }
        .cc-field b { display: block; font-size: 13px; color: var(--text-dark); font-weight: 700; margin-top: 1px; }

        /* ═══════════════════════ إعدادات: معاينة الأيقونة + الصيانة ═══════════════════════ */
        .icon-preview-img {
            width: 76px; height: 76px; border-radius: 20px; object-fit: cover; flex-shrink: 0;
