            table.data-table { font-size: 12.5px; }
        }
    </style>
</head>
<body>
    <div class="bg-orb orb1"></div>
    <div class="bg-orb orb2"></div>
    <div class="bg-orb orb3"></div>
    <div id="toastRoot"></div>

    <?php if (!ownerExists($pdo)): ?>
        <?php renderSetupScreen(); ?>
        <?php renderScripts($currentUserData, $currentPerms); ?>
    <?php elseif ($page === 'portal'): ?>
        <?php renderPortalShell($shopName); ?>
        <?php renderPortalScripts($shopName); ?>
    <?php elseif (!isLoggedIn()): ?>
        <?php renderLoginScreen($shopName); ?>
        <?php renderScripts($currentUserData, $currentPerms); ?>
    <?php else: ?>
        <?php renderAppShell($shopName, $currentUserData, $currentPerms); ?>
        <?php renderGlobalModals(); ?>
        <?php renderScripts($currentUserData, $currentPerms); ?>
    <?php endif; ?>
</body>
</html>
