/* ════════════════════════════════════════════════════════════════
 *  دوال العرض (Render Functions)
 * ════════════════════════════════════════════════════════════════ */

function renderSetupScreen(): void
{
    ?>
    <div class="auth-screen">
        <div class="auth-box">
            <div class="auth-logo">
                <div class="auth-logo-icon"><i class="ph-duotone ph-crown-simple"></i></div>
