/* ════════════════════════════════════════════════════════════════
 *  السكريبتات — بوابة الزبائن
 * ════════════════════════════════════════════════════════════════ */
function renderPortalScripts(string $shopName): void
{
    ?>
    <script>
    const PORTAL_CACHE_KEY = 'ansnet_portal_me';
    const P_SHOP = <?php echo json_encode($shopName, JSON_UNESCAPED_UNICODE); ?>;
    const SHARE_URL = location.origin + location.pathname;

    /* نسخ رابط الموقع */
    function copyPortalLink() { copyText(SHARE_URL); }

    /* مشاركة الرابط عبر تطبيقات الجهاز (واتساب وغيره) — وإن لم تتوفر يُنسخ الرابط */
    async function sharePortalLink() {
        const text = 'تطبيق ' + P_SHOP + ' 💎 — اشترِ بطاقات الإنترنت وتابع حسابك من جوالك:';
        if (navigator.share) {
            try {
                await navigator.share({ title: P_SHOP, text: text, url: SHARE_URL });
                return;
            } catch (e) {
                if (e && e.name === 'AbortError') return; // المستخدم أغلق نافذة المشاركة
            }
        }
        copyText(text + ' ' + SHARE_URL);
    }
    let P_STATE = null;

    /* ═══ أدوات مشتركة ═══ */
    function apiGet(action, params = {}) {
        const qs = new URLSearchParams({ action, ...params }).toString();
        return fetch('?' + qs, { credentials: 'same-origin' })
            .then(r => r.json())
            .catch(() => ({ success: false, offline: true, message: 'أنت بدون اتصال' }));
    }
    function apiPost(action, data = {}) {
        const fd = new FormData();
        fd.append('action', action);
        for (const k in data) fd.append(k, data[k]);
        return fetch('?action=' + encodeURIComponent(action), { method: 'POST', body: fd, credentials: 'same-origin' })
            .then(r => r.json())
            .catch(() => ({ success: false, offline: true, message: 'أنت بدون اتصال — حاول عند عودة النت' }));
    }
    function escapeHtml(str) {
        if (str === null || str === undefined) return '';
        return String(str).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
    }
    function money(n) {
        n = parseFloat(n) || 0;
        const isInt = Math.round(n) === n;
        return n.toLocaleString('en-US', { minimumFractionDigits: isInt ? 0 : 2, maximumFractionDigits: 2 }) + ' ₪';
    }
    function formatDateTime(dateStr) {
        if (!dateStr) return '—';
        const d = new Date(String(dateStr).replace(' ', 'T'));
        if (isNaN(d)) return dateStr;
        return d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'short' }) + ' — ' + d.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
    }
    function showToast(type, title, msg = '') {
        const root = document.getElementById('toastRoot');
        const icons = { success: 'ph-check-circle', error: 'ph-x-circle', warning: 'ph-warning', info: 'ph-info' };
        const el = document.createElement('div');
        el.className = `toast toast-${type}`;
        el.innerHTML = `<div class="toast-icon"><i class="ph-fill ${icons[type] || icons.info}"></i></div>
            <div class="toast-body"><div class="toast-title">${escapeHtml(title)}</div>${msg ? `<div class="toast-msg">${escapeHtml(msg)}</div>` : ''}</div>
            <div class="toast-progress"></div>`;
        el.onclick = () => { el.classList.add('hide'); setTimeout(() => el.remove(), 300); };
        root.appendChild(el);
        requestAnimationFrame(() => el.classList.add('show'));
        setTimeout(() => { el.classList.add('hide'); setTimeout(() => el.remove(), 300); }, 3800);
    }
    function openPortalModal(id) { document.getElementById(id).classList.add('show'); }
    function closePortalModal(id) { document.getElementById(id).classList.remove('show'); }

    function showPortalConfirm(title, msg, onConfirm, btnLabel = 'تأكيد') {
        document.getElementById('pcTitle').textContent = title;
        document.getElementById('pcMsg').textContent = msg;
        const btn = document.getElementById('pcConfirmBtn');
        btn.textContent = btnLabel;
        const newBtn = btn.cloneNode(true);
        btn.parentNode.replaceChild(newBtn, btn);
        newBtn.addEventListener('click', () => { closePortalModal('portalConfirmModal'); onConfirm(); });
        openPortalModal('portalConfirmModal');
    }
    document.querySelectorAll('.modal-overlay').forEach(ov => {
        ov.addEventListener('click', e => { if (e.target === ov) ov.classList.remove('show'); });
    });

    /* ═══ تسجيل Service Worker (أساس العمل بدون نت والإشعارات) ═══ */
    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.register('?action=sw').catch(() => {});
    }

    /* ═══════════ تطبيق البوابة ═══════════ */

    function switchPortalTab(tab) {
        // منع الوصول للتبويبات المحجوبة عند وجود دين وحجب مفعّل (الدفع يبقى متاحاً دائماً)
        if (P_STATE && P_STATE.blocked_for_debt && (tab === 'cards' || tab === 'requests')) {
            showToast('warning', 'محجوب مؤقتاً', 'سدّد دينك أولاً لتعود هذه الخدمة — تبويب الدفع متاح لك');
            tab = 'pay';
        }
        document.querySelectorAll('.portal-tab-view').forEach(v => v.classList.remove('active'));
        document.getElementById('ptab-' + tab).classList.add('active');
        document.querySelectorAll('.dock-tab').forEach(b => b.classList.toggle('active', b.dataset.ptab === tab));
        window.scrollTo({ top: 0, behavior: 'smooth' });
        if (tab === 'support') { backToPortalTickets(); loadPortalTickets(); }
        else if (portalChatTimer) { clearInterval(portalChatTimer); portalChatTimer = null; }
    }

    async function loadPortal() {
        const res = await apiGet('portal_me');
        if (res.success) {
            P_STATE = res;
            try { localStorage.setItem(PORTAL_CACHE_KEY, JSON.stringify(res)); } catch (e) {}
            document.getElementById('offlineChip').classList.remove('show');
            renderPortal(res, false);
        } else if (res.offline || !navigator.onLine) {
            let cached = null;
            try { cached = JSON.parse(localStorage.getItem(PORTAL_CACHE_KEY) || 'null'); } catch (e) {}
            document.getElementById('offlineChip').classList.add('show');
            if (cached) { P_STATE = cached; renderPortal(cached, true); }
            else document.getElementById('lockBannerBox').innerHTML = '<div class="lock-banner"><i class="ph-duotone ph-wifi-slash"></i><div style="font-weight:800;">لا يوجد اتصال ولا بيانات محفوظة بعد</div><div style="font-size:12px; color:var(--text-muted); margin-top:6px;">افتح التطبيق مرة واحدة وأنت متصل بالشبكة</div></div>';
        } else if (res.message && res.message.includes('تسجيل الدخول')) {
            window.location.href = '?page=portal';
        }
    }

    function renderPortal(s, isOffline) {
        // بطاقة الرصيد
        const balance = parseFloat(s.balance) || 0;
        document.getElementById('balanceHeroBox').innerHTML = `<div class="balance-hero">
            <div class="balance-hero-label"><i class="ph-fill ph-wallet"></i> رصيدك الحالي</div>
            <div class="balance-hero-amount">${money(balance)}</div>
            <div class="balance-hero-sub">اشترِ بطاقاتك مباشرة من الأسفل هنا، واشحن رصيدك من تبويب «الدفع»</div>
        </div>`;

        // قسم الدين: يظهر فقط إذا فعّله المالك لهذا الزبون
        const showDebt = parseInt(s.show_debt) === 1;
        document.getElementById('debtSectionBox').style.display = showDebt ? 'block' : 'none';

        // بطاقة الدين
        const debt = parseFloat(s.open_debt) || 0;
        const hero = document.getElementById('debtHeroBox');
        if (debt > 0) {
            hero.innerHTML = `<div class="debt-hero has-debt">
                <div class="debt-hero-label"><i class="ph-fill ph-hand-coins"></i> الدين المستحق عليك</div>
                <div class="debt-hero-amount">${money(debt)}</div>
                <div class="debt-hero-sub">سدّد عبر تبويب «الدفع» وارفق إشعار التحويل ليُخصم من دينك</div>
            </div>`;
        } else {
            hero.innerHTML = `<div class="debt-hero clear">
                <div class="debt-hero-label"><i class="ph-fill ph-seal-check"></i> حسابك</div>
                <div class="debt-hero-amount">لا ديون 🎉</div>
                <div class="debt-hero-sub">ذمتك صافية — شكراً لالتزامك</div>
            </div>`;
        }

        // لافتة الحجب
        const lockBox = document.getElementById('lockBannerBox');
        if (s.blocked_for_debt) {
            lockBox.innerHTML = `<div class="lock-banner">
                <i class="ph-duotone ph-lock-key"></i>
                <div style="font-weight:900; font-family:var(--font-display); font-size:16px; color:var(--text-dark);">الخدمات موقوفة حتى سداد الدين</div>
                <div style="font-size:12.5px; color:var(--text-muted); margin:8px 0 14px;">بمجرد سداد المبلغ وقبول الإيصال تعود جميع الخدمات تلقائياً</div>
                <button class="btn btn-gold" onclick="switchPortalTab('pay')"><i class="ph-bold ph-wallet"></i> الذهاب للدفع الآن</button>
            </div>`;
        } else lockBox.innerHTML = '';

        // قائمة الديون
        const debtsBox = document.getElementById('debtsListBox');
        if (!s.debts || !s.debts.length) {
            debtsBox.innerHTML = '<div class="empty-state" style="padding:20px;"><i class="ph-duotone ph-seal-check"></i><div class="empty-state-sub">لا توجد ديون مسجّلة عليك</div></div>';
        } else {
            debtsBox.innerHTML = s.debts.map(d => `
                <div class="notif-item">
                    <div class="notif-icon" style="background:linear-gradient(140deg,#F0565C,#D63A40);"><i class="ph-fill ph-hand-coins"></i></div>
                    <div style="flex:1;">
                        <div style="font-weight:800; color:var(--text-dark); font-size:14px;">${money(d.remaining_amount)} <span style="font-size:11px; color:var(--text-muted); font-weight:600;">من أصل ${money(d.original_amount)}</span></div>
                        <div style="font-size:11.5px; color:var(--text-muted); margin-top:3px;">${d.due_date ? 'الاستحقاق: ' + d.due_date : 'بدون موعد محدد'}${d.note ? ' · ' + escapeHtml(d.note) : ''}</div>
                    </div>
                </div>`).join('');
        }

        // بطاقاتي
        const cardsBox = document.getElementById('myCardsBox');
        if (!s.cards || !s.cards.length) {
            cardsBox.innerHTML = '<div class="empty-state" style="padding:24px;"><i class="ph-duotone ph-cards"></i><div class="empty-state-title">لا بطاقات بعد</div><div class="empty-state-sub">أول ما تُرسل لك بطاقة رح تظهر هنا فوراً</div></div>';
        } else {
            const srvNow = Number(s.server_now) || Math.floor(Date.now() / 1000);
            cardsBox.innerHTML = s.cards.map(c => {
                const expiresTs = Number(c.expires_ts) || 0; // ثواني بتوقيت الخادم (0 = غير مُفعّلة أو بلا مدة)
                // نُحوّل لحظة الانتهاء لتوقيت جهاز المستخدم (معالجة فرق الساعة بين الخادم والجهاز)
                const expiresAtLocal = expiresTs > 0 ? (Date.now() + (expiresTs - srvNow) * 1000) : 0;
                const isExpired = expiresAtLocal > 0 && expiresAtLocal <= Date.now();
                let statusHtml;
                if (isExpired) {
                    statusHtml = '<span class="card-badge expired"><i class="ph-fill ph-x-circle"></i> منتهية</span>';
                } else if (expiresAtLocal > 0) {
                    statusHtml = `<span class="card-badge counting" data-expire="${expiresAtLocal}"><i class="ph-fill ph-timer"></i> <span class="card-cd">--:--:--</span></span>`;
                } else {
                    statusHtml = '<span class="card-badge avail"><i class="ph-fill ph-check-circle"></i> متاح</span>';
                }
                return `
                <div class="card-number-item" data-card-id="${c.id}">
                    <div style="min-width:0; flex:1;">
                        <div class="card-number-value">${escapeHtml(c.card_number)}</div>
                        <div style="font-size:10.5px; color:var(--text-muted); margin-top:4px;">${c.category_name ? escapeHtml(c.category_name) + ' · ' : ''}${formatDateTime(c.sent_at)}</div>
                        <div style="margin-top:7px;">${statusHtml}</div>
                    </div>
                    <div class="card-actions-col">
                        <button class="copy-btn" onclick="copyText('${escapeHtml(c.card_number)}')" title="نسخ الرقم"><i class="ph-bold ph-copy"></i></button>
                        <button class="card-login-btn" data-card-id="${c.id}" data-code="${escapeHtml(c.card_number)}" onclick="directLogin(this)" ${isExpired ? 'disabled' : ''} title="دخول مباشر للشبكة">
                            <i class="ph-bold ph-sign-in"></i> دخول
                        </button>
                    </div>
                </div>`;
            }).join('');
            startCardCountdownTicker();
        }

        // شراء بطاقة — تُبنى من فئاتك الحقيقية المفعّلة مع المخزون المتاح فعلياً
        const buyBox = document.getElementById('buyCardsBox');
        const cats = s.categories || [];
        if (s.blocked_for_debt) {
            buyBox.innerHTML = '<div class="lock-banner" style="padding:18px 14px;"><i class="ph-duotone ph-lock-key" style="font-size:30px; margin-bottom:6px;"></i><div style="font-weight:800; color:var(--text-dark);">الشراء موقوف مؤقتاً حتى سداد الدين</div><div style="font-size:12px; color:var(--text-muted); margin-top:4px;">تبويب «الدفع» متاح لك لرفع إشعار التسديد</div></div>';
        } else if (!cats.length) {
            buyBox.innerHTML = '<div class="empty-state" style="padding:24px;"><i class="ph-duotone ph-package"></i><div class="empty-state-title">لا فئات متاحة حالياً</div><div class="empty-state-sub">تواصل مع الإدارة لإضافة بطاقات للبيع</div></div>';
        } else {
            buyBox.innerHTML = cats.map(c => {
                const stock = parseInt(c.stock_available) || 0;
                const stockClass = stock === 0 ? 'out' : (stock <= 5 ? 'low' : 'ok');
                const stockText = stock === 0 ? 'نفدت الكمية' : `متاح: ${stock}`;
                return `
                <div class="buy-card-tile">
                    <div class="buy-card-head">
                        <div class="buy-card-icon" style="background:${c.color || '#6C43FF'};"><i class="ph-fill ${c.icon || 'ph-wifi-high'}"></i></div>
                        <div style="flex:1;">
                            <div style="font-weight:800; color:var(--text-dark); font-size:14.5px;">${escapeHtml(c.name)}</div>
                            <div class="buy-card-stock ${stockClass}">${stockText}</div>
                        </div>
                        <div class="buy-card-price">${money(c.default_sell_price)}</div>
                    </div>
                    <div class="buy-card-controls">
                        <div class="qty-stepper">
                            <button type="button" onclick="stepBuyQty(${c.id}, -1, ${stock})"><i class="ph-bold ph-minus"></i></button>
                            <input type="number" id="buyQty-${c.id}" value="1" min="1" max="${Math.max(1, Math.min(10, stock))}" readonly>
                            <button type="button" onclick="stepBuyQty(${c.id}, 1, ${stock})"><i class="ph-bold ph-plus"></i></button>
                        </div>
                        <span class="buy-total-chip" id="buyTotal-${c.id}">${money(c.default_sell_price)}</span>
                        <button class="btn btn-gold btn-sm" style="margin-right:auto;" ${stock === 0 ? 'disabled' : ''} onclick="buyCard(${c.id}, ${parseFloat(c.default_sell_price)}, '${escapeHtml(c.name)}', ${stock})">
                            <i class="ph-bold ph-shopping-cart-simple"></i> شراء
                        </button>
                    </div>
                </div>`;
            }).join('');
        }

        // طرق الدفع
        const payBox = document.getElementById('payMethodsBox');
        payBox.innerHTML = (s.payment_methods || []).map(pm => `
            <div class="pay-method-card">
                <div class="pay-method-head">
                    <div class="pay-method-logo" style="background:${pm.method === 'palpay' ? 'linear-gradient(140deg,#0FA97A,#0A9068)' : 'linear-gradient(140deg,#E5484D,#C22F62)'};">
                        <i class="ph-fill ph-wallet"></i>
                    </div>
                    <div>
                        <div style="font-weight:800; color:var(--text-dark); font-size:14.5px;">${escapeHtml(pm.label)}</div>
                        <div style="font-size:11px; color:var(--text-muted);">${escapeHtml(pm.note)}</div>
                    </div>
                </div>
                <div class="pay-number-row">
                    <div class="pay-number-value">${escapeHtml(pm.number)}</div>
                    <button class="copy-btn" onclick="copyText('${escapeHtml(pm.number)}')"><i class="ph-bold ph-copy"></i></button>
                </div>
            </div>`).join('');

        // إيصالاتي
        const rBox = document.getElementById('myReceiptsBox');
        const rBadge = { pending: '<span class="badge badge-gold">قيد المراجعة</span>', approved: '<span class="badge badge-green">مقبول</span>', rejected: '<span class="badge badge-red">مرفوض</span>' };
        if (!s.receipts || !s.receipts.length) {
            rBox.innerHTML = '<div class="empty-state" style="padding:18px;"><div class="empty-state-sub">لم ترفع أي إيصال بعد</div></div>';
        } else {
            rBox.innerHTML = s.receipts.map(r => `
                <div class="notif-item">
                    <div class="notif-icon" style="background:${r.method === 'palpay' ? 'linear-gradient(140deg,#0FA97A,#0A9068)' : 'linear-gradient(140deg,#E5484D,#C22F62)'};"><i class="ph-fill ph-receipt"></i></div>
                    <div style="flex:1;">
                        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                            <span style="font-weight:800; color:var(--text-dark);">${money(r.amount)}</span>${rBadge[r.status] || ''}
                        </div>
                        <div style="font-size:11px; color:var(--text-muted); margin-top:3px;">${r.method === 'palpay' ? 'PalPay' : 'Jawwal Pay'} · ${formatDateTime(r.created_at)}${r.review_note ? '<br>ملاحظة الإدارة: ' + escapeHtml(r.review_note) : ''}</div>
                    </div>
                </div>`).join('');
        }

        // خيارات الفئات لطلب الشراء
        const catSel = document.getElementById('prqCategory');
        catSel.innerHTML = '<option value="">أي نوع متاح</option>' + (s.categories || []).map(c => `<option value="${c.id}">${escapeHtml(c.name)} — ${money(c.default_sell_price)}</option>`).join('');

        // طلباتي
        const reqBox = document.getElementById('myRequestsBox');
        const reqBadge = { pending: '<span class="badge badge-gold">قيد المعالجة</span>', approved: '<span class="badge badge-purple">مقبول</span>', rejected: '<span class="badge badge-red">مرفوض</span>', done: '<span class="badge badge-green">مكتمل</span>' };
        if (!s.requests || !s.requests.length) {
            reqBox.innerHTML = '<div class="empty-state" style="padding:18px;"><div class="empty-state-sub">لا طلبات سابقة</div></div>';
        } else {
            reqBox.innerHTML = s.requests.map(r => `
                <div class="notif-item">
                    <div class="notif-icon"><i class="ph-fill ph-shopping-cart"></i></div>
                    <div style="flex:1;">
                        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                            <span style="font-weight:800; color:var(--text-dark);">${r.quantity} × ${escapeHtml(r.category_name || 'أي نوع')}</span>${reqBadge[r.status] || ''}
                        </div>
                        <div style="font-size:11px; color:var(--text-muted); margin-top:3px;">${formatDateTime(r.created_at)}${r.note ? ' · ' + escapeHtml(r.note) : ''}</div>
                    </div>
                </div>`).join('');
        }

        // نقطة الدعم: مجموع الرسائل غير المقروءة في تذاكر الزبون
        const tks = s.tickets || [];
        const supUnread = tks.reduce((sum, t) => sum + (parseInt(t.unread_customer) || 0), 0);
        const supDot = document.getElementById('supportDockDot');
        if (supDot) supDot.style.display = supUnread > 0 ? 'block' : 'none';
        if (document.getElementById('ptab-support').classList.contains('active') && !document.getElementById('ptChatView').style.display.includes('block')) {
            renderPortalTickets(tks);
        }

        // الإشعارات
        const unread = (s.notifications || []).filter(n => !parseInt(n.is_read)).length;
        const dot = document.getElementById('notifDot');
        if (unread > 0) { dot.style.display = 'flex'; dot.textContent = unread > 9 ? '9+' : unread; }
        else dot.style.display = 'none';
        document.getElementById('notifListBox').innerHTML = (s.notifications || []).length
            ? s.notifications.map(n => `
                <div class="notif-item ${parseInt(n.is_read) ? '' : 'unread'}">
                    <div class="notif-icon"><i class="ph-fill ph-bell"></i></div>
                    <div style="flex:1;">
                        <div style="font-weight:800; color:var(--text-dark); font-size:13.5px;">${escapeHtml(n.title)}</div>
                        ${n.body ? `<div style="font-size:12px; color:var(--text-body); margin-top:3px; white-space:pre-line;">${escapeHtml(n.body)}</div>` : ''}
                        <div style="font-size:10.5px; color:var(--text-muted); margin-top:4px;">${formatDateTime(n.created_at)}</div>
                    </div>
                </div>`).join('')
            : '<div class="empty-state" style="padding:20px;"><i class="ph-duotone ph-bell-slash"></i><div class="empty-state-sub">لا إشعارات بعد</div></div>';
    }

    function copyText(text) {
        const done = () => showToast('success', 'تم النسخ', text);
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
        } else fallbackCopy(text, done);
    }
    function fallbackCopy(text, done) {
        const ta = document.createElement('textarea');
        ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
        document.body.appendChild(ta); ta.select();
        try { document.execCommand('copy'); done(); } catch (e) { showToast('error', 'تعذر النسخ'); }
        ta.remove();
    }

    /* ════════ الدخول المباشر لشبكة الميكروتك + العد التنازلي ════════ */
    // رابط صفحة تسجيل الدخول لهوت سبوت الميكروتك
    const HOTSPOT_LOGIN_URL = 'http://172.30.20.1/login';

    // استخراج اسم المستخدم وكلمة المرور من رقم البطاقة:
    // إن احتوى الرقم على فاصل واضح (: أو | أو / أو مسافة) نقسمه لاسم/كلمة، وإلا فالرقم نفسه هو الاثنان معاً (بطاقات الفاوتشر)
    function parseCardCreds(code) {
        code = String(code || '').trim();
        let m = code.match(/^(\S+)\s*[:|\/]\s*(\S+)$/);
        if (!m) m = code.match(/^(\S+)\s+(\S+)$/);
        if (m) return { u: m[1], p: m[2] };
        return { u: code, p: code };
    }

    // يبدأ العد التنازلي (بتسجيل لحظة التفعيل على الخادم) ثم يوجّه المستخدم لصفحة دخول الميكروتك مع تعبئة البيانات تلقائياً
    function directLogin(btn) {
        const code = btn.getAttribute('data-code') || '';
        const cardId = btn.getAttribute('data-card-id') || '';
        const creds = parseCardCreds(code);

        // تسجيل لحظة التفعيل على الخادم (يصمد أثناء الانتقال للصفحة الأخرى) — مرة واحدة فقط
        try {
            const fd = new FormData();
            fd.append('action', 'portal_activate_card');
            fd.append('card_id', cardId);
            if (navigator.sendBeacon) {
                navigator.sendBeacon('?action=portal_activate_card', fd);
            } else {
                fetch('?action=portal_activate_card', { method: 'POST', body: fd, credentials: 'same-origin', keepalive: true });
            }
        } catch (e) {}

        // بناء نموذج يُرسل بيانات الدخول مباشرة لصفحة الميكروتك (انتقال أعلى المستوى — لا يمنعه المتصفح)
        const f = document.createElement('form');
        f.method = 'POST';
        f.action = HOTSPOT_LOGIN_URL;
        f.acceptCharset = 'UTF-8';
        f.style.display = 'none';
        const addField = (n, v) => { const i = document.createElement('input'); i.type = 'hidden'; i.name = n; i.value = v; f.appendChild(i); };
        addField('username', creds.u);
        addField('password', creds.p);
        addField('dst', '');
        addField('popup', 'true');
        document.body.appendChild(f);
        showToast('info', 'جاري الاتصال بالشبكة…', 'يتم تسجيل دخولك تلقائياً');
        setTimeout(() => { try { f.submit(); } catch (e) { window.location.href = HOTSPOT_LOGIN_URL; } }, 350);
    }

    // مؤقّت واحد يحدّث كل شارات العد التنازلي كل ثانية
    let _cardTicker = null;
    function startCardCountdownTicker() {
        if (_cardTicker) return; // مؤقّت واحد يكفي لكل الشارات
        const tick = () => {
            const badges = document.querySelectorAll('.card-badge.counting');
            if (!badges.length) { clearInterval(_cardTicker); _cardTicker = null; return; }
            const now = Date.now();
            badges.forEach(b => {
                const exp = Number(b.getAttribute('data-expire')) || 0;
                let diff = Math.floor((exp - now) / 1000);
                const cd = b.querySelector('.card-cd');
                if (diff <= 0) {
                    // انتهت المدة الآن → حوّل الشارة إلى «منتهية» وعطّل زر الدخول لنفس البطاقة
                    b.classList.remove('counting');
                    b.classList.add('expired');
                    b.innerHTML = '<i class="ph-fill ph-x-circle"></i> منتهية';
                    const item = b.closest('.card-number-item');
                    if (item) { const lb = item.querySelector('.card-login-btn'); if (lb) lb.disabled = true; }
                    return;
                }
                const dd = Math.floor(diff / 86400); diff -= dd * 86400;
                const hh = Math.floor(diff / 3600); diff -= hh * 3600;
                const mm = Math.floor(diff / 60); const ss = diff - mm * 60;
                const p2 = n => String(n).padStart(2, '0');
                if (cd) cd.textContent = (dd > 0 ? dd + 'ي ' : '') + p2(hh) + ':' + p2(mm) + ':' + p2(ss);
            });
        };
        tick();
        _cardTicker = setInterval(tick, 1000);
    }

    async function openNotifSheet() {
        openPortalModal('notifSheet');
        if (navigator.onLine && P_STATE) {
            await apiPost('portal_notifications_read');
            (P_STATE.notifications || []).forEach(n => n.is_read = 1);
            try { localStorage.setItem(PORTAL_CACHE_KEY, JSON.stringify(P_STATE)); } catch (e) {}
            document.getElementById('notifDot').style.display = 'none';
            document.querySelectorAll('#notifListBox .notif-item').forEach(el => el.classList.remove('unread'));
        }
    }

    async function portalLogout() {
        await apiPost('portal_logout');
        try { localStorage.removeItem(PORTAL_CACHE_KEY); } catch (e) {}
        window.location.href = '?page=portal';
    }

    /* ═══ رفع إيصال الدفع (مع ضغط الصورة قبل الرفع) ═══ */
    function previewReceiptImage() {
        const file = document.getElementById('rcImage').files[0];
        const img = document.getElementById('rcPreview');
        if (!file) { img.style.display = 'none'; return; }
        img.src = URL.createObjectURL(file);
        img.style.display = 'block';
    }

    function compressImage(file, maxDim = 1200, quality = 0.8) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
                let { width, height } = img;
                if (width > maxDim || height > maxDim) {
                    const scale = maxDim / Math.max(width, height);
                    width = Math.round(width * scale);
                    height = Math.round(height * scale);
                }
                const canvas = document.createElement('canvas');
                canvas.width = width; canvas.height = height;
                canvas.getContext('2d').drawImage(img, 0, 0, width, height);
                resolve(canvas.toDataURL('image/jpeg', quality));
            };
            img.onerror = reject;
            img.src = URL.createObjectURL(file);
        });
    }

    async function submitReceipt() {
        const file = document.getElementById('rcImage').files[0];
        const amount = parseFloat(document.getElementById('rcAmount').value) || 0;
        if (amount <= 0) return showToast('warning', 'تنبيه', 'أدخل المبلغ المحوَّل');
        if (!file) return showToast('warning', 'تنبيه', 'أرفق صورة إشعار التحويل');
        if (!navigator.onLine) return showToast('error', 'لا يوجد اتصال', 'رفع الإيصال يحتاج إنترنت — أعد المحاولة عند عودة الاتصال');

        const btn = document.getElementById('rcSubmitBtn');
        btn.disabled = true;
        btn.innerHTML = '<i class="ph-bold ph-spinner ph-spin"></i> جاري الرفع...';
        try {
            const dataUrl = await compressImage(file);
            const res = await apiPost('portal_upload_receipt', {
                method: document.getElementById('rcMethod').value,
                amount,
                note: document.getElementById('rcNote').value,
                image: dataUrl,
            });
            if (res.success) {
                showToast('success', 'وصل الإيصال 🎉', 'سيراجعه فريقنا ويصلك إشعار بالنتيجة');
                document.getElementById('rcAmount').value = '';
                document.getElementById('rcNote').value = '';
                document.getElementById('rcImage').value = '';
                document.getElementById('rcPreview').style.display = 'none';
                loadPortal();
            } else showToast('error', 'خطأ', res.message || 'تعذر رفع الإيصال');
        } catch (e) {
            showToast('error', 'خطأ', 'تعذرت معالجة الصورة');
        } finally {
            btn.disabled = false;
            btn.innerHTML = '<i class="ph-bold ph-paper-plane-tilt"></i> إرسال الإيصال';
        }
    }

    /* ═══ طلب شراء ═══ */
    async function submitPurchaseRequest() {
        if (!navigator.onLine) return showToast('error', 'لا يوجد اتصال', 'إرسال الطلب يحتاج إنترنت');
        const qty = Math.max(1, parseInt(document.getElementById('prqQty').value) || 1);
        const btn = document.getElementById('prqSubmitBtn');
        btn.disabled = true;
        const res = await apiPost('portal_purchase_request', {
            category_id: document.getElementById('prqCategory').value,
            quantity: qty,
            note: document.getElementById('prqNote').value,
        });
        btn.disabled = false;
        if (res.success) {
            showToast('success', 'وصل طلبك 🎉', 'سيتواصل معك فريقنا قريباً');
            document.getElementById('prqQty').value = 1;
            document.getElementById('prqNote').value = '';
            loadPortal();
        } else showToast('error', 'خطأ', res.message || 'تعذر إرسال الطلب');
    }

    /* ═══ شراء بطاقة بالرصيد ═══ */
    function stepBuyQty(catId, delta, stock) {
        const input = document.getElementById('buyQty-' + catId);
        const max = Math.max(1, Math.min(10, stock));
        let val = (parseInt(input.value) || 1) + delta;
        val = Math.max(1, Math.min(max, val));
        input.value = val;
        const cat = (P_STATE.categories || []).find(c => c.id == catId);
        if (cat) document.getElementById('buyTotal-' + catId).textContent = money(parseFloat(cat.default_sell_price) * val);
    }

    let buyInFlight = false;
    async function buyCard(catId, unitPrice, catName, stock) {
        if (buyInFlight) return;
        if (!navigator.onLine) return showToast('error', 'لا يوجد اتصال', 'الشراء يحتاج إنترنت للتأكد من رصيدك ومخزونك');
        if (stock <= 0) return showToast('error', 'نفدت الكمية', `لا يوجد مخزون متاح حالياً من ${catName}`);

        const qty = parseInt(document.getElementById('buyQty-' + catId).value) || 1;
        const total = unitPrice * qty;
        const balance = parseFloat(P_STATE.balance) || 0;
        if (balance + 0.009 < total) {
            return showToast('error', 'رصيدك غير كافٍ', `تحتاج ${money(total)} ومعك ${money(balance)}. اشحن رصيدك من تبويب الدفع`);
        }

        showPortalConfirm('تأكيد الشراء', `شراء ${qty} × ${catName} بمبلغ ${money(total)}؟ سيُخصم فوراً من رصيدك.`, async () => {
            buyInFlight = true;
            try {
                const res = await apiPost('portal_buy_card', { category_id: catId, quantity: qty });
                if (res.success) {
                    showToast('success', 'تم الشراء بنجاح 🎉', `اذهب لتبويب «بطاقاتي» لنسخ ${res.numbers.length > 1 ? 'الأرقام' : 'الرقم'}`);
                    await loadPortal();
                    switchPortalTab('cards');
                } else {
                    showToast('error', 'تعذر الشراء', res.message || 'حدث خطأ غير متوقع');
                }
            } finally {
                buyInFlight = false;
            }
        }, 'شراء الآن');
    }

    /* ═══ تفعيل إشعارات Push ═══ */
    function urlB64ToUint8Array(base64String) {
        const padding = '='.repeat((4 - base64String.length % 4) % 4);
        const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
        const raw = window.atob(base64);
        const arr = new Uint8Array(raw.length);
        for (let i = 0; i < raw.length; ++i) arr[i] = raw.charCodeAt(i);
        return arr;
    }

    async function enablePushNotifications() {
        if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) {
            return showToast('error', 'غير مدعوم', 'متصفحك لا يدعم الإشعارات — جرّب Chrome على أندرويد');
        }
        if (!P_STATE || !P_STATE.vapid_public) {
            return showToast('warning', 'انتظر لحظة', 'يجب الاتصال بالإنترنت أولاً لتفعيل الإشعارات');
        }
        const perm = await Notification.requestPermission();
        if (perm !== 'granted') return showToast('warning', 'لم يتم التفعيل', 'اسمح بالإشعارات من إعدادات المتصفح');
        try {
            const reg = await navigator.serviceWorker.ready;
            const sub = await reg.pushManager.subscribe({
                userVisibleOnly: true,
                applicationServerKey: urlB64ToUint8Array(P_STATE.vapid_public),
            });
            const json = sub.toJSON();
            const res = await apiPost('portal_subscribe_push', {
                endpoint: sub.endpoint,
                p256dh: json.keys.p256dh,
                auth: json.keys.auth,
            });
            if (res.success) showToast('success', 'تم التفعيل 🔔', 'ستصلك الإشعارات حتى والتطبيق مغلق');
            else showToast('error', 'خطأ', res.message || 'تعذر حفظ الاشتراك');
        } catch (e) {
            showToast('error', 'تعذر التفعيل', 'أعد المحاولة، وتأكد أن الموقع مفتوح عبر HTTPS');
        }
    }

    /* ═══════════ الدعم الفني — محادثات الزبون ═══════════ */
    let portalTickets = [];
    let ptCurrentId = null;
    let ptCurrentStatus = 'open';
    let ptLastMsgId = 0;
    let portalChatTimer = null;

    function showPortalView(which) {
        document.getElementById('ptSupportList').style.display = which === 'list' ? 'block' : 'none';
        document.getElementById('ptNewForm').style.display = which === 'new' ? 'block' : 'none';
        document.getElementById('ptChatView').style.display = which === 'chat' ? 'block' : 'none';
    }

    function backToPortalTickets() {
        showPortalView('list');
        ptCurrentId = null;
        if (portalChatTimer) { clearInterval(portalChatTimer); portalChatTimer = null; }
    }

    function showNewTicketForm() {
        document.getElementById('ptSubject').value = '';
        document.getElementById('ptBody').value = '';
        showPortalView('new');
    }

    async function loadPortalTickets() {
        const res = await apiGet('portal_tickets_list');
        if (res.success) { portalTickets = res.data || []; if (document.getElementById('ptChatView').style.display !== 'block') renderPortalTickets(portalTickets); }
    }

    function renderPortalTickets(list) {
        const box = document.getElementById('ptTicketsBox');
        if (!box) return;
        if (!list.length) {
            box.innerHTML = '<div class="empty-state" style="padding:22px;"><i class="ph-duotone ph-headset"></i><div class="empty-state-sub">لا محادثات بعد — افتح واحدة وسنرد عليك بأسرع وقت</div></div>';
            return;
        }
        box.innerHTML = list.map(t => {
            const unread = parseInt(t.unread_customer) || 0;
            return `<div class="notif-item ${unread ? 'unread' : ''}" style="cursor:pointer;" onclick="openPortalTicket(${t.id})">
                <div class="notif-icon" style="background:${t.status === 'open' ? 'var(--success)' : 'var(--text-muted)'};"><i class="ph-fill ph-chats-circle"></i></div>
                <div style="flex:1; min-width:0;">
                    <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                        <span style="font-weight:800; color:var(--text-dark); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(t.subject || 'محادثة')}</span>
                        ${unread ? `<span class="ticket-unread">${unread}</span>` : `<span class="ticket-status-chip ${t.status}">${t.status === 'open' ? 'مفتوحة' : 'مغلقة'}</span>`}
                    </div>
                    <div style="font-size:11px; color:var(--text-muted); margin-top:3px;">${formatDateTime(t.last_msg_at)}</div>
                </div>
            </div>`;
        }).join('');
    }

    async function openPortalTicket(id) {
        ptCurrentId = id; ptLastMsgId = 0;
        showPortalView('chat');
        document.getElementById('ptChatMessages').innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-muted);">جارٍ التحميل...</div>';
        const res = await apiGet('portal_ticket_messages', { ticket_id: id });
        if (!res.success) { showToast('error', 'خطأ', res.message || 'تعذر فتح المحادثة'); backToPortalTickets(); return; }
        const t = res.ticket;
        ptCurrentStatus = t.status;
        document.getElementById('ptChatTitle').textContent = t.subject || 'محادثة';
        updatePtStatusChip();
        document.getElementById('ptChatMessages').innerHTML = '';
        appendPortalMessages(res.messages || []);
        const tc = portalTickets.find(x => x.id == id);
        if (tc) tc.unread_customer = 0;
        renderPortalTickets(portalTickets);
        refreshSupportDot();
        if (portalChatTimer) clearInterval(portalChatTimer);
        // تحديث المحادثة كل 6 ثوانٍ ما دامت مفتوحة
        portalChatTimer = setInterval(() => {
            if (!ptCurrentId || document.getElementById('ptChatView').style.display !== 'block') { clearInterval(portalChatTimer); portalChatTimer = null; return; }
            pollPortalMessages();
        }, 6000);
    }

    function updatePtStatusChip() {
        const chip = document.getElementById('ptChatStatus');
        chip.className = 'ticket-status-chip ' + (ptCurrentStatus === 'open' ? 'open' : 'closed');
        chip.textContent = ptCurrentStatus === 'open' ? 'مفتوحة' : 'مغلقة';
    }

    function appendPortalMessages(msgs) {
        const box = document.getElementById('ptChatMessages');
        msgs.forEach(m => {
            ptLastMsgId = Math.max(ptLastMsgId, parseInt(m.id) || 0);
            const cls = m.sender === 'customer' ? 'cb-me' : (m.sender === 'system' ? 'cb-system' : 'cb-them');
            const div = document.createElement('div');
            div.className = 'chat-bubble ' + cls;
            const who = m.sender === 'staff' ? 'الدعم · ' : (m.sender === 'system' ? '' : '');
            div.innerHTML = escapeHtml(m.body) + '<span class="cb-meta">' + who + shortTimePortal(m.created_at) + '</span>';
            box.appendChild(div);
        });
        if (msgs.length) box.scrollTop = box.scrollHeight;
    }

    function shortTimePortal(dt) {
        if (!dt) return '';
        const d = new Date(String(dt).replace(' ', 'T'));
        if (isNaN(d)) return '';
        const now = new Date();
        return d.toDateString() === now.toDateString()
            ? d.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })
            : d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'short' });
    }

    async function pollPortalMessages() {
        if (!ptCurrentId) return;
        const res = await apiGet('portal_ticket_messages', { ticket_id: ptCurrentId, after_id: ptLastMsgId });
        if (res.success) {
            if (res.messages && res.messages.length) appendPortalMessages(res.messages);
            if (res.ticket) { ptCurrentStatus = res.ticket.status; updatePtStatusChip(); }
        }
    }

    async function sendPortalMsg() {
        const input = document.getElementById('ptChatInput');
        const body = input.value.trim();
        if (!body || !ptCurrentId) return;
        input.value = '';
        const res = await apiPost('portal_ticket_send', { ticket_id: ptCurrentId, body });
        if (res.success) { ptCurrentStatus = 'open'; updatePtStatusChip(); await pollPortalMessages(); }
        else { input.value = body; showToast('error', 'خطأ', res.message || 'تعذر الإرسال'); }
    }

    async function createPortalTicket() {
        const body = document.getElementById('ptBody').value.trim();
        if (!body) return showToast('warning', 'تنبيه', 'اكتب رسالتك أولاً');
        const btn = document.getElementById('ptCreateBtn'); btn.disabled = true;
        const res = await apiPost('portal_ticket_create', { subject: document.getElementById('ptSubject').value.trim(), body });
        btn.disabled = false;
        if (res.success) {
            showToast('success', 'تم الإرسال ✅', 'وصلتنا رسالتك وسيتم الرد قريباً');
            await loadPortalTickets();
            openPortalTicket(res.ticket_id);
        } else showToast('error', 'خطأ', res.message || 'تعذر الإرسال');
    }

    function refreshSupportDot() {
        const supUnread = portalTickets.reduce((sum, t) => sum + (parseInt(t.unread_customer) || 0), 0);
        const supDot = document.getElementById('supportDockDot');
        if (supDot) supDot.style.display = supUnread > 0 ? 'block' : 'none';
    }

    /* ═══ الأوفلاين والتهيئة ═══ */
    window.addEventListener('online', () => { document.getElementById('offlineChip').classList.remove('show'); loadPortal(); });
    window.addEventListener('offline', () => document.getElementById('offlineChip').classList.add('show'));

    (function initPortal() {
        const standalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
        if (!standalone) document.getElementById('installHint').classList.add('show');
        loadPortal();
    })();
    </script>
    <?php
}

/* ════════════════════════════════════════════════════════════════
 *  السكريبتات (JavaScript) — واجهة الإدارة
 * ════════════════════════════════════════════════════════════════ */
function renderScripts(?array $user, array $perms): void
{
    $permsJson = json_encode($perms, JSON_UNESCAPED_UNICODE);
    $allPermsJson = json_encode(ALL_PERMISSIONS, JSON_UNESCAPED_UNICODE);
    ?>
    <script>
    /* ════════ الحالة العامة ════════ */
    const APP_PERMS = <?php echo $permsJson ?: '{}'; ?>;
    const ALL_PERMS = <?php echo $allPermsJson ?: '{}'; ?>;
    const IS_OWNER = <?php echo (is_array($user) && ($user['role'] ?? '') === 'owner') ? 'true' : 'false'; ?>;
    let CATEGORIES_CACHE = [];
    let CUSTOMERS_CACHE = [];
    let currentDebtsFilter = 'open';
    let currentReportPeriod = 'daily';
    let posPaymentStatus = 'paid';

    function can(perm) { return !!APP_PERMS[perm]; }

    /* ════════ أدوات مساعدة عامة ════════ */
    function apiGet(action, params = {}) {
        const qs = new URLSearchParams({ action, ...params }).toString();
        return fetch('?' + qs, { credentials: 'same-origin' })
            .then(r => r.json())
            .catch(() => ({ success: false, offline: true, message: 'أنت بدون اتصال — تُعرض آخر بيانات محفوظة إن وجدت' }));
    }
    function apiPost(action, data = {}) {
        const fd = new FormData();
        fd.append('action', action);
        for (const k in data) fd.append(k, data[k]);
        return fetch('?action=' + encodeURIComponent(action), { method: 'POST', body: fd, credentials: 'same-origin' })
            .then(r => r.json())
            .catch(() => ({ success: false, offline: true, message: 'أنت بدون اتصال' }));
    }
    function money(n) {
        n = parseFloat(n) || 0;
        const isInt = Math.round(n) === n;
        return n.toLocaleString('en-US', { minimumFractionDigits: isInt ? 0 : 2, maximumFractionDigits: 2 }) + ' ₪';
    }
    function escapeHtml(str) {
        if (str === null || str === undefined) return '';
        return String(str).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
    }
    function formatDate(dateStr) {
        if (!dateStr) return '—';
        const d = new Date(dateStr.replace(' ', 'T'));
        if (isNaN(d)) return dateStr;
        return d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'short', year: 'numeric' });
    }
    function formatDateTime(dateStr) {
        if (!dateStr) return '—';
        const d = new Date(dateStr.replace(' ', 'T'));
        if (isNaN(d)) return dateStr;
        return d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'short' }) + ' — ' + d.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
    }
    function debounce(fn, ms) {
        let t;
        return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
    }
    function initialsOf(name) { return (name || '؟').trim().charAt(0) || '؟'; }

    /* ════════ التوست (Toasts) ════════ */
    function showToast(type, title, msg = '') {
        const root = document.getElementById('toastRoot');
        const icons = { success: 'ph-check-circle', error: 'ph-x-circle', warning: 'ph-warning', info: 'ph-info' };
        const el = document.createElement('div');
        el.className = `toast toast-${type}`;
        el.innerHTML = `
            <div class="toast-icon"><i class="ph-fill ${icons[type] || icons.info}"></i></div>
            <div class="toast-body"><div class="toast-title">${escapeHtml(title)}</div>${msg ? `<div class="toast-msg">${escapeHtml(msg)}</div>` : ''}</div>
            <div class="toast-progress"></div>`;
        el.onclick = () => dismissToast(el);
        root.appendChild(el);
        requestAnimationFrame(() => el.classList.add('show'));
        setTimeout(() => dismissToast(el), 3800);
    }
    function dismissToast(el) {
        if (!el || !el.parentNode) return;
        el.classList.add('hide');
        setTimeout(() => el.remove(), 300);
    }
    function handleApiError(res, fallbackMsg = 'حدث خطأ غير متوقع') {
        showToast('error', 'خطأ', (res && res.message) ? res.message : fallbackMsg);
    }

    /* ════════ المودالات ════════ */
    function openModal(id) { document.getElementById(id).classList.add('show'); }
    function closeModal(id) { document.getElementById(id).classList.remove('show'); }
    document.querySelectorAll('.modal-overlay').forEach(ov => {
        ov.addEventListener('click', e => { if (e.target === ov) ov.classList.remove('show'); });
    });
    document.addEventListener('keydown', e => {
        if (e.key === 'Escape') document.querySelectorAll('.modal-overlay.show').forEach(m => m.classList.remove('show'));
    });

    function showConfirm(title, msg, onConfirm, btnLabel = 'تأكيد') {
        document.getElementById('confirmModalTitle').textContent = title;
        document.getElementById('confirmModalMsg').textContent = msg;
        const btn = document.getElementById('confirmModalActionBtn');
        btn.textContent = btnLabel;
        const newBtn = btn.cloneNode(true);
        btn.parentNode.replaceChild(newBtn, btn);
        newBtn.addEventListener('click', () => { closeModal('confirmModal'); onConfirm(); });
        openModal('confirmModal');
    }

    /* ════════ التنقل بين الصفحات ════════ */
    const PAGE_PERMS = {
        dashboard: null, profile: null,
        pos: 'sales.create', sales: 'sales.view',
        customers: 'customers.view', debts: 'debts.view',
        inventory: 'inventory.view', expenses: 'expenses.view',
        reports: 'reports.view', employees: 'employees.manage', settings: 'settings.manage',
        cardspool: 'inventory.view', receipts: 'debts.manage', requests: 'sales.view',
        cardlog: 'sales.view', cardcheck: 'sales.view', support: 'support.manage', audit: 'owner',
    };

    const pageLoaders = {
        dashboard: loadDashboard,
        pos: loadPosPage,
        sales: loadSales,
        customers: loadCustomers,
        debts: loadDebtsPage,
        inventory: loadInventoryPage,
        cardspool: loadCardsPool,
        cardlog: loadCardLog,
        receipts: loadReceipts,
        requests: loadRequests,
        expenses: loadExpensesPage,
        reports: loadReports,
        employees: loadEmployees,
        settings: loadSettingsPage,
        cardcheck: loadCardCheckPage,
        support: loadSupportPage,
        audit: loadAuditPage,
        profile: () => {},
    };

    function goToPage(page) {
        const requiredPerm = PAGE_PERMS[page];
        const denied = requiredPerm === 'owner' ? !IS_OWNER : (requiredPerm && !can(requiredPerm));
        if (denied) {
            showToast('warning', 'تنبيه', 'ليس لديك صلاحية للوصول لهذه الصفحة');
            page = 'dashboard';
        }
        document.querySelectorAll('.page-view').forEach(p => p.classList.remove('active'));
        const target = document.getElementById('page-' + page);
        if (target) target.classList.add('active');
        document.querySelectorAll('.nav-link[data-page]').forEach(l => l.classList.toggle('active', l.dataset.page === page));
        closeMobileSidebar();
        window.scrollTo({ top: 0, behavior: 'smooth' });
        if (pageLoaders[page]) pageLoaders[page]();
        history.replaceState(null, '', '#' + page);
    }

    function openMobileSidebar() {
        document.getElementById('mainSidebar').classList.add('mobile-open');
        document.getElementById('sidebarOverlay').classList.add('show');
    }
    function closeMobileSidebar() {
        document.getElementById('mainSidebar').classList.remove('mobile-open');
        document.getElementById('sidebarOverlay').classList.remove('show');
    }

    function confirmLogout() {
        showConfirm('تسجيل الخروج', 'هل تريد تسجيل الخروج من النظام؟', async () => {
            await apiPost('logout');
            window.location.href = '?page=login';
        }, 'تسجيل الخروج');
    }

    /* ════════ تحميل الفئات والزبائن (مشتركة بين صفحات) ════════ */
    async function loadCategoriesCache() {
        const res = await apiGet('categories_list');
        if (res.success) CATEGORIES_CACHE = res.data;
        return CATEGORIES_CACHE;
    }
    async function loadCustomersCache() {
        const res = await apiGet('customers_list');
        if (res.success) CUSTOMERS_CACHE = res.data;
        return CUSTOMERS_CACHE;
    }
    function fillCustomerSelect(selectEl, includeEmpty = true) {
        selectEl.innerHTML = (includeEmpty ? '<option value="">— بدون زبون (بيع كاش) —</option>' : '<option value="">— اختر الزبون —</option>')
            + CUSTOMERS_CACHE.map(c => `<option value="${c.id}">${escapeHtml(c.full_name)}${c.phone ? ' — ' + escapeHtml(c.phone) : ''}</option>`).join('');
    }
    function fillCategorySelect(selectEl) {
        selectEl.innerHTML = '<option value="">— اختر الفئة —</option>'
            + CATEGORIES_CACHE.filter(c => c.is_active == 1).map(c => `<option value="${c.id}" data-buy="${c.default_buy_price}" data-sell="${c.default_sell_price}" data-qty="${c.quantity_available}">${escapeHtml(c.name)} (متوفر: ${c.quantity_available})</option>`).join('');
    }

    /* ════════ الإعداد الأولي وتسجيل الدخول ════════ */
    function submitSetup() {
        const fullName = document.getElementById('setupFullName').value.trim();
        const username = document.getElementById('setupUsername').value.trim();
        const password = document.getElementById('setupPassword').value;
        const errBox = document.getElementById('setupError');
        errBox.style.display = 'none';

        if (!fullName || !username || password.length < 4) {
            errBox.textContent = 'يرجى تعبئة جميع الحقول (كلمة المرور 4 أحرف على الأقل)';
            errBox.style.display = 'block';
            return;
        }
        apiPost('setup_owner', { full_name: fullName, username, password }).then(res => {
            if (res.success) {
                window.location.href = '?page=dashboard';
            } else {
                errBox.textContent = res.message || 'حدث خطأ، حاول مرة أخرى';
                errBox.style.display = 'block';
            }
        }).catch(() => {
            errBox.textContent = 'تعذر الاتصال بالخادم';
            errBox.style.display = 'block';
        });
    }

    /* ميزة «تذكّرني»: حفظ بيانات الدخول محلياً على الجهاز واستعادتها تلقائياً */
    const REMEMBER_KEY = 'ansnet_remember_login';
    function saveRememberedLogin(username, password) {
        try {
            const chk = document.getElementById('rememberMe');
            if (chk && chk.checked) {
                localStorage.setItem(REMEMBER_KEY, JSON.stringify({ u: username, p: password }));
            } else {
                localStorage.removeItem(REMEMBER_KEY);
            }
        } catch (e) {}
    }
    function prefillRememberedLogin() {
        try {
            const raw = localStorage.getItem(REMEMBER_KEY);
            if (!raw) return;
            const data = JSON.parse(raw);
            const u = document.getElementById('loginUsername');
            const p = document.getElementById('loginPassword');
            const chk = document.getElementById('rememberMe');
            if (u && data.u) u.value = data.u;
            if (p && data.p) p.value = data.p;
            if (chk) chk.checked = true;
        } catch (e) {}
    }

    function submitLogin() {
        const username = document.getElementById('loginUsername').value.trim();
        const password = document.getElementById('loginPassword').value;
        const errBox = document.getElementById('loginError');
        errBox.style.display = 'none';

        if (!username || !password) {
            errBox.textContent = 'يرجى إدخال اسم المستخدم وكلمة المرور';
            errBox.style.display = 'block';
            return;
        }
        // حفظ/مسح بيانات الدخول حسب اختيار «تذكّرني»
        saveRememberedLogin(username, password);
        apiPost('login', { username, password }).then(res => {
            if (res.success) {
                // موظف → لوحة الإدارة، زبون → البوابة
                window.location.href = res.kind === 'customer' ? '?page=portal' : '?page=dashboard';
            } else {
                errBox.textContent = res.message || 'اسم المستخدم أو كلمة المرور غير صحيحة';
                errBox.style.display = 'block';
            }
        }).catch(() => {
            errBox.textContent = 'تعذر الاتصال بالخادم';
            errBox.style.display = 'block';
        });
    }

    /* تبديل تبويبي الدخول/التسجيل في الشاشة الموحّدة */
    function switchAuthTab(tab) {
        document.querySelectorAll('#authTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
        const lf = document.getElementById('loginForm'), rf = document.getElementById('registerForm');
        if (lf) lf.style.display = tab === 'login' ? 'block' : 'none';
        if (rf) rf.style.display = tab === 'register' ? 'block' : 'none';
        const errBox = document.getElementById('loginError');
        if (errBox) errBox.style.display = 'none';
    }

    function submitRegister() {
        const errBox = document.getElementById('loginError');
        errBox.style.display = 'none';
        apiPost('portal_register', {
            full_name: document.getElementById('regFullName').value.trim(),
            username: document.getElementById('regUsername').value.trim(),
            phone: document.getElementById('regPhone').value.trim(),
            password: document.getElementById('regPassword').value,
            password_confirm: document.getElementById('regPasswordConfirm').value,
        }).then(res => {
            if (res.success) window.location.href = '?page=portal';
            else { errBox.textContent = res.message || 'تعذر إنشاء الحساب'; errBox.style.display = 'block'; }
        }).catch(() => { errBox.textContent = 'تعذر الاتصال بالخادم'; errBox.style.display = 'block'; });
    }

    // السماح بالإرسال بالضغط على Enter
    ['setupForm', 'loginForm', 'registerForm'].forEach(formId => {
        const form = document.getElementById(formId);
        if (form) form.addEventListener('submit', e => {
            e.preventDefault();
            if (formId === 'setupForm') submitSetup();
            else if (formId === 'registerForm') submitRegister();
            else submitLogin();
        });
    });
    // استعادة بيانات الدخول المحفوظة (تذكّرني) عند فتح شاشة تسجيل الدخول
    if (document.getElementById('loginForm')) prefillRememberedLogin();

    /* ════════ الرئيسية (Dashboard) ════════ */
