            <div class="stat-card">
                <div class="stat-card-top"><div class="stat-icon-wrap purple"><i class="ph-duotone ph-coins"></i></div>${res.today.count > 0 ? `<span class="stat-trend up"><i class="ph-bold ph-arrow-up-right"></i> ${res.today.count}</span>` : ''}</div>
                <div class="stat-value">${money(res.today.sales)}</div>
                <div class="stat-label">مبيعات اليوم</div>
            </div>
            <div class="stat-card">
                <div class="stat-card-top"><div class="stat-icon-wrap gold"><i class="ph-duotone ph-trend-up"></i></div></div>
                <div class="stat-value">${money(res.today.profit)}</div>
                <div class="stat-label">أرباح اليوم</div>
            </div>
            <div class="stat-card">
                <div class="stat-card-top"><div class="stat-icon-wrap red"><i class="ph-duotone ph-hand-coins"></i></div></div>
                <div class="stat-value">${money(res.total_debt)}</div>
                <div class="stat-label">إجمالي الديون</div>
            </div>
            <div class="stat-card">
                <div class="stat-card-top"><div class="stat-icon-wrap green"><i class="ph-duotone ph-package"></i></div>${res.low_stock_count > 0 ? `<span class="stat-trend down"><i class="ph-bold ph-warning"></i> ${res.low_stock_count}</span>` : ''}</div>
                <div class="stat-value">${res.total_stock}</div>
                <div class="stat-label">كروت متوفرة بالمخزون</div>
            </div>`;

        // ملخص الشهر
        const monthBox = document.getElementById('monthSummaryBox');
        const netMonth = res.month.profit - res.month.expenses;
        monthBox.innerHTML = `
            <div style="display:flex; flex-direction:column; gap:14px;">
                <div style="display:flex; justify-content:space-between; align-items:center;"><span style="font-size:13px; color:var(--text-muted);">إجمالي المبيعات</span><strong style="font-family:var(--font-display); font-size:17px;">${money(res.month.sales)}</strong></div>
                <div style="display:flex; justify-content:space-between; align-items:center;"><span style="font-size:13px; color:var(--text-muted);">عدد العمليات</span><strong>${res.month.count}</strong></div>
                <div style="display:flex; justify-content:space-between; align-items:center;"><span style="font-size:13px; color:var(--text-muted);">المصاريف</span><strong style="color:var(--danger);">${money(res.month.expenses)}</strong></div>
                <div style="height:1px; background:var(--border-light);"></div>
                <div style="display:flex; justify-content:space-between; align-items:center;"><span style="font-size:13px; font-weight:700;">صافي الربح</span><strong style="color:var(--success); font-family:var(--font-display); font-size:19px;">${money(netMonth)}</strong></div>
