    function paymentStatusBadge(status) {
        const map = {
            paid: '<span class="badge badge-green"><i class="ph-fill ph-check-circle"></i> مدفوعة</span>',
            partial: '<span class="badge badge-gold"><i class="ph-fill ph-clock"></i> دفع جزئي</span>',
            debt: '<span class="badge badge-red"><i class="ph-fill ph-hand-coins"></i> دين</span>',
        };
        return map[status] || `<span class="badge badge-gray">${escapeHtml(status)}</span>`;
    }

    function renderSimpleBarChart(containerId, data) {
        const container = document.getElementById(containerId);
        // بناء آخر 7 أيام كاملة حتى لو ما فيها مبيعات
        const byDate = {};
        (data || []).forEach(d => { byDate[d.d] = d; });
        const days = [];
        for (let i = 6; i >= 0; i--) {
            const dt = new Date(); dt.setDate(dt.getDate() - i);
            const key = dt.getFullYear() + '-' + String(dt.getMonth()+1).padStart(2,'0') + '-' + String(dt.getDate()).padStart(2,'0');
            days.push(byDate[key] || { d: key, s: 0, p: 0 });
        }
        const hasAny = days.some(d => parseFloat(d.s) > 0);
        if (!hasAny) {
            container.innerHTML = '<div class="empty-state" style="padding:20px;"><i class="ph-duotone ph-chart-bar"></i><div class="empty-state-sub">لا توجد مبيعات في آخر 7 أيام بعد</div></div>';
            return;
        }
        const max = Math.max(...days.map(d => parseFloat(d.s)), 1);
        container.innerHTML = `<div style="display:flex; align-items:flex-end; gap:10px; height:180px; padding:0 4px;">
            ${days.map(d => {
                const h = Math.max(4, (parseFloat(d.s) / max) * 100);
                const dateObj = new Date(d.d + 'T12:00:00');
                const label = dateObj.toLocaleDateString('ar-EG', { weekday: 'short' });
                return `<div style="flex:1; display:flex; flex-direction:column; align-items:center; gap:8px; height:100%; justify-content:flex-end;">
                    <div style="font-size:10.5px; font-weight:700; color:var(--text-dark);" title="${money(d.s)}">${parseFloat(d.s) > 0 ? money(d.s).replace(' ₪','') : ''}</div>
                    <div style="width:100%; max-width:34px; height:${h}%; min-height:4px; border-radius:10px 10px 4px 4px; background:linear-gradient(180deg, #A66BF2, #6C43FF); box-shadow:0 6px 14px -6px rgba(108,67,255,0.5); transition:height 0.6s cubic-bezier(0.22,1,0.36,1); ${parseFloat(d.s) === 0 ? 'opacity:0.25;' : ''}"></div>
                    <div style="font-size:11px; color:var(--text-muted); font-weight:600;">${label}</div>
                </div>`;
            }).join('')}
        </div>`;
    }

    /* ════════ بيع بطاقة جديدة (POS) ════════ */
    async function loadPosPage() {
        await Promise.all([loadCategoriesCache(), loadCustomersCache()]);
        fillCategorySelect(document.getElementById('posCategory'));
        fillCustomerSelect(document.getElementById('posCustomer'));
        document.getElementById('posQuantity').value = 1;
        document.getElementById('posBuyPrice').value = 0;
        document.getElementById('posSellPrice').value = 0;
        document.getElementById('posAmountPaid').value = 0;
        document.getElementById('posNotes').value = '';
        document.getElementById('posDueDate').value = '';
        document.getElementById('posDueDateFull').value = '';
        document.getElementById('posStockHint').textContent = '';
        setPosPaymentStatus('paid');
        recalcPosTotals();
    }

    function onPosCategoryChange() {
        const sel = document.getElementById('posCategory');
        const opt = sel.selectedOptions[0];
        if (!opt || !opt.value) { document.getElementById('posStockHint').textContent = ''; return; }
        document.getElementById('posBuyPrice').value = opt.dataset.buy || 0;
        document.getElementById('posSellPrice').value = opt.dataset.sell || 0;
        const qty = parseInt(opt.dataset.qty || 0);
        const hint = document.getElementById('posStockHint');
        if (qty <= 0) {
            hint.innerHTML = '<span style="color:var(--danger); font-weight:700;"><i class="ph-fill ph-warning"></i> نفدت الكمية من هذه الفئة!</span>';
        } else {
            hint.innerHTML = `<span style="color:var(--text-muted);">الكمية المتوفرة حالياً: <strong style="color:var(--text-dark);">${qty}</strong></span>`;
        }
        recalcPosTotals();
    }

    function setPosPaymentStatus(status) {
        posPaymentStatus = status;
        document.querySelectorAll('#posPaymentTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.status === status));
        document.getElementById('posPartialRow').style.display = status === 'partial' ? 'grid' : 'none';
        document.getElementById('posDebtDueRow').style.display = status === 'debt' ? 'block' : 'none';
        recalcPosTotals();
    }

    function recalcPosTotals() {
        const qty = Math.max(1, parseInt(document.getElementById('posQuantity').value) || 1);
        const buy = parseFloat(document.getElementById('posBuyPrice').value) || 0;
        const sell = parseFloat(document.getElementById('posSellPrice').value) || 0;
        const totalCost = buy * qty;
        const totalSell = sell * qty;
        const profit = totalSell - totalCost;

        document.getElementById('posTotalCost').textContent = money(totalCost);
        document.getElementById('posTotalSell').textContent = money(totalSell);
        const profitEl = document.getElementById('posProfit');
        profitEl.textContent = money(profit);
        profitEl.style.color = profit >= 0 ? 'var(--success)' : 'var(--danger)';

        const remainingRow = document.getElementById('posRemainingRow');
        if (posPaymentStatus === 'debt') {
            remainingRow.hidden = false;
            document.getElementById('posRemaining').textContent = money(totalSell);
        } else if (posPaymentStatus === 'partial') {
            const paid = parseFloat(document.getElementById('posAmountPaid').value) || 0;
            remainingRow.hidden = false;
            document.getElementById('posRemaining').textContent = money(Math.max(0, totalSell - paid));
        } else {
            remainingRow.hidden = true;
        }
    }

    async function submitSale() {
        const categoryId = document.getElementById('posCategory').value;
        const customerId = document.getElementById('posCustomer').value;
        const qty = Math.max(1, parseInt(document.getElementById('posQuantity').value) || 1);
        const sellPrice = parseFloat(document.getElementById('posSellPrice').value) || 0;

        if (!categoryId) return showToast('warning', 'تنبيه', 'يرجى اختيار فئة البطاقة');
        if (sellPrice <= 0) return showToast('warning', 'تنبيه', 'يرجى إدخال سعر بيع صحيح');
        if (!customerId && posPaymentStatus !== 'paid') return showToast('warning', 'تنبيه', 'لا يمكن تسجيل دين بدون اختيار زبون');

        const btn = document.getElementById('posSubmitBtn');
        btn.disabled = true;
        btn.innerHTML = '<i class="ph-bold ph-spinner ph-spin"></i> جاري التنفيذ...';

        const dueDate = posPaymentStatus === 'debt'
            ? document.getElementById('posDueDateFull').value
            : (posPaymentStatus === 'partial' ? document.getElementById('posDueDate').value : '');

        const payload = {
            category_id: categoryId,
            customer_id: customerId,
            quantity: qty,
            buy_price: document.getElementById('posBuyPrice').value || 0,
            sell_price: sellPrice,
            payment_status: posPaymentStatus,
            amount_paid: posPaymentStatus === 'partial' ? (document.getElementById('posAmountPaid').value || 0) : 0,
            due_date: dueDate,
            notes: document.getElementById('posNotes').value,
        };

        try {
            const res = await apiPost('sale_create', payload);
            if (res.success) {
                showToast('success', 'تمّت العملية بنجاح', `رقم الفاتورة: ${res.invoice_no}`);
                await loadPosPage();
                showInvoicePreview(res.sale_id);
            } else if (res.offline) {
                // بدون اتصال: نحفظ العملية محلياً وترسل تلقائياً عند عودة النت
                const catOpt = document.getElementById('posCategory').selectedOptions[0];
                const custOpt = document.getElementById('posCustomer').selectedOptions[0];
                queueOfflineSale(payload, {
                    category_name: catOpt ? catOpt.textContent : '—',
                    customer_name: (custOpt && custOpt.value) ? custOpt.textContent : 'بيع كاش',
                    total_sell: (parseFloat(payload.sell_price) || 0) * qty,
                    created_at: new Date().toISOString(),
                });
                showToast('warning', 'حُفظت محلياً 📥', 'أنت بدون اتصال — سترسل العملية تلقائياً فور عودة النت');
                await loadPosPage();
            } else {
                handleApiError(res, 'تعذر إتمام عملية البيع');
            }
        } catch (e) {
            showToast('error', 'خطأ', 'تعذر الاتصال بالخادم');
        } finally {
            btn.disabled = false;
            btn.innerHTML = '<i class="ph-bold ph-check-circle"></i> تأكيد عملية البيع';
        }
    }

    async function showInvoicePreview(saleId) {
        const res = await apiGet('sale_detail', { id: saleId });
        if (!res.success) return;
        const s = res.data;
        document.getElementById('invoicePrintArea').innerHTML = buildInvoiceHtml(s);
        openModal('invoiceModal');
    }

    function buildInvoiceHtml(s) {
        return `
        <div id="invoiceContent" style="background:#fff; border-radius:16px; padding:20px; border:1px solid var(--border-light);">
            <div style="text-align:center; margin-bottom:16px;">
                <div style="font-family:var(--font-display); font-weight:900; font-size:20px; color:var(--text-dark);">فاتورة بيع</div>
                <div style="font-size:12px; color:var(--text-muted);">${escapeHtml(s.invoice_no)}</div>
            </div>
            <div style="display:flex; flex-direction:column; gap:8px; font-size:13px; border-top:1px dashed var(--border-light); border-bottom:1px dashed var(--border-light); padding:14px 0; margin-bottom:14px;">
                <div style="display:flex; justify-content:space-between;"><span style="color:var(--text-muted);">الزبون</span><strong>${escapeHtml(s.customer_name || 'بيع كاش')}</strong></div>
                <div style="display:flex; justify-content:space-between;"><span style="color:var(--text-muted);">الفئة</span><strong>${escapeHtml(s.category_name || '—')}</strong></div>
                <div style="display:flex; justify-content:space-between;"><span style="color:var(--text-muted);">الكمية</span><strong>${s.quantity}</strong></div>
                <div style="display:flex; justify-content:space-between;"><span style="color:var(--text-muted);">التاريخ</span><strong>${formatDateTime(s.sold_at)}</strong></div>
                <div style="display:flex; justify-content:space-between;"><span style="color:var(--text-muted);">البائع</span><strong>${escapeHtml(s.seller_name || '—')}</strong></div>
            </div>
            <div style="display:flex; justify-content:space-between; font-size:15px; margin-bottom:6px;"><span>الإجمالي</span><strong>${money(s.total_sell)}</strong></div>
            <div style="display:flex; justify-content:space-between; font-size:13px; margin-bottom:6px;"><span style="color:var(--text-muted);">الحالة</span>${paymentStatusBadge(s.payment_status)}</div>
            ${s.payment_status !== 'paid' ? `<div style="display:flex; justify-content:space-between; font-size:13px; color:var(--danger);"><span>المتبقي</span><strong>${money(s.total_sell - s.amount_paid)}</strong></div>` : ''}
            <div style="text-align:center; margin-top:16px; font-size:11px; color:var(--text-muted);">شكراً لتعاملكم معنا 💜</div>
        </div>`;
    }

    function printInvoice() {
        const content = document.getElementById('invoiceContent').outerHTML;
        const win = window.open('', '_blank', 'width=400,height=600');
        win.document.write(`<html dir="rtl" lang="ar"><head><meta charset="UTF-8"><title>فاتورة</title>
            <style>
                :root { --text-dark:#17102E; --text-muted:#8C84AB; --border-light:rgba(122,100,190,0.25); --danger:#E5484D; --font-display:'Segoe UI',Tahoma,sans-serif; }
                body{font-family:'Segoe UI',Tahoma,Arial,sans-serif; padding:20px; color:#17102E;}
                .badge{display:inline-flex;align-items:center;gap:4px;padding:4px 11px;border-radius:30px;font-size:11px;font-weight:700;}
                .badge-green{background:#DDF6ED;color:#067A5B;}
                .badge-gold{background:#FBF0D7;color:#8A5C00;}
                .badge-red{background:#FDE9EA;color:#B42318;}
                .badge-gray{background:#EEECF5;color:#8C84AB;}
                i{display:none;}
                @media print { body{padding:0;} }
            </style>
        </head><body>${content}<script>window.onload=function(){window.print();}<\/script></body></html>`);
        win.document.close();
    }

    /* ════════ سجل المبيعات ════════ */
    const debouncedLoadSales = debounce(loadSales, 400);

    async function loadSales() {
        if (!can('sales.view')) return;
        if (!CATEGORIES_CACHE.length) await loadCategoriesCache();
        const catFilterSel = document.getElementById('salesCategoryFilter');
        if (catFilterSel.options.length <= 1) {
            catFilterSel.innerHTML = '<option value="">كل الفئات</option>' + CATEGORIES_CACHE.map(c => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');
        }

        const params = {
            search: document.getElementById('salesSearch').value,
            category_id: document.getElementById('salesCategoryFilter').value,
            status: document.getElementById('salesStatusFilter').value,
            from: document.getElementById('salesFromDate').value,
            to: document.getElementById('salesToDate').value,
        };
        const res = await apiGet('sales_list', params);
        const tbody = document.querySelector('#salesTable tbody');
        if (!res.success) { handleApiError(res); return; }
        if (!res.data.length) {
            tbody.innerHTML = `<tr><td colspan="10"><div class="empty-state"><i class="ph-duotone ph-receipt"></i><div class="empty-state-title">لا توجد نتائج</div><div class="empty-state-sub">جرّب تغيير الفلاتر أو ابدأ ببيع بطاقة جديدة</div></div></td></tr>`;
            return;
        }
        tbody.innerHTML = res.data.map(s => `
            <tr>
                <td class="cell-strong">${escapeHtml(s.invoice_no)}</td>
                <td>${escapeHtml(s.customer_name || 'بيع كاش')}</td>
                <td><span class="badge-dot" style="color:${escapeHtml(s.category_color || '#6C43FF')};"></span> ${escapeHtml(s.category_name || '—')}</td>
                <td>${s.quantity}</td>
                <td class="cell-strong">${money(s.total_sell)}</td>
                <td style="color:var(--success); font-weight:700;">${money(s.profit)}</td>
                <td>${paymentStatusBadge(s.payment_status)}</td>
                <td style="font-size:12px; color:var(--text-muted);">${escapeHtml(s.seller_name || '—')}</td>
                <td style="font-size:12px; color:var(--text-muted); white-space:nowrap;">${formatDateTime(s.sold_at)}</td>
                <td>
                    <div class="cell-actions">
                        <button class="btn-icon btn-ghost" style="width:32px;height:32px;" onclick="showInvoicePreview(${s.id})" title="عرض الفاتورة"><i class="ph-bold ph-receipt"></i></button>
                        ${can('sales.delete') ? `<button class="btn-icon btn-ghost" style="width:32px;height:32px; color:var(--danger);" onclick="deleteSale(${s.id}, '${escapeHtml(s.invoice_no)}')" title="حذف"><i class="ph-bold ph-trash"></i></button>` : ''}
                    </div>
                </td>
            </tr>`).join('');
    }

    function deleteSale(id, invoiceNo) {
        showConfirm('حذف عملية بيع', `سيتم حذف الفاتورة ${invoiceNo} وإرجاع الكمية للمخزون. هل أنت متأكد؟`, async () => {
            const res = await apiPost('sale_delete', { id });
            if (res.success) { showToast('success', 'تم الحذف', 'تم حذف العملية وإرجاع الكمية للمخزون'); loadSales(); }
            else handleApiError(res);
        }, 'حذف نهائياً');
    }

    /* ════════ الزبائن ════════ */
    const debouncedLoadCustomers = debounce(loadCustomers, 400);

    async function loadCustomers() {
        if (!can('customers.view')) return;
        const search = document.getElementById('customersSearch').value;
        const res = await apiGet('customers_list', { search });
        const grid = document.getElementById('customersGrid');
        if (!res.success) { handleApiError(res); return; }
        CUSTOMERS_CACHE = res.data;
        if (!res.data.length) {
            grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><i class="ph-duotone ph-users-three"></i><div class="empty-state-title">لا يوجد زبائن بعد</div><div class="empty-state-sub">أضف أول زبون للبدء بتسجيل عملياته</div></div>`;
            return;
        }
        grid.innerHTML = res.data.map(c => `
            <div class="card" style="cursor:pointer; margin-bottom:0;" onclick="openCustomerDetail(${c.id})">
                <div style="display:flex; align-items:center; gap:12px; margin-bottom:14px;">
                    <div class="user-avatar" style="width:44px;height:44px;font-size:17px;background:${c.is_blocked ? '#A79FC7' : '#6C43FF'};">${escapeHtml(initialsOf(c.full_name))}</div>
                    <div style="min-width:0; flex:1;">
                        <div style="font-weight:800; font-size:14.5px; color:var(--text-dark); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(c.full_name)}</div>
                        <div style="font-size:12px; color:var(--text-muted); direction:ltr; text-align:right;">${escapeHtml(c.phone || 'بدون رقم')}</div>
                    </div>
                    ${c.is_blocked == 1 ? '<span class="badge badge-red">محظور</span>' : (c.username ? '<span class="badge badge-purple" title="مسجّل في البوابة"><i class="ph-fill ph-device-mobile"></i></span>' : '')}
                    ${c.portal_block_debt == 1 ? '<span class="badge badge-gold" title="بوابته محجوبة حتى السداد"><i class="ph-fill ph-lock-key"></i></span>' : ''}
                    ${c.portal_show_debt == 1 && c.username ? '<span class="badge badge-green" title="الدين ظاهر له في البوابة"><i class="ph-fill ph-eye"></i></span>' : ''}
                </div>
                <div style="display:flex; justify-content:space-between; font-size:12.5px; padding-top:12px; border-top:1px solid var(--border-soft);">
                    <span style="color:var(--text-muted);"><i class="ph-duotone ph-receipt"></i> ${c.total_orders} عملية</span>
                    <span style="font-weight:700; color:${parseFloat(c.total_debt) > 0 ? 'var(--danger)' : 'var(--success)'};">${parseFloat(c.total_debt) > 0 ? money(c.total_debt) + ' دين' : 'لا يوجد دين'}</span>
                </div>
                <div style="display:flex; justify-content:space-between; font-size:12.5px; padding-top:8px; margin-top:8px; border-top:1px dashed var(--border-soft);">
                    <span style="color:var(--text-muted);"><i class="ph-duotone ph-wallet"></i> الرصيد</span>
                    <span style="font-weight:800; color:var(--primary);">${money(c.balance || 0)}</span>
                </div>
            </div>`).join('');
    }

    function openCustomerModal(customerId = null) {
        document.getElementById('customerId').value = customerId || '';
        document.getElementById('customerModalTitle').textContent = customerId ? 'تعديل بيانات الزبون' : 'إضافة زبون جديد';
        if (customerId) {
            const c = CUSTOMERS_CACHE.find(x => x.id == customerId);
            if (c) {
                document.getElementById('customerFullName').value = c.full_name || '';
                document.getElementById('customerPhone').value = c.phone || '';
                document.getElementById('customerAddress').value = c.address || '';
                document.getElementById('customerNotes').value = c.notes || '';
                document.getElementById('customerPortalUsername').value = c.username || '';
                document.getElementById('customerPortalPassword').value = '';
            }
        } else {
            document.getElementById('customerFullName').value = '';
            document.getElementById('customerPhone').value = '';
            document.getElementById('customerAddress').value = '';
            document.getElementById('customerNotes').value = '';
            document.getElementById('customerPortalUsername').value = '';
            document.getElementById('customerPortalPassword').value = '';
        }
        openModal('customerModal');
    }

    async function saveCustomer() {
        const id = document.getElementById('customerId').value;
        const fullName = document.getElementById('customerFullName').value.trim();
        if (!fullName) return showToast('warning', 'تنبيه', 'اسم الزبون مطلوب');

        const payload = {
            id: id || 0,
            full_name: fullName,
            phone: document.getElementById('customerPhone').value.trim(),
            address: document.getElementById('customerAddress').value.trim(),
            notes: document.getElementById('customerNotes').value.trim(),
            portal_username: document.getElementById('customerPortalUsername').value.trim(),
            portal_password: document.getElementById('customerPortalPassword').value,
        };
        const res = await apiPost(id ? 'customer_update' : 'customer_create', payload);
        if (res.success) {
            showToast('success', id ? 'تم التعديل' : 'تمت الإضافة', fullName);
            closeModal('customerModal');
            await loadCustomersCache();
            loadCustomers();
        } else handleApiError(res);
    }

    async function openCustomerDetail(customerId) {
        openModal('customerDetailModal');
        document.getElementById('customerDetailName').textContent = '...';
        document.getElementById('customerDetailBody').innerHTML = '<div style="text-align:center; padding:30px; color:var(--text-muted);">جاري التحميل...</div>';

        const res = await apiGet('customer_detail', { id: customerId });
        if (!res.success) { document.getElementById('customerDetailBody').innerHTML = '<div class="empty-state"><i class="ph-duotone ph-warning"></i><div class="empty-state-title">تعذر تحميل البيانات</div></div>'; return; }

        const c = res.customer;
        document.getElementById('customerDetailName').textContent = c.full_name;

        const totalDebt = res.debts.filter(d => d.status !== 'paid').reduce((s, d) => s + parseFloat(d.remaining_amount), 0);

        const balance = parseFloat(c.balance) || 0;
        const cards = res.cards || [];

        document.getElementById('customerDetailBody').innerHTML = `
            <div style="display:flex; gap:10px; margin-bottom:18px; flex-wrap:wrap;">
                <button class="btn btn-sm btn-outline" onclick="closeModal('customerDetailModal'); openCustomerModal(${c.id});"><i class="ph-bold ph-pencil-simple"></i> تعديل</button>
                <button class="btn btn-sm ${c.is_blocked == 1 ? 'btn-success' : 'btn-outline danger'}" onclick="toggleCustomerBlock(${c.id}, ${c.is_blocked})"><i class="ph-bold ph-prohibit"></i> ${c.is_blocked == 1 ? 'إلغاء الحظر' : 'حظر الزبون'}</button>
                ${c.phone ? `<a class="btn btn-sm btn-outline" href="https://wa.me/${c.phone.replace(/[^0-9]/g,'')}" target="_blank"><i class="ph-bold ph-whatsapp-logo"></i> واتساب</a>` : ''}
                ${can('customers.manage') ? `<button class="btn btn-sm btn-gold" onclick="openRechargeBalanceModal(${c.id}, '${escapeHtml(c.full_name)}', ${balance})"><i class="ph-bold ph-wallet"></i> شحن رصيد</button>` : ''}
                ${can('customers.manage') ? `<button class="btn btn-sm btn-outline danger" onclick="openDeductBalanceModal(${c.id}, '${escapeHtml(c.full_name)}', ${balance})"><i class="ph-bold ph-minus-circle"></i> خصم رصيد</button>` : ''}
                ${c.username && can('customers.manage') ? `<button class="btn btn-sm btn-outline" onclick="closeModal('customerDetailModal'); openNotifyCustomerModal(${c.id}, '${escapeHtml(c.full_name)}');"><i class="ph-bold ph-bell-ringing"></i> إرسال إشعار</button>` : ''}
                ${c.username && can('customers.manage') ? `<button class="btn btn-sm ${c.portal_block_debt == 1 ? 'btn-success' : 'btn-outline danger'}" onclick="togglePortalBlock(${c.id})"><i class="ph-bold ph-lock-key"></i> ${c.portal_block_debt == 1 ? 'إلغاء حجب البوابة' : 'حجب حتى السداد'}</button>` : ''}
                ${c.username && can('customers.manage') ? `<button class="btn btn-sm btn-outline" onclick="toggleDebtVisibility(${c.id})"><i class="ph-bold ${c.portal_show_debt == 1 ? 'ph-eye-slash' : 'ph-eye'}"></i> ${c.portal_show_debt == 1 ? 'إخفاء الدين من البوابة' : 'عرض الدين في البوابة'}</button>` : ''}
                ${c.username && can('sales.create') ? `<button class="btn btn-sm btn-outline" onclick="closeModal('customerDetailModal'); openCardSendModal(); setTimeout(() => { document.getElementById('csCustomer').value = '${c.id}'; }, 100);"><i class="ph-bold ph-cards"></i> إرسال بطاقة</button>` : ''}
                ${res.sales.length === 0 && can('customers.manage') ? `<button class="btn btn-sm btn-outline danger" onclick="deleteCustomer(${c.id}, '${escapeHtml(c.full_name)}')"><i class="ph-bold ph-trash"></i> حذف</button>` : ''}
            </div>
            ${c.username ? `<div style="font-size:12px; margin-bottom:14px;"><span class="badge badge-purple"><i class="ph-fill ph-device-mobile"></i> مسجّل في البوابة @${escapeHtml(c.username)}</span> ${c.portal_block_debt == 1 ? '<span class="badge badge-red"><i class="ph-fill ph-lock-key"></i> محجوب حتى السداد</span>' : ''} ${c.portal_show_debt == 1 ? '<span class="badge badge-gold"><i class="ph-fill ph-eye"></i> الدين ظاهر له في البوابة</span>' : ''}</div>` : ''}
            <div class="stats-grid" style="grid-template-columns:repeat(4,1fr); margin-bottom:18px;">
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:18px; color:var(--primary);">${money(balance)}</div><div class="stat-label">الرصيد الحالي</div></div>
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:18px;">${res.sales.length}</div><div class="stat-label">عملية بيع</div></div>
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:18px; color:${totalDebt>0?'var(--danger)':'var(--success)'};">${money(totalDebt)}</div><div class="stat-label">دين مستحق</div></div>
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:14px;">${escapeHtml(c.phone || '—')}</div><div class="stat-label">رقم الجوال</div></div>
            </div>
            ${c.address ? `<div style="font-size:13px; margin-bottom:10px;"><i class="ph-duotone ph-map-pin" style="color:var(--primary);"></i> ${escapeHtml(c.address)}</div>` : ''}
            ${c.notes ? `<div style="font-size:13px; margin-bottom:16px; background:rgba(108,67,255,0.06); padding:10px 14px; border-radius:12px;"><i class="ph-duotone ph-note" style="color:var(--primary);"></i> ${escapeHtml(c.notes)}</div>` : ''}
            ${cards.length ? `
            <div class="card-title" style="margin-bottom:10px;"><i class="ph-duotone ph-cards"></i> بطاقات الزبون <span style="font-size:12px; color:var(--text-muted); font-weight:600;">(${cards.length})</span></div>
            <div class="table-wrap" style="margin-bottom:16px;">
                <table class="data-table">
                    <thead><tr><th>رقم البطاقة</th><th>الفئة</th><th>الطريقة</th><th>السعر</th><th>التاريخ والوقت</th>${can('inventory.manage') ? '<th></th>' : ''}</tr></thead>
                    <tbody>${cards.slice(0,20).map(p => `
                        <tr>
                            <td class="cell-strong" style="direction:ltr; text-align:right; font-family:'Courier New',monospace;">${escapeHtml(p.card_number)}</td>
                            <td>${escapeHtml(p.category_name||'—')}</td>
                            <td>${parseInt(p.sold_via_portal) === 1 ? '<span class="badge badge-green">شراء ذاتي</span>' : `<span class="badge badge-purple">إرسال يدوي</span>${p.sender_name ? `<div style="font-size:10.5px; color:var(--text-muted); margin-top:2px;">بواسطة ${escapeHtml(p.sender_name)}</div>` : ''}`}</td>
                            <td>${p.sale_price ? money(p.sale_price) : '—'}</td>
                            <td style="font-size:12px; color:var(--text-muted); white-space:nowrap;">${formatDateTime(p.sent_at)}</td>
                            ${can('inventory.manage') ? `<td><button class="btn-icon btn-ghost" style="width:32px;height:32px;color:var(--danger);" title="سحب البطاقة من الزبون" onclick="openWithdrawCardModal(${p.id}, '${escapeHtml(p.card_number)}', '${escapeHtml(c.full_name)}', 'detail', ${c.id})"><i class="ph-bold ph-arrow-u-up-left"></i></button></td>` : ''}
                        </tr>
                    `).join('')}</tbody>
                </table>
            </div>` : ''}
            <div class="card-title" style="margin-bottom:10px;"><i class="ph-duotone ph-receipt"></i> آخر العمليات</div>
            <div class="table-wrap" style="margin-bottom:16px;">
                <table class="data-table">
                    <thead><tr><th>الفاتورة</th><th>الفئة</th><th>المبلغ</th><th>الحالة</th><th>التاريخ</th></tr></thead>
                    <tbody>${res.sales.length ? res.sales.slice(0,8).map(s => `
                        <tr><td class="cell-strong">${escapeHtml(s.invoice_no)}</td><td>${escapeHtml(s.category_name||'—')}</td><td>${money(s.total_sell)}</td><td>${paymentStatusBadge(s.payment_status)}</td><td style="font-size:12px; color:var(--text-muted);">${formatDate(s.sold_at)}</td></tr>
                    `).join('') : `<tr><td colspan="5" style="text-align:center; color:var(--text-muted); padding:16px;">لا توجد عمليات</td></tr>`}</tbody>
                </table>
            </div>
            <div class="card-title" style="margin-bottom:10px;"><i class="ph-duotone ph-wallet"></i> سجل حركات الرصيد</div>
            <div id="balanceHistoryBox" style="margin-bottom:8px;"><div style="text-align:center; padding:14px; color:var(--text-muted); font-size:13px;">جاري التحميل...</div></div>
        `;
        loadBalanceHistory(c.id);
    }

    async function toggleCustomerBlock(id, isBlocked) {
        const res = await apiPost('customer_toggle_block', { id });
        if (res.success) {
            showToast('success', isBlocked == 1 ? 'تم إلغاء الحظر' : 'تم حظر الزبون');
            closeModal('customerDetailModal');
            await loadCustomersCache();
            loadCustomers();
        } else handleApiError(res);
    }

    function deleteCustomer(id, name) {
        showConfirm('حذف زبون', `سيتم حذف سجل "${name}" نهائياً. هل أنت متأكد؟`, async () => {
            const res = await apiPost('customer_delete', { id });
            if (res.success) {
                showToast('success', 'تم الحذف', name);
                closeModal('customerDetailModal');
                await loadCustomersCache();
                loadCustomers();
            } else handleApiError(res);
        }, 'حذف نهائياً');
    }

    /* ════════ الديون ════════ */
    const debouncedLoadDebts = debounce(loadDebtsPage, 400);

    function setDebtsFilter(status) {
        currentDebtsFilter = status;
        document.querySelectorAll('#debtsTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.status === status));
        loadDebtsPage();
    }

    async function loadDebtsPage() {
        if (!can('debts.view')) return;
        const [summaryRes, listRes] = await Promise.all([
            apiGet('debts_summary'),
            apiGet('debts_list', { status: currentDebtsFilter, search: document.getElementById('debtsSearch').value }),
        ]);

        if (summaryRes.success) {
            document.getElementById('debtsTotalStat').textContent = money(summaryRes.total_debt);
            document.getElementById('debtsOverdueStat').textContent = summaryRes.overdue_count;
            document.getElementById('debtsCustomersStat').textContent = summaryRes.customers_count;
            updateDebtsBadge(summaryRes.customers_count);
        }

        const tbody = document.querySelector('#debtsTable tbody');
        if (!listRes.success) { handleApiError(listRes); return; }
        if (!listRes.data.length) {
            tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state"><i class="ph-duotone ph-hand-coins"></i><div class="empty-state-title">لا توجد ديون</div><div class="empty-state-sub">جميع الزبائن مسدّدين بالكامل 🎉</div></div></td></tr>`;
            return;
        }
        tbody.innerHTML = listRes.data.map(d => `
            <tr>
                <td class="cell-strong">${escapeHtml(d.customer_name || '—')}</td>
                <td style="direction:ltr; text-align:right; font-size:12.5px; color:var(--text-muted);">${escapeHtml(d.customer_phone || '—')}</td>
                <td>${money(d.original_amount)}</td>
                <td class="cell-strong" style="color:${d.status === 'paid' ? 'var(--success)' : 'var(--danger)'};">${money(d.remaining_amount)}</td>
                <td style="font-size:12.5px; color:var(--text-muted);">${d.due_date ? formatDate(d.due_date) : '—'}</td>
                <td>${debtStatusBadge(d.status)}</td>
                <td>
                    <div class="cell-actions">
                        <button class="btn-icon btn-ghost" style="width:32px;height:32px;" onclick="openDebtDetail(${d.id})" title="التفاصيل"><i class="ph-bold ph-eye"></i></button>
                        ${d.status !== 'paid' && can('debts.manage') ? `<button class="btn-icon btn-ghost" style="width:32px;height:32px; color:var(--success);" onclick="openDebtPayModal(${d.id}, '${escapeHtml(d.customer_name)}', ${d.remaining_amount})" title="تسديد"><i class="ph-bold ph-hand-coins"></i></button>` : ''}
                    </div>
                </td>
            </tr>`).join('');
    }

    function debtStatusBadge(status) {
        const map = {
            open: '<span class="badge badge-gold"><i class="ph-fill ph-clock"></i> مستحق</span>',
            overdue: '<span class="badge badge-red"><i class="ph-fill ph-warning"></i> متأخر</span>',
            paid: '<span class="badge badge-green"><i class="ph-fill ph-check-circle"></i> مسدّد</span>',
        };
        return map[status] || `<span class="badge badge-gray">${escapeHtml(status)}</span>`;
    }

    async function updateDebtsBadge(count) {
        const badge = document.getElementById('debtsBadge');
        if (!badge) return;
        if (count > 0) { badge.style.display = 'inline-block'; badge.textContent = count; }
        else badge.style.display = 'none';
    }

    async function openManualDebtModal() {
        if (!CUSTOMERS_CACHE.length) await loadCustomersCache();
        fillCustomerSelect(document.getElementById('manualDebtCustomer'), false);
        document.getElementById('manualDebtAmount').value = 0;
        document.getElementById('manualDebtDueDate').value = '';
        document.getElementById('manualDebtNote').value = '';
        openModal('manualDebtModal');
    }

    async function submitManualDebt() {
        const customerId = document.getElementById('manualDebtCustomer').value;
        const amount = parseFloat(document.getElementById('manualDebtAmount').value) || 0;
        if (!customerId) return showToast('warning', 'تنبيه', 'يرجى اختيار الزبون');
        if (amount <= 0) return showToast('warning', 'تنبيه', 'يرجى إدخال مبلغ صحيح');

        const res = await apiPost('debt_create', {
            customer_id: customerId,
            amount,
            due_date: document.getElementById('manualDebtDueDate').value,
            note: document.getElementById('manualDebtNote').value,
        });
        if (res.success) {
            showToast('success', 'تم تسجيل الدين', money(amount));
            closeModal('manualDebtModal');
            loadDebtsPage();
        } else handleApiError(res);
    }

    function openDebtPayModal(debtId, customerName, remaining) {
        document.getElementById('debtPayId').value = debtId;
        document.getElementById('debtPayCustomerName').textContent = customerName;
        document.getElementById('debtPayRemaining').textContent = money(remaining);
        document.getElementById('debtPayAmount').value = remaining;
        document.getElementById('debtPayAmount').max = remaining;
        document.getElementById('debtPayNote').value = '';
        openModal('debtPayModal');
    }

    async function submitDebtPay() {
        const debtId = document.getElementById('debtPayId').value;
        const amount = parseFloat(document.getElementById('debtPayAmount').value) || 0;
        if (amount <= 0) return showToast('warning', 'تنبيه', 'يرجى إدخال مبلغ صحيح');

        const res = await apiPost('debt_pay', { debt_id: debtId, amount, note: document.getElementById('debtPayNote').value });
        if (res.success) {
            showToast('success', 'تم التسديد', res.status === 'paid' ? 'تم سداد الدين بالكامل 🎉' : `المتبقي: ${money(res.remaining)}`);
            closeModal('debtPayModal');
            loadDebtsPage();
        } else handleApiError(res);
    }

    async function openDebtDetail(debtId) {
        openModal('debtDetailModal');
        document.getElementById('debtDetailBody').innerHTML = '<div style="text-align:center; padding:30px; color:var(--text-muted);">جاري التحميل...</div>';
        const res = await apiGet('debt_detail', { id: debtId });
        if (!res.success) { document.getElementById('debtDetailBody').innerHTML = '<div class="empty-state"><i class="ph-duotone ph-warning"></i></div>'; return; }
        const d = res.debt;
        document.getElementById('debtDetailBody').innerHTML = `
            <div class="stats-grid" style="grid-template-columns:repeat(3,1fr); margin-bottom:18px;">
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:16px;">${escapeHtml(d.customer_name)}</div><div class="stat-label">الزبون</div></div>
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:16px;">${money(d.original_amount)}</div><div class="stat-label">المبلغ الأصلي</div></div>
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:16px; color:${d.remaining_amount>0?'var(--danger)':'var(--success)'};">${money(d.remaining_amount)}</div><div class="stat-label">المتبقي</div></div>
            </div>
            ${d.note ? `<div style="font-size:13px; margin-bottom:16px; background:rgba(108,67,255,0.06); padding:10px 14px; border-radius:12px;"><i class="ph-duotone ph-note"></i> ${escapeHtml(d.note)}</div>` : ''}
            <div class="card-title" style="margin-bottom:10px;"><i class="ph-duotone ph-clock-counter-clockwise"></i> سجل التسديدات</div>
            <div class="table-wrap">
                <table class="data-table">
                    <thead><tr><th>المبلغ</th><th>ملاحظة</th><th>بواسطة</th><th>التاريخ</th></tr></thead>
                    <tbody>${res.payments.length ? res.payments.map(p => `
                        <tr><td class="cell-strong" style="color:var(--success);">${money(p.amount)}</td><td>${escapeHtml(p.note||'—')}</td><td style="font-size:12px; color:var(--text-muted);">${escapeHtml(p.user_name||'—')}</td><td style="font-size:12px; color:var(--text-muted);">${formatDateTime(p.paid_at)}</td></tr>
                    `).join('') : `<tr><td colspan="4" style="text-align:center; color:var(--text-muted); padding:16px;">لا توجد تسديدات بعد</td></tr>`}</tbody>
                </table>
            </div>
            ${d.remaining_amount > 0 && can('debts.manage') ? `<button class="btn btn-success btn-block" style="margin-top:16px;" onclick="closeModal('debtDetailModal'); openDebtPayModal(${d.id}, '${escapeHtml(d.customer_name)}', ${d.remaining_amount});"><i class="ph-bold ph-hand-coins"></i> تسجيل تسديد جديد</button>` : ''}
        `;
    }

    /* ════════ المخزون والفئات ════════ */
    let selectedCategoryColor = '#6C43FF';

    async function loadInventoryPage() {
        if (!can('inventory.view')) return;
        await loadCategoriesCache();
        const grid = document.getElementById('inventoryGrid');
        let lowStockCount = 0;

        if (!CATEGORIES_CACHE.length) {
            grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><i class="ph-duotone ph-package"></i><div class="empty-state-title">لا توجد فئات بطاقات بعد</div><div class="empty-state-sub">أضف أول فئة لتبدأ بتسجيل المبيعات</div></div>`;
        } else {
            grid.innerHTML = CATEGORIES_CACHE.map(c => {
                const low = c.quantity_available <= c.low_stock_threshold;
                if (low && c.is_active == 1) lowStockCount++;
                return `
                <div class="card" style="margin-bottom:0; ${c.is_active == 0 ? 'opacity:0.55;' : ''}">
                    <div style="display:flex; align-items:center; gap:12px; margin-bottom:14px;">
                        <div class="row-avatar" style="width:46px;height:46px;border-radius:14px;font-size:20px;background:${escapeHtml(c.color)};"><i class="ph-duotone ${escapeHtml(c.icon || 'ph-wifi-high')}"></i></div>
                        <div style="min-width:0; flex:1;">
                            <div style="font-weight:800; font-size:15px; color:var(--text-dark); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(c.name)}</div>
                            <div style="font-size:11.5px; color:var(--text-muted);">شراء ${money(c.default_buy_price)} · بيع ${money(c.default_sell_price)}</div>
                        </div>
                        ${low ? '<span class="badge badge-red"><i class="ph-fill ph-warning"></i></span>' : ''}
                    </div>
                    <div style="text-align:center; padding:14px 0; background:rgba(108,67,255,0.05); border-radius:14px; margin-bottom:14px;">
                        <div style="font-family:var(--font-display); font-size:28px; font-weight:900; color:${low ? 'var(--danger)' : 'var(--text-dark)'};">${c.quantity_available}</div>
                        <div style="font-size:11.5px; color:var(--text-muted); font-weight:600;">كرت متوفر</div>
                    </div>
                    <div style="display:flex; gap:8px;">
                        <button class="btn btn-sm btn-gold" style="flex:1;" onclick="openStockAddModal(${c.id}, '${escapeHtml(c.name)}')"><i class="ph-bold ph-plus"></i> تحديث الكمية</button>
                        <button class="btn-icon btn-outline" onclick="openCategoryModal(${c.id})" title="تعديل"><i class="ph-bold ph-pencil-simple"></i></button>
                        <button class="btn-icon ${c.is_active == 1 ? 'btn-outline danger' : 'btn-outline'}" onclick="toggleCategoryActive(${c.id})" title="${c.is_active == 1 ? 'تعطيل' : 'تفعيل'}"><i class="ph-bold ${c.is_active == 1 ? 'ph-eye-slash' : 'ph-eye'}"></i></button>
                    </div>
                </div>`;
            }).join('');
        }

        const lowStockBadge = document.getElementById('lowStockBadge');
        if (lowStockBadge) {
            if (lowStockCount > 0) { lowStockBadge.style.display = 'inline-block'; lowStockBadge.textContent = lowStockCount; }
            else lowStockBadge.style.display = 'none';
        }

        loadStockMovements();
    }

    async function loadStockMovements() {
        const res = await apiGet('stock_movements_list');
        const tbody = document.querySelector('#stockMovementsTable tbody');
        if (!res.success || !res.data.length) {
            tbody.innerHTML = `<tr><td colspan="6" style="text-align:center; color:var(--text-muted); padding:20px;">لا توجد حركات مسجّلة بعد</td></tr>`;
            return;
        }
        const typeMap = { in: '<span class="badge badge-green">وارد</span>', adjustment: '<span class="badge badge-gold">تسوية</span>', sale_out: '<span class="badge badge-red">بيع</span>' };
        tbody.innerHTML = res.data.map(m => `
            <tr>
                <td class="cell-strong">${escapeHtml(m.category_name || '—')}</td>
                <td>${typeMap[m.movement_type] || m.movement_type}</td>
                <td style="font-weight:700; color:${m.quantity >= 0 ? 'var(--success)' : 'var(--danger)'};">${m.quantity > 0 ? '+' : ''}${m.quantity}</td>
                <td style="font-size:12.5px; color:var(--text-muted);">${escapeHtml(m.note || '—')}</td>
                <td style="font-size:12px; color:var(--text-muted);">${escapeHtml(m.user_name || '—')}</td>
                <td style="font-size:12px; color:var(--text-muted); white-space:nowrap;">${formatDateTime(m.created_at)}</td>
            </tr>`).join('');
    }

    function selectCategoryColor(color) {
        selectedCategoryColor = color;
        document.getElementById('categoryColor').value = color;
        document.querySelectorAll('#categoryColorPicker .color-dot').forEach(d => d.classList.toggle('selected', d.dataset.color === color));
    }

    function openCategoryModal(categoryId = null) {
        document.getElementById('categoryId').value = categoryId || '';
        document.getElementById('categoryModalTitle').textContent = categoryId ? 'تعديل الفئة' : 'إضافة فئة جديدة';
        if (categoryId) {
            const c = CATEGORIES_CACHE.find(x => x.id == categoryId);
            if (c) {
                document.getElementById('categoryName').value = c.name;
                document.getElementById('categoryBuyPrice').value = c.default_buy_price;
                document.getElementById('categorySellPrice').value = c.default_sell_price;
                document.getElementById('categoryThreshold').value = c.low_stock_threshold;
                document.getElementById('categoryDuration').value = c.duration_hours || 0;
                selectCategoryColor(c.color);
            }
        } else {
            document.getElementById('categoryName').value = '';
            document.getElementById('categoryBuyPrice').value = 0;
            document.getElementById('categorySellPrice').value = 0;
            document.getElementById('categoryThreshold').value = 5;
            document.getElementById('categoryDuration').value = 0;
            selectCategoryColor('#6C43FF');
        }
        openModal('categoryModal');
    }

    async function saveCategory() {
        const id = document.getElementById('categoryId').value;
        const name = document.getElementById('categoryName').value.trim();
        if (!name) return showToast('warning', 'تنبيه', 'اسم الفئة مطلوب');

        const payload = {
            id: id || 0,
            name,
            default_buy_price: document.getElementById('categoryBuyPrice').value || 0,
            default_sell_price: document.getElementById('categorySellPrice').value || 0,
            low_stock_threshold: document.getElementById('categoryThreshold').value || 5,
            duration_hours: document.getElementById('categoryDuration').value || 0,
            color: document.getElementById('categoryColor').value,
        };
        const res = await apiPost(id ? 'category_update' : 'category_create', payload);
        if (res.success) {
            showToast('success', id ? 'تم التعديل' : 'تمت الإضافة', name);
            closeModal('categoryModal');
            loadInventoryPage();
        } else handleApiError(res);
    }

    async function toggleCategoryActive(id) {
        const res = await apiPost('category_toggle_active', { id });
        if (res.success) { showToast('success', 'تم التحديث'); loadInventoryPage(); }
        else handleApiError(res);
    }

    function openStockAddModal(categoryId, categoryName) {
        document.getElementById('stockCategoryId').value = categoryId;
        document.getElementById('stockCategoryLabel').textContent = 'الفئة: ' + categoryName;
        document.getElementById('stockQuantity').value = '';
        document.getElementById('stockNote').value = '';
        openModal('stockAddModal');
    }

    async function submitStockAdd() {
        const categoryId = document.getElementById('stockCategoryId').value;
        const qty = parseInt(document.getElementById('stockQuantity').value);
        if (!qty) return showToast('warning', 'تنبيه', 'يرجى إدخال كمية صحيحة (موجبة أو سالبة)');

        const res = await apiPost('stock_add', { category_id: categoryId, quantity: qty, note: document.getElementById('stockNote').value });
        if (res.success) {
            showToast('success', 'تم تحديث المخزون', qty > 0 ? `تمت إضافة ${qty} كرت` : `تم خصم ${Math.abs(qty)} كرت`);
            closeModal('stockAddModal');
            loadInventoryPage();
        } else handleApiError(res);
    }

    /* ════════ المصاريف ════════ */
    async function loadExpensesPage() {
        if (!can('expenses.view')) return;
        await loadExpenses();
        const todaySum = await apiGet('expenses_list', { from: new Date().toISOString().slice(0,10), to: new Date().toISOString().slice(0,10) });
        if (todaySum.success) {
            document.getElementById('expensesTodayStat').textContent = money(todaySum.data.reduce((s,e) => s + parseFloat(e.amount), 0));
        }
        const now = new Date();
        const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().slice(0,10);
        const monthSum = await apiGet('expenses_list', { from: monthStart, to: now.toISOString().slice(0,10) });
        if (monthSum.success) {
            document.getElementById('expensesMonthStat').textContent = money(monthSum.data.reduce((s,e) => s + parseFloat(e.amount), 0));
        }
    }

    function clearExpenseDates() {
        document.getElementById('expensesFromDate').value = '';
        document.getElementById('expensesToDate').value = '';
        loadExpenses();
    }

    async function loadExpenses() {
        const params = { from: document.getElementById('expensesFromDate').value, to: document.getElementById('expensesToDate').value };
        const res = await apiGet('expenses_list', params);
        const tbody = document.querySelector('#expensesTable tbody');
        if (!res.success) { handleApiError(res); return; }
        if (!res.data.length) {
            tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state"><i class="ph-duotone ph-wallet"></i><div class="empty-state-title">لا توجد مصاريف مسجّلة</div></div></td></tr>`;
            return;
        }
        tbody.innerHTML = res.data.map(e => `
            <tr>
                <td class="cell-strong">${escapeHtml(e.title)}</td>
                <td><span class="badge badge-purple">${escapeHtml(e.category)}</span></td>
                <td style="color:var(--danger); font-weight:700;">${money(e.amount)}</td>
                <td style="font-size:12.5px; color:var(--text-muted);">${escapeHtml(e.note || '—')}</td>
                <td style="font-size:12px; color:var(--text-muted);">${escapeHtml(e.user_name || '—')}</td>
                <td style="font-size:12px; color:var(--text-muted); white-space:nowrap;">${formatDate(e.expense_date)}</td>
                <td>${can('expenses.manage') ? `<button class="btn-icon btn-ghost" style="width:32px;height:32px; color:var(--danger);" onclick="deleteExpense(${e.id})"><i class="ph-bold ph-trash"></i></button>` : ''}</td>
            </tr>`).join('');
    }

    function openExpenseModal() {
        document.getElementById('expenseTitle').value = '';
        document.getElementById('expenseAmount').value = 0;
        document.getElementById('expenseCategory').value = 'عام';
        document.getElementById('expenseDate').value = new Date().toISOString().slice(0,10);
        document.getElementById('expenseNote').value = '';
        openModal('expenseModal');
    }

    async function submitExpense() {
        const title = document.getElementById('expenseTitle').value.trim();
        const amount = parseFloat(document.getElementById('expenseAmount').value) || 0;
        if (!title) return showToast('warning', 'تنبيه', 'عنوان المصروف مطلوب');
        if (amount <= 0) return showToast('warning', 'تنبيه', 'يرجى إدخال مبلغ صحيح');

        const res = await apiPost('expense_create', {
            title, amount,
            category: document.getElementById('expenseCategory').value,
            expense_date: document.getElementById('expenseDate').value,
            note: document.getElementById('expenseNote').value,
        });
        if (res.success) {
            showToast('success', 'تم تسجيل المصروف', `${title} — ${money(amount)}`);
            closeModal('expenseModal');
            loadExpensesPage();
        } else handleApiError(res);
    }

    function deleteExpense(id) {
        showConfirm('حذف مصروف', 'هل أنت متأكد من حذف هذا المصروف؟', async () => {
            const res = await apiPost('expense_delete', { id });
            if (res.success) { showToast('success', 'تم الحذف'); loadExpensesPage(); }
            else handleApiError(res);
        }, 'حذف');
    }

    /* ════════ التقارير والأرباح ════════ */
    function setReportPeriod(period) {
        currentReportPeriod = period;
        document.querySelectorAll('#reportsPeriodTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.period === period));
        loadReports();
    }

    async function loadReports() {
        if (!can('reports.view')) return;
        if (!document.getElementById('reportsFromDate').value) {
            const d = new Date(); d.setDate(d.getDate() - 30);
            document.getElementById('reportsFromDate').value = d.toISOString().slice(0,10);
            document.getElementById('reportsToDate').value = new Date().toISOString().slice(0,10);
        }
        const params = {
            period: currentReportPeriod,
            from: document.getElementById('reportsFromDate').value,
            to: document.getElementById('reportsToDate').value,
        };
        const res = await apiGet('reports_range', params);
        if (!res.success) return handleApiError(res);

        document.getElementById('repRevenueStat').textContent = money(res.totals.revenue);
        document.getElementById('repProfitStat').textContent = money(res.totals.profit);
        document.getElementById('repExpensesStat').textContent = money(res.totals.expenses);
        const netEl = document.getElementById('repNetProfitStat');
        netEl.textContent = money(res.totals.net_profit);
        netEl.style.color = res.totals.net_profit >= 0 ? 'var(--success)' : 'var(--danger)';

        const tbody = document.querySelector('#reportsTable tbody');
        if (!res.rows.length) {
            tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state"><i class="ph-duotone ph-chart-bar"></i><div class="empty-state-title">لا توجد بيانات لهذه الفترة</div></div></td></tr>`;
        } else {
            tbody.innerHTML = res.rows.map(r => `
                <tr>
                    <td class="cell-strong">${formatPeriodLabel(r.period_label)}</td>
                    <td>${r.orders_count}</td>
                    <td>${r.cards_sold}</td>
                    <td>${money(r.revenue)}</td>
                    <td style="color:var(--success); font-weight:700;">${money(r.profit)}</td>
                    <td style="color:var(--danger);">${money(r.expenses)}</td>
                    <td class="cell-strong" style="color:${r.net_profit>=0?'var(--success)':'var(--danger)'};">${money(r.net_profit)}</td>
                </tr>`).join('');
        }

        const topBox = document.getElementById('topCategoriesBox');
        if (!res.top_categories.length) {
            topBox.innerHTML = '<div class="empty-state" style="padding:20px;"><i class="ph-duotone ph-trophy"></i><div class="empty-state-sub">لا توجد بيانات كافية</div></div>';
        } else {
            const maxQty = Math.max(...res.top_categories.map(c => parseInt(c.qty)), 1);
            topBox.innerHTML = res.top_categories.map((c, i) => `
                <div style="margin-bottom:14px;">
                    <div style="display:flex; justify-content:space-between; font-size:12.5px; margin-bottom:5px;">
                        <span style="font-weight:700; color:var(--text-dark);">${i===0?'🥇':i===1?'🥈':i===2?'🥉':'▪️'} ${escapeHtml(c.name)}</span>
                        <span style="color:var(--text-muted);">${c.qty} كرت</span>
                    </div>
                    <div style="height:8px; background:rgba(140,132,171,0.12); border-radius:10px; overflow:hidden;">
                        <div style="height:100%; width:${(c.qty/maxQty)*100}%; background:${escapeHtml(c.color)}; border-radius:10px; transition:width 0.6s ease;"></div>
                    </div>
                </div>`).join('');
        }
    }

    function formatPeriodLabel(label) {
        if (currentReportPeriod === 'yearly') return label;
        if (currentReportPeriod === 'monthly') {
            const [y, m] = label.split('-');
            const months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
            return `${months[parseInt(m)-1]} ${y}`;
        }
        return formatDate(label);
    }

    /* ════════ أرقام البطاقات (Cards Pool) ════════ */
    let currentPoolFilter = 'available';
    const debouncedLoadCardsPool = debounce(loadCardsPool, 400);

    function setPoolFilter(status) {
        currentPoolFilter = status;
        document.querySelectorAll('#poolTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.status === status));
        loadCardsPool();
    }

    /* ═══ التحديد الجماعي لبطاقات المخزن ═══ */
    const POOL_SELECTED = new Set();

    function togglePoolSelect(id, on) {
        on ? POOL_SELECTED.add(String(id)) : POOL_SELECTED.delete(String(id));
        updatePoolBulkBar();
    }
    function togglePoolSelectAll(on) {
        document.querySelectorAll('#cardsPoolTable .pool-check').forEach(cb => {
            cb.checked = on;
            on ? POOL_SELECTED.add(cb.dataset.id) : POOL_SELECTED.delete(cb.dataset.id);
        });
        updatePoolBulkBar();
    }
    function clearPoolSelection() {
        POOL_SELECTED.clear();
        document.querySelectorAll('#cardsPoolTable .pool-check').forEach(cb => cb.checked = false);
        const sa = document.getElementById('poolSelectAll');
        if (sa) sa.checked = false;
        updatePoolBulkBar();
    }
    function updatePoolBulkBar() {
        const bar = document.getElementById('poolBulkBar');
        if (!bar) return;
        document.getElementById('poolSelCount').textContent = POOL_SELECTED.size;
        bar.style.display = POOL_SELECTED.size ? 'flex' : 'none';
    }
    function bulkDeleteSelectedCards() {
        if (!POOL_SELECTED.size) return;
        showConfirm('حذف جماعي', `سيُحذف ${POOL_SELECTED.size} رقم بطاقة نهائياً من المخزن. البطاقات المُرسلة للزبائن محمية ولن تُحذف.`, async () => {
            const res = await apiPost('cards_pool_bulk_delete', { ids: Array.from(POOL_SELECTED).join(',') });
            if (res.success) {
                showToast('success', `حُذف ${res.deleted} بطاقة 🗑️`, res.skipped ? `تم تجاوز ${res.skipped} (مُرسلة أو غير موجودة)` : '');
                clearPoolSelection();
                loadCardsPool();
            } else handleApiError(res);
        }, 'حذف نهائياً');
    }

    async function loadCardsPool() {
        if (!can('inventory.view')) return;
        const res = await apiGet('cards_pool_list', { status: currentPoolFilter, search: document.getElementById('poolSearch').value });
        if (!res.success) return handleApiError(res);
        document.getElementById('poolAvailableStat').textContent = res.summary.available;
        document.getElementById('poolSentStat').textContent = res.summary.sent;

        clearPoolSelection(); // البيانات تغيّرت — تحديد نظيف

        const tbody = document.querySelector('#cardsPoolTable tbody');
        if (!res.data.length) {
            tbody.innerHTML = `<tr><td colspan="8"><div class="empty-state"><i class="ph-duotone ph-cards"></i><div class="empty-state-title">لا توجد أرقام</div><div class="empty-state-sub">ارفع دفعة أرقام لتبدأ بالإرسال للزبائن</div></div></td></tr>`;
            return;
        }
        const canBulk = can('inventory.manage');
        tbody.innerHTML = res.data.map(c => `
            <tr>
                <td style="text-align:center;">${c.status === 'available' && canBulk ? `<input type="checkbox" class="pool-check" data-id="${c.id}" onchange="togglePoolSelect('${c.id}', this.checked)">` : ''}</td>
                <td style="font-family:'Courier New',monospace; font-weight:700; direction:ltr; text-align:right;">${escapeHtml(c.card_number)}</td>
                <td>${c.category_name ? `<span class="badge-dot" style="color:${escapeHtml(c.category_color || '#6C43FF')};"></span> ${escapeHtml(c.category_name)}` : '—'}</td>
                <td>${c.status === 'available' ? '<span class="badge badge-green">متاحة</span>' : '<span class="badge badge-purple">مرسلة</span>'}</td>
                <td>${escapeHtml(c.customer_name || '—')}</td>
                <td style="font-size:12px; color:var(--text-muted);">${escapeHtml(c.sender_name || '—')}</td>
                <td style="font-size:12px; color:var(--text-muted); white-space:nowrap;">${c.sent_at ? formatDateTime(c.sent_at) : formatDateTime(c.created_at)}</td>
                <td>
                    <div class="cell-actions">
                        ${c.status === 'available' && can('sales.create') ? `<button class="btn-icon btn-ghost" style="width:32px;height:32px; color:var(--primary);" onclick="openCardSendModal(${c.id}, '${escapeHtml(c.card_number)}')" title="إرسال هذه البطاقة"><i class="ph-bold ph-paper-plane-tilt"></i></button>` : ''}
                        ${c.status === 'available' && can('inventory.manage') ? `<button class="btn-icon btn-ghost" style="width:32px;height:32px; color:var(--danger);" onclick="deletePoolCard(${c.id})" title="حذف"><i class="ph-bold ph-trash"></i></button>` : ''}
                    </div>
                </td>
            </tr>`).join('');
    }

    async function openCardsUploadModal() {
        if (!CATEGORIES_CACHE.length) await loadCategoriesCache();
        document.getElementById('cuCategory').innerHTML = '<option value="">بدون فئة</option>' + CATEGORIES_CACHE.map(c => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');
        document.getElementById('cuNumbers').value = '';
        const cf = document.getElementById('cuFile'); if (cf) cf.value = '';
        const fh = document.getElementById('cuFileHint'); if (fh) fh.textContent = 'اختر ملف .txt — كل سطر رقم بطاقة، وستُضاف الأرقام للمربع بالأسفل تلقائياً';
        updateCuCount();
        openModal('cardsUploadModal');
    }

    /* قراءة ملف TXT من الجهاز وإدراج أرقامه في مربع الأرقام */
    function readCardsFile(input) {
        const f = input.files && input.files[0];
        if (!f) return;
        const reader = new FileReader();
        reader.onload = () => {
            const ta = document.getElementById('cuNumbers');
            const incoming = String(reader.result || '').trim();
            if (!incoming) { showToast('warning', 'الملف فارغ', 'لم يتم العثور على أي أرقام داخل الملف'); input.value = ''; return; }
            const existing = ta.value.trim();
            ta.value = (existing ? existing + '\n' : '') + incoming;
            updateCuCount();
            const count = ta.value.split(/\r\n|\r|\n/).filter(l => l.trim()).length;
            document.getElementById('cuFileHint').textContent = `تمت قراءة «${f.name}» ✅ — الإجمالي الآن: ${count} رقم`;
            input.value = '';
        };
        reader.onerror = () => showToast('error', 'تعذر قراءة الملف', 'جرّب ملف .txt آخر');
        reader.readAsText(f, 'UTF-8');
    }

    function updateCuCount() {
        const hint = document.getElementById('cuCountHint');
        if (!hint) return;
        const count = document.getElementById('cuNumbers').value.split(/\r\n|\r|\n/).filter(l => l.trim()).length;
        hint.textContent = count ? `عدد الأرقام في المربع: ${count} — التكرارات تُستبعد تلقائياً` : 'يمكنك لصق محتوى ملف نصي كامل — التكرارات تُستبعد تلقائياً';
    }

    async function submitCardsUpload() {
        const numbers = document.getElementById('cuNumbers').value.trim();
        if (!numbers) return showToast('warning', 'تنبيه', 'الصق الأرقام أولاً');
        const res = await apiPost('cards_upload', { numbers, category_id: document.getElementById('cuCategory').value });
        if (res.success) {
            showToast('success', 'تم الرفع', `أُضيف ${res.added} رقم` + (res.skipped ? ` — تم تجاوز ${res.skipped} مكرر` : ''));
            closeModal('cardsUploadModal');
            loadCardsPool();
        } else handleApiError(res);
    }

    async function openCardSendModal(cardId = null, cardNumber = '') {
        if (!CUSTOMERS_CACHE.length) await loadCustomersCache();
        if (!CATEGORIES_CACHE.length) await loadCategoriesCache();
        const portalCustomers = CUSTOMERS_CACHE.filter(c => c.username);
        document.getElementById('csCustomer').innerHTML = '<option value="">— اختر الزبون —</option>'
            + portalCustomers.map(c => `<option value="${c.id}">${escapeHtml(c.full_name)} (@${escapeHtml(c.username)})</option>`).join('');
        document.getElementById('csCategory').innerHTML = '<option value="">أي فئة</option>' + CATEGORIES_CACHE.map(c => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');
        document.getElementById('csSpecificCardId').value = cardId || '';
        document.getElementById('csSpecificCardInfo').style.display = cardId ? 'block' : 'none';
        document.getElementById('csSpecificCardNumber').textContent = cardNumber;
        document.getElementById('csAutoRow').style.display = cardId ? 'none' : 'grid';
        document.getElementById('csQty').value = 1;
        if (!portalCustomers.length) showToast('warning', 'لا يوجد زبائن بحسابات', 'اطلب من زبائنك التسجيل في البوابة أولاً');
        openModal('cardSendModal');
    }

    async function submitCardSend() {
        const customerId = document.getElementById('csCustomer').value;
        if (!customerId) return showToast('warning', 'تنبيه', 'اختر الزبون');
        const btn = document.getElementById('csSubmitBtn');
        btn.disabled = true;
        const res = await apiPost('card_send', {
            customer_id: customerId,
            card_id: document.getElementById('csSpecificCardId').value || 0,
            category_id: document.getElementById('csCategory').value,
            quantity: document.getElementById('csQty').value || 1,
        });
        btn.disabled = false;
        if (res.success) {
            showToast('success', `أُرسلت ${res.sent} بطاقة 🎫`, 'وصل الزبون إشعار بالأرقام');
            closeModal('cardSendModal');
            loadCardsPool();
        } else handleApiError(res);
    }

    function deletePoolCard(id) {
        showConfirm('حذف رقم بطاقة', 'سيُحذف هذا الرقم من المخزن نهائياً', async () => {
            const res = await apiPost('card_pool_delete', { id });
            if (res.success) { showToast('success', 'تم الحذف'); loadCardsPool(); }
            else handleApiError(res);
        }, 'حذف');
    }

    /* ════════ سجل البطاقات ════════ */
    const debouncedLoadCardLog = debounce(loadCardLog, 400);

    async function loadCardLog() {
        if (!can('sales.view')) return;
        const res = await apiGet('cards_log_list', { search: document.getElementById('clogSearch').value });
        if (!res.success) return handleApiError(res);
        document.getElementById('clogTotalStat').textContent = res.summary.total;
        document.getElementById('clogTodayStat').textContent = res.summary.today;
        document.getElementById('clogPortalStat').textContent = res.summary.via_portal;

        const tbody = document.querySelector('#cardLogTable tbody');
        if (!res.data.length) {
            tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state"><i class="ph-duotone ph-clipboard-text"></i><div class="empty-state-title">لا يوجد سجل بعد</div><div class="empty-state-sub">أول ما تُرسَل أو تُشترى بطاقة رح تظهر هنا مع الوقت والتاريخ</div></div></td></tr>`;
            return;
        }
        tbody.innerHTML = res.data.map(c => `
            <tr>
                <td style="font-family:'Courier New',monospace; font-weight:700; direction:ltr; text-align:right;">${escapeHtml(c.card_number)}</td>
                <td>${c.category_name ? `<span class="badge-dot" style="color:${escapeHtml(c.category_color || '#6C43FF')};"></span> ${escapeHtml(c.category_name)}` : '—'}</td>
                <td>${escapeHtml(c.customer_name || '—')}${c.customer_username ? ` <span style="font-size:11px; color:var(--text-muted);">@${escapeHtml(c.customer_username)}</span>` : ''}</td>
                <td>${parseInt(c.sold_via_portal) === 1
                    ? '<span class="badge badge-green">شراء ذاتي من البوابة</span>'
                    : `<span class="badge badge-purple">إرسال يدوي</span>${c.sender_name ? `<div style="font-size:11px; color:var(--text-muted); margin-top:3px;">بواسطة ${escapeHtml(c.sender_name)}</div>` : ''}`}</td>
                <td style="font-weight:700;">${c.sale_price ? money(c.sale_price) : '—'}</td>
                <td style="font-size:12px; color:var(--text-muted); white-space:nowrap;">${formatDateTime(c.sent_at)}</td>
                <td>${can('inventory.manage') ? `<button class="btn-icon btn-ghost" style="width:32px;height:32px;color:var(--danger);" title="سحب البطاقة من الزبون" onclick="openWithdrawCardModal(${c.id}, '${escapeHtml(c.card_number)}', '${escapeHtml(c.customer_name || '')}', 'log', 0)"><i class="ph-bold ph-arrow-u-up-left"></i></button>` : ''}</td>
            </tr>`).join('');
    }

    /* ════════ إيصالات الدفع ════════ */
    let currentReceiptsFilter = 'pending';
    let RECEIPTS_CACHE = [];

    function setReceiptsFilter(status) {
        currentReceiptsFilter = status;
        document.querySelectorAll('#receiptsTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.status === status));
        loadReceipts();
    }

    async function loadReceipts() {
        if (!can('debts.manage')) return;
        const res = await apiGet('receipts_list', { status: currentReceiptsFilter });
        if (!res.success) return handleApiError(res);
        RECEIPTS_CACHE = res.data;
        const grid = document.getElementById('receiptsGrid');
        if (!res.data.length) {
            grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><i class="ph-duotone ph-receipt"></i><div class="empty-state-title">لا توجد إيصالات</div><div class="empty-state-sub">إيصالات التحويل من الزبائن ستظهر هنا</div></div>`;
            refreshSidebarBadges();
            return;
        }
        const statusBadge = { pending: '<span class="badge badge-gold">قيد المراجعة</span>', approved: '<span class="badge badge-green">مقبول</span>', rejected: '<span class="badge badge-red">مرفوض</span>' };
        grid.innerHTML = res.data.map(r => `
            <div class="card" style="margin-bottom:0; cursor:${r.status === 'pending' ? 'pointer' : 'default'};" ${r.status === 'pending' ? `onclick="openReceiptReview(${r.id})"` : ''}>
                <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:12px;">
                    <div style="display:flex; align-items:center; gap:10px;">
                        <div class="row-avatar" style="width:40px;height:40px;background:${r.method === 'palpay' ? 'linear-gradient(140deg,#0FA97A,#0A9068)' : 'linear-gradient(140deg,#E5484D,#C22F62)'};"><i class="ph-fill ph-wallet"></i></div>
                        <div>
                            <div style="font-weight:800; color:var(--text-dark); font-size:14px;">${escapeHtml(r.customer_name || '—')}</div>
                            <div style="font-size:11px; color:var(--text-muted);">${r.method === 'palpay' ? 'PalPay' : 'Jawwal Pay'}</div>
                        </div>
                    </div>
                    ${statusBadge[r.status] || ''}
                </div>
                ${r.has_image ? `<img src="?action=receipt_image&id=${r.id}" alt="إيصال" loading="lazy" style="width:100%; height:150px; object-fit:cover; border-radius:14px; border:1px solid var(--border-light); margin-bottom:12px;">` : ''}
                <div style="display:flex; justify-content:space-between; align-items:center; font-size:12.5px;">
                    <strong style="font-family:var(--font-display); font-size:18px; color:var(--text-dark);">${money(r.amount)}</strong>
                    <span style="color:var(--text-muted); font-size:11.5px;">${formatDateTime(r.created_at)}</span>
                </div>
                ${r.note ? `<div style="font-size:11.5px; color:var(--text-muted); margin-top:8px;"><i class="ph-duotone ph-note"></i> ${escapeHtml(r.note)}</div>` : ''}
                ${r.review_note ? `<div style="font-size:11.5px; color:var(--text-muted); margin-top:6px;"><i class="ph-duotone ph-chat-circle"></i> ${escapeHtml(r.review_note)}</div>` : ''}
                ${r.status === 'pending' ? `<button class="btn btn-sm btn-gold btn-block" style="margin-top:12px;" onclick="event.stopPropagation(); openReceiptReview(${r.id});"><i class="ph-bold ph-magnifying-glass"></i> مراجعة الآن</button>` : ''}
            </div>`).join('');
        refreshSidebarBadges();
    }

    function openReceiptReview(id) {
        const r = RECEIPTS_CACHE.find(x => x.id == id);
        if (!r) return;
        document.getElementById('rrId').value = id;
        document.getElementById('rrNote').value = '';
        document.getElementById('rrApplyDebt').checked = true;
        document.getElementById('rrDetails').innerHTML = `
            <div class="stats-grid" style="grid-template-columns:repeat(2,1fr); margin-bottom:14px;">
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:15px;">${escapeHtml(r.customer_name)}</div><div class="stat-label">الزبون</div></div>
                <div class="stat-card" style="padding:14px;"><div class="stat-value" style="font-size:18px;">${money(r.amount)}</div><div class="stat-label">${r.method === 'palpay' ? 'PalPay' : 'Jawwal Pay'}</div></div>
            </div>
            ${r.has_image ? `<img src="?action=receipt_image&id=${r.id}" alt="إيصال" style="width:100%; max-height:340px; object-fit:contain; border-radius:14px; border:1px solid var(--border-light); background:#fff; margin-bottom:8px;">` : '<div class="empty-state" style="padding:14px;"><div class="empty-state-sub">بدون صورة</div></div>'}
            ${r.note ? `<div style="font-size:12.5px; color:var(--text-muted); margin-bottom:8px;">ملاحظة الزبون: ${escapeHtml(r.note)}</div>` : ''}
        `;
        openModal('receiptReviewModal');
    }

    async function submitReceiptReview(decision) {
        const id = document.getElementById('rrId').value;
        const mode = document.querySelector('input[name="rrApplyMode"]:checked')?.value || 'none';
        const res = await apiPost('receipt_review', {
            id,
            decision,
            review_note: document.getElementById('rrNote').value,
            apply_to_debt: mode === 'debt' ? 1 : 0,
            apply_to_balance: mode === 'balance' ? 1 : 0,
        });
        if (res.success) {
            let detail = 'وصل الزبون إشعار بالنتيجة';
            if (res.applied > 0) detail = `سُدد ${money(res.applied)} من ديون الزبون`;
            else if (res.credited_balance > 0) detail = `شُحن رصيد الزبون — الرصيد الحالي: ${money(res.credited_balance)}`;
            showToast('success', decision === 'approved' ? 'تم قبول الإيصال ✅' : 'تم رفض الإيصال', detail);
            closeModal('receiptReviewModal');
            loadReceipts();
        } else handleApiError(res);
    }

    /* ════════ طلبات الشراء ════════ */
    let currentRequestsFilter = 'pending';

    function setRequestsFilter(status) {
        currentRequestsFilter = status;
        document.querySelectorAll('#requestsTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.status === status));
        loadRequests();
