    async function loadRequests() {
        if (!can('sales.view')) return;
        const res = await apiGet('requests_list', { status: currentRequestsFilter });
        if (!res.success) return handleApiError(res);
        const tbody = document.querySelector('#requestsTable tbody');
        if (!res.data.length) {
            tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state"><i class="ph-duotone ph-shopping-cart"></i><div class="empty-state-title">لا توجد طلبات</div><div class="empty-state-sub">طلبات الشراء من زبائن البوابة ستظهر هنا</div></div></td></tr>`;
            refreshSidebarBadges();
            return;
        }
        const statusBadge = { pending: '<span class="badge badge-gold">جديد</span>', approved: '<span class="badge badge-purple">مقبول</span>', rejected: '<span class="badge badge-red">مرفوض</span>', done: '<span class="badge badge-green">مكتمل</span>' };
        tbody.innerHTML = res.data.map(r => `
            <tr>
                <td class="cell-strong">${escapeHtml(r.customer_name || '—')}</td>
                <td style="direction:ltr; text-align:right; font-size:12px; color:var(--text-muted);">${escapeHtml(r.customer_phone || '—')}</td>
                <td>${r.quantity} × ${escapeHtml(r.category_name || 'أي نوع')}</td>
                <td style="font-size:12px; color:var(--text-muted);">${escapeHtml(r.note || '—')}</td>
                <td>${statusBadge[r.status] || ''}</td>
                <td style="font-size:12px; color:var(--text-muted); white-space:nowrap;">${formatDateTime(r.created_at)}</td>
                <td>
                    ${r.status === 'pending' && can('sales.create') ? `
                    <div class="cell-actions">
                        <button class="btn-icon btn-ghost" style="width:32px;height:32px; color:var(--success);" onclick="updateRequest(${r.id}, 'approved')" title="قبول"><i class="ph-bold ph-check"></i></button>
                        <button class="btn-icon btn-ghost" style="width:32px;height:32px; color:var(--danger);" onclick="updateRequest(${r.id}, 'rejected')" title="رفض"><i class="ph-bold ph-x"></i></button>
                    </div>` : (r.status === 'approved' && can('sales.create') ? `<button class="btn btn-sm btn-success" onclick="updateRequest(${r.id}, 'done')"><i class="ph-bold ph-check-circle"></i> اكتمل</button>` : '')}
                </td>
            </tr>`).join('');
        refreshSidebarBadges();
    }

    async function updateRequest(id, status) {
        const res = await apiPost('request_update', { id, status });
        if (res.success) { showToast('success', 'تم التحديث', 'وصل الزبون إشعار بالحالة الجديدة'); loadRequests(); }
        else handleApiError(res);
    }

