    function openNotifyCustomerModal(customerId, customerName) {
        document.getElementById('ncCustomerId').value = customerId;
        document.getElementById('ncCustomerName').textContent = customerName;
        document.getElementById('ncTitle').value = '';
        document.getElementById('ncBody').value = '';
        openModal('notifyCustomerModal');
    }

    function fillDebtReminderTemplate() {
        document.getElementById('ncTitle').value = '💰 تذكير بالدين المستحق';
        document.getElementById('ncBody').value = 'نذكّرك بوجود دين مستحق على حسابك. يمكنك السداد عبر PalPay أو Jawwal Pay من تبويب «الدفع» في التطبيق ورفع صورة الإشعار ليُخصم تلقائياً. شكراً لتعاونك 🙏';
