    async function submitCustomerNotify() {
        const customerId = document.getElementById('ncCustomerId').value;
        const title = document.getElementById('ncTitle').value.trim();
        if (!title) return showToast('warning', 'تنبيه', 'اكتب عنوان الإشعار');
        const res = await apiPost('customer_notify', { customer_id: customerId, title, body: document.getElementById('ncBody').value });
        if (res.success) {
            showToast('success', 'أُرسل الإشعار 🔔', 'سيصل الزبون حتى لو كان خارج التطبيق');
            closeModal('notifyCustomerModal');
