    /* ════════ شحن رصيد زبون ════════ */
    function openRechargeBalanceModal(customerId, customerName, currentBalance) {
        document.getElementById('rbCustomerId').value = customerId;
        document.getElementById('rbCustomerName').textContent = customerName;
        document.getElementById('rbCurrentBalance').textContent = money(currentBalance || 0);
        document.getElementById('rbAmount').value = '';
        document.getElementById('rbNote').value = '';
        openModal('rechargeBalanceModal');
    }

    async function submitRechargeBalance() {
        const customerId = document.getElementById('rbCustomerId').value;
        const amount = parseFloat(document.getElementById('rbAmount').value) || 0;
        if (amount <= 0) return showToast('warning', 'تنبيه', 'أدخل مبلغاً أكبر من صفر');
        const btn = document.getElementById('rbSubmitBtn');
        btn.disabled = true;
        const res = await apiPost('customer_recharge_balance', { id: customerId, amount, note: document.getElementById('rbNote').value });
        btn.disabled = false;
        if (res.success) {
            showToast('success', 'تم شحن الرصيد 💰', `الرصيد الجديد: ${money(res.new_balance)}`);
            closeModal('rechargeBalanceModal');
            await loadCustomersCache();
            if (document.getElementById('page-customers').classList.contains('active')) loadCustomers();
            if (document.getElementById('customerDetailModal').classList.contains('show')) openCustomerDetail(customerId);
        } else handleApiError(res);
    }

    async function loadBalanceHistory(customerId) {
        const res = await apiGet('customer_balance_transactions', { id: customerId });
        const box = document.getElementById('balanceHistoryBox');
        if (!box) return;
        if (!res.success || !res.data.length) {
            box.innerHTML = '<div class="empty-state" style="padding:16px;"><div class="empty-state-sub">لا حركات رصيد بعد</div></div>';
            return;
        }
        const typeLabels = { recharge: ['شحن يدوي', 'ph-plus-circle', 'var(--success)'], purchase: ['شراء بطاقة', 'ph-cards', 'var(--danger)'], refund: ['استرجاع', 'ph-arrow-counter-clockwise', 'var(--gold)'], receipt_credit: ['شحن عبر إيصال', 'ph-receipt', 'var(--success)'], deduct: ['خصم إداري', 'ph-minus-circle', 'var(--danger)'] };
        box.innerHTML = res.data.map(t => {
            const [label, icon, color] = typeLabels[t.type] || [t.type, 'ph-circle', 'var(--text-muted)'];
            const sign = (t.type === 'purchase' || t.type === 'deduct') ? '-' : '+';
            return `<div class="notif-item">
                <div class="notif-icon" style="background:${color};"><i class="ph-fill ${icon}"></i></div>
                <div style="flex:1;">
                    <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                        <span style="font-weight:800; color:var(--text-dark);">${label}</span>
                        <span style="font-weight:800; color:${color};">${sign}${money(t.amount)}</span>
                    </div>
                    <div style="font-size:11px; color:var(--text-muted); margin-top:3px;">الرصيد بعدها: ${money(t.balance_after)} · ${formatDateTime(t.created_at)}${t.note ? ' · ' + escapeHtml(t.note) : ''}${t.user_name ? ' · بواسطة ' + escapeHtml(t.user_name) : ''}</div>
                </div>
            </div>`;
        }).join('');
    }

    async function togglePortalBlock(customerId) {
        const res = await apiPost('customer_toggle_portal_block', { id: customerId });
        if (res.success) {
            showToast('success', res.portal_block_debt == 1 ? 'فُعّل الحجب حتى السداد 🔒' : 'أُلغي الحجب ✅');
            closeModal('customerDetailModal');
            await loadCustomersCache();
            loadCustomers();
        } else handleApiError(res);
    }

    async function toggleDebtVisibility(customerId) {
        const res = await apiPost('customer_toggle_debt_visibility', { id: customerId });
        if (res.success) {
            showToast('success', res.portal_show_debt == 1 ? 'أصبح الدين ظاهراً للزبون في بوابته 👁️' : 'أُخفي الدين من بوابة الزبون ✅');
            closeModal('customerDetailModal');
            await loadCustomersCache();
            loadCustomers();
        } else handleApiError(res);
    }

    /* ════════ الموظفون والصلاحيات ════════ */
    let EMPLOYEES_CACHE = [];
    let selectedEmployeeColor = '#6C43FF';

    async function loadEmployees() {
        if (!can('employees.manage')) return;
        const res = await apiGet('employees_list');
        if (!res.success) return handleApiError(res);
        EMPLOYEES_CACHE = res.data;
        const grid = document.getElementById('employeesGrid');
        grid.innerHTML = res.data.map(u => {
            const perms = JSON.parse(u.permissions || '{}');
            const permCount = Object.values(perms).filter(Boolean).length;
            return `
            <div class="card" style="margin-bottom:0; ${u.is_active == 0 ? 'opacity:0.55;' : ''}">
                <div style="display:flex; align-items:center; gap:12px; margin-bottom:14px;">
                    <div class="user-avatar" style="width:48px;height:48px;font-size:19px;background:${escapeHtml(u.avatar_color)};">${escapeHtml(initialsOf(u.full_name))}</div>
                    <div style="min-width:0; flex:1;">
                        <div style="font-weight:800; font-size:15px; color:var(--text-dark);">${escapeHtml(u.full_name)}</div>
                        <div style="font-size:12px; color:var(--text-muted);">@${escapeHtml(u.username)} · ${u.role === 'owner' ? 'المالك' : `${permCount} صلاحية مفعّلة`}</div>
                    </div>
                    ${u.role === 'owner' ? '<span class="badge badge-gold"><i class="ph-fill ph-crown-simple"></i> مالك</span>' : (u.is_active == 1 ? '<span class="badge badge-green">نشط</span>' : '<span class="badge badge-gray">موقوف</span>')}
                </div>
                <div style="font-size:11.5px; color:var(--text-muted); margin-bottom:14px;">آخر دخول: ${u.last_login ? formatDateTime(u.last_login) : 'لم يسجل دخول بعد'}</div>
                ${u.role !== 'owner' ? `
                <div style="display:flex; gap:8px;">
                    <button class="btn btn-sm btn-outline" style="flex:1;" onclick="openEmployeeModal(${u.id})"><i class="ph-bold ph-pencil-simple"></i> تعديل</button>
                    <button class="btn-icon ${u.is_active == 1 ? 'btn-outline danger' : 'btn-outline'}" onclick="toggleEmployeeActive(${u.id})" title="${u.is_active == 1 ? 'إيقاف' : 'تفعيل'}"><i class="ph-bold ${u.is_active == 1 ? 'ph-pause' : 'ph-play'}"></i></button>
                    <button class="btn-icon btn-outline danger" onclick="deleteEmployee(${u.id}, '${escapeHtml(u.full_name)}')" title="حذف"><i class="ph-bold ph-trash"></i></button>
                </div>` : ''}
            </div>`;
        }).join('');
    }

    function buildPermsGrid(containerId, checkedPerms = {}) {
        const container = document.getElementById(containerId);
        container.innerHTML = Object.entries(ALL_PERMS).map(([key, label]) => `
            <div class="perm-item">
                <span>${escapeHtml(label)}</span>
                <label class="toggle-switch">
                    <input type="checkbox" data-perm="${key}" ${checkedPerms[key] ? 'checked' : ''}>
                    <span class="toggle-track"></span>
                </label>
            </div>`).join('');
    }

    function collectPermsFromGrid(containerId) {
        const perms = {};
        document.querySelectorAll(`#${containerId} input[data-perm]`).forEach(inp => { perms[inp.dataset.perm] = inp.checked; });
        return perms;
    }

    function selectEmployeeColor(color) {
        selectedEmployeeColor = color;
        document.getElementById('employeeColor').value = color;
        document.querySelectorAll('#employeeColorPicker .color-dot').forEach(d => d.classList.toggle('selected', d.dataset.color === color));
    }

    function openEmployeeModal(employeeId = null) {
        document.getElementById('employeeId').value = employeeId || '';
        document.getElementById('employeeModalTitle').textContent = employeeId ? 'تعديل بيانات الموظف' : 'إضافة موظف جديد';
        document.getElementById('employeeUsername').disabled = !!employeeId;
        document.getElementById('employeePasswordLabel').innerHTML = employeeId ? 'كلمة مرور جديدة (اتركها فارغة لعدم التغيير)' : 'كلمة المرور <span class="req">*</span>';

        if (employeeId) {
            const u = EMPLOYEES_CACHE.find(x => x.id == employeeId);
            if (u) {
                document.getElementById('employeeFullName').value = u.full_name;
                document.getElementById('employeeUsername').value = u.username;
                document.getElementById('employeePassword').value = '';
                selectEmployeeColor(u.avatar_color);
                buildPermsGrid('employeePermsGrid', JSON.parse(u.permissions || '{}'));
            }
        } else {
            document.getElementById('employeeFullName').value = '';
            document.getElementById('employeeUsername').value = '';
            document.getElementById('employeePassword').value = '';
            selectEmployeeColor('#6C43FF');
            buildPermsGrid('employeePermsGrid', {});
        }
        openModal('employeeModal');
    }

    async function saveEmployee() {
        const id = document.getElementById('employeeId').value;
        const fullName = document.getElementById('employeeFullName').value.trim();
        const username = document.getElementById('employeeUsername').value.trim();
        const password = document.getElementById('employeePassword').value;

        if (!fullName) return showToast('warning', 'تنبيه', 'الاسم الكامل مطلوب');
        if (!id && !username) return showToast('warning', 'تنبيه', 'اسم المستخدم مطلوب');
        if (!id && password.length < 4) return showToast('warning', 'تنبيه', 'كلمة المرور يجب أن تكون 4 أحرف على الأقل');

        const perms = collectPermsFromGrid('employeePermsGrid');
        const payload = {
            full_name: fullName,
            username,
            password,
            avatar_color: document.getElementById('employeeColor').value,
            permissions: JSON.stringify(perms),
        };
        if (id) payload.id = id;

        const res = await apiPost(id ? 'employee_update' : 'employee_create', payload);
        if (res.success) {
            showToast('success', id ? 'تم التعديل' : 'تمت الإضافة', fullName);
            closeModal('employeeModal');
            loadEmployees();
        } else handleApiError(res);
    }

    async function toggleEmployeeActive(id) {
        const res = await apiPost('employee_toggle_active', { id });
        if (res.success) { showToast('success', 'تم التحديث'); loadEmployees(); }
        else handleApiError(res);
    }

    function deleteEmployee(id, name) {
        showConfirm('حذف موظف', `سيتم حذف حساب "${name}" نهائياً. هل أنت متأكد؟`, async () => {
            const res = await apiPost('employee_delete', { id });
            if (res.success) { showToast('success', 'تم الحذف'); loadEmployees(); }
            else handleApiError(res);
        }, 'حذف نهائياً');
    }

    /* ════════ الإعدادات ════════ */
    async function loadSettingsPage() {
        const res = await apiGet('settings_get');
        if (!res.success) return;
        const d = res.data || {};
        document.getElementById('settingsShopName').value = d.shop_name || '';
        const maintOn = (d.maintenance_mode || '0') === '1';
        const mt = document.getElementById('maintToggle');
        if (mt) mt.checked = maintOn;
        updateMaintPill(maintOn);
        const mm = document.getElementById('maintMessage');
        if (mm) mm.value = d.maintenance_message || '';
        const ip = document.getElementById('iconPreviewImg');
        if (ip) ip.src = '?action=icon&s=192&v=' + encodeURIComponent(d.icon_version || '1');
    }

    async function saveSettings() {
        const shopName = document.getElementById('settingsShopName').value.trim();
        if (!shopName) return showToast('warning', 'تنبيه', 'اسم المحل مطلوب');
        const res = await apiPost('settings_update', { shop_name: shopName });
        if (res.success) {
            showToast('success', 'تم الحفظ', 'تم تحديث إعدادات النظام');
            document.querySelectorAll('.sidebar-brand-title').forEach(el => el.textContent = shopName);
        } else handleApiError(res);
    }

    function updateMaintPill(on) {
        const pill = document.getElementById('maintStatusPill');
        if (!pill) return;
        pill.className = 'maint-pill ' + (on ? 'on' : 'off');
        pill.innerHTML = on ? '<i class="ph-bold ph-wrench"></i> الصيانة مفعّلة — بوابة الزبائن مقفلة' : '<i class="ph-bold ph-check-circle"></i> النظام يعمل';
    }

    async function toggleMaintenance(cb) {
        const on = cb.checked;
        const res = await apiPost('settings_update', { maintenance_mode: on ? '1' : '0' });
        if (res.success) {
            updateMaintPill(on);
            showToast(on ? 'warning' : 'success', on ? 'وضع الصيانة مفعّل 🔧' : 'عاد النظام للعمل ✅', on ? 'بوابة الزبائن مقفلة الآن — لوحة الإدارة تعمل طبيعي' : 'الزبائن يقدروا يدخلوا ويشتروا الآن');
        } else { cb.checked = !on; handleApiError(res); }
    }

    async function saveMaintenanceMsg() {
        const res = await apiPost('settings_update', { maintenance_message: document.getElementById('maintMessage').value.trim() });
        if (res.success) showToast('success', 'تم الحفظ', 'حُدّثت رسالة الصيانة');
        else handleApiError(res);
    }

    async function uploadAppIcon(input) {
        const file = input.files && input.files[0];
        if (!file) return;
        if (file.size > 3 * 1024 * 1024) { input.value = ''; return showToast('warning', 'الصورة كبيرة', 'الحد الأقصى 3 ميجابايت'); }
        const fd = new FormData();
        fd.append('icon', file);
        showToast('success', 'جارٍ الرفع...', 'يتم معالجة الأيقونة الجديدة');
        try {
            const r = await fetch('?action=settings_upload_icon', { method: 'POST', body: fd });
            const res = await r.json();
            if (res.success) {
                const ip = document.getElementById('iconPreviewImg');
                if (ip) ip.src = '?action=icon&s=192&v=' + Date.now();
                showToast('success', 'تم تغيير الأيقونة 🎨', 'ستظهر في المتصفح والإشعارات فوراً — وإذا التطبيق مثبّت على الجوال أعد تثبيته لتتحدّث أيقونة الشاشة الرئيسية');
            } else handleApiError(res);
        } catch (e) { showToast('error', 'خطأ', 'تعذر رفع الصورة — تحقق من الاتصال'); }
        input.value = '';
    }

    function resetAppIcon() {
        showConfirm('إعادة الأيقونة الافتراضية', 'سيتم حذف الأيقونة المخصصة والرجوع لشعار النظام الأصلي', async () => {
            const res = await apiPost('settings_reset_icon');
            if (res.success) {
                const ip = document.getElementById('iconPreviewImg');
                if (ip) ip.src = '?action=icon&s=192&v=' + Date.now();
                showToast('success', 'تمت الإعادة', 'رجعت أيقونة النظام الافتراضية');
            } else handleApiError(res);
        }, 'إعادة الافتراضية');
    }

    /* ════════ الملف الشخصي ════════ */
    async function saveProfile() {
        const fullName = document.getElementById('profileFullName').value.trim();
        if (!fullName) return showToast('warning', 'تنبيه', 'الاسم الكامل مطلوب');
        const res = await apiPost('profile_update', { full_name: fullName, password: document.getElementById('profilePassword').value });
        if (res.success) {
            showToast('success', 'تم الحفظ', 'تم تحديث بياناتك الشخصية');
