    /* ════════ طابور المبيعات بدون اتصال (Offline Queue) ════════ */
    const SALE_QUEUE_KEY = 'ansnet_sale_queue';

    function getSaleQueue() {
        try { return JSON.parse(localStorage.getItem(SALE_QUEUE_KEY) || '[]'); } catch (e) { return []; }
    }
    function saveSaleQueue(q) {
        try { localStorage.setItem(SALE_QUEUE_KEY, JSON.stringify(q)); } catch (e) {}
        updateQueueChip();
    }
    function queueOfflineSale(payload, meta) {
        const q = getSaleQueue();
        q.push({ id: 'q' + Date.now() + Math.random().toString(36).slice(2, 7), payload, meta, status: 'pending', error: '' });
        saveSaleQueue(q);
    }

    function ensureQueueUI() {
        if (document.getElementById('saleQueueChip')) return;
        const chip = document.createElement('button');
        chip.id = 'saleQueueChip';
        chip.style.cssText = 'display:none; position:fixed; bottom:18px; left:18px; z-index:1500; align-items:center; gap:8px; padding:11px 18px; border-radius:30px; border:1px solid rgba(255,255,255,0.95); background:rgba(255,255,255,0.85); backdrop-filter:blur(20px) saturate(180%); -webkit-backdrop-filter:blur(20px) saturate(180%); box-shadow:0 14px 34px -10px rgba(201,138,27,0.5), inset 0 1px 0 rgba(255,255,255,1); font-family:var(--font-body); font-weight:800; font-size:13px; color:#6B4A08; cursor:pointer;';
        chip.innerHTML = '<i class="ph-fill ph-cloud-arrow-up" style="font-size:18px; color:var(--gold);"></i> <span id="queueChipText"></span>';
        chip.onclick = openQueueModal;
        document.body.appendChild(chip);

        const modal = document.createElement('div');
        modal.className = 'modal-overlay';
        modal.id = 'saleQueueModal';
        modal.innerHTML = `<div class="modal-box modal-wide">
            <div class="modal-header">
                <div class="modal-title"><i class="ph-duotone ph-cloud-arrow-up"></i> عمليات بانتظار المزامنة</div>
                <button class="modal-close" onclick="closeModal('saleQueueModal')"><i class="ph-bold ph-x"></i></button>
            </div>
            <div id="queueListBox"></div>
            <div class="modal-footer">
                <button class="btn btn-outline" onclick="closeModal('saleQueueModal')">إغلاق</button>
                <button class="btn btn-gold" onclick="syncSaleQueue(true)"><i class="ph-bold ph-arrows-clockwise"></i> مزامنة الآن</button>
            </div>
        </div>`;
        modal.addEventListener('click', e => { if (e.target === modal) modal.classList.remove('show'); });
        document.body.appendChild(modal);
    }

    function updateQueueChip() {
        ensureQueueUI();
        const q = getSaleQueue();
        const chip = document.getElementById('saleQueueChip');
        if (!q.length) { chip.style.display = 'none'; return; }
        const errors = q.filter(i => i.status === 'error').length;
        document.getElementById('queueChipText').textContent = q.length + ' عملية بانتظار المزامنة' + (errors ? ` (${errors} بحاجة لمراجعة)` : '');
        chip.style.display = 'inline-flex';
    }

    function openQueueModal() {
        renderQueueList();
        openModal('saleQueueModal');
    }

    function renderQueueList() {
        const q = getSaleQueue();
        const box = document.getElementById('queueListBox');
        if (!q.length) {
            box.innerHTML = '<div class="empty-state" style="padding:24px;"><i class="ph-duotone ph-check-circle"></i><div class="empty-state-title">لا عمليات معلّقة 🎉</div></div>';
            return;
        }
        box.innerHTML = q.map(item => `
            <div class="card card-flat" style="margin-bottom:10px; padding:14px 16px;">
                <div style="display:flex; justify-content:space-between; align-items:center; gap:10px; flex-wrap:wrap;">
                    <div>
                        <div style="font-weight:800; color:var(--text-dark); font-size:13.5px;">${escapeHtml(item.meta.customer_name)} — ${money(item.meta.total_sell)}</div>
                        <div style="font-size:11.5px; color:var(--text-muted); margin-top:3px;">${escapeHtml(item.meta.category_name)} · ${formatDateTime(item.meta.created_at)}</div>
                        ${item.status === 'error' ? `<div style="font-size:11.5px; color:var(--danger); margin-top:5px;"><i class="ph-fill ph-warning"></i> ${escapeHtml(item.error)}</div>` : ''}
                    </div>
                    <div style="display:flex; gap:6px;">
                        ${item.status === 'error' ? `<button class="btn-icon btn-outline" onclick="retryQueueItem('${item.id}')" title="إعادة المحاولة"><i class="ph-bold ph-arrow-clockwise"></i></button>` : '<span class="badge badge-gold">قيد الانتظار</span>'}
                        <button class="btn-icon btn-outline danger" onclick="deleteQueueItem('${item.id}')" title="حذف"><i class="ph-bold ph-trash"></i></button>
                    </div>
                </div>
            </div>`).join('');
    }

    function retryQueueItem(id) {
        const q = getSaleQueue();
        const item = q.find(i => i.id === id);
        if (item) { item.status = 'pending'; item.error = ''; saveSaleQueue(q); renderQueueList(); syncSaleQueue(); }
    }
    function deleteQueueItem(id) {
        saveSaleQueue(getSaleQueue().filter(i => i.id !== id));
        renderQueueList();
    }

    let queueSyncing = false;
    async function syncSaleQueue(manual = false) {
        if (queueSyncing) return;
        if (!navigator.onLine) { if (manual) showToast('warning', 'لا يوجد اتصال', 'ستتم المزامنة تلقائياً فور عودة النت'); return; }
        let q = getSaleQueue();
        const pending = q.filter(i => i.status === 'pending');
        if (!pending.length) { if (manual) showToast('info', 'لا عمليات معلّقة'); return; }

        queueSyncing = true;
        let synced = 0;
        for (const item of pending) {
            const res = await apiPost('sale_create', item.payload);
            q = getSaleQueue();
            if (res.success) {
                q = q.filter(i => i.id !== item.id);
                synced++;
            } else if (res.offline) {
                saveSaleQueue(q);
                break; // انقطع الاتصال مجدداً — نتوقف ونكمل لاحقاً
            } else {
                const it = q.find(i => i.id === item.id);
                if (it) { it.status = 'error'; it.error = res.message || 'رفضها الخادم'; }
            }
            saveSaleQueue(q);
        }
        queueSyncing = false;
        if (synced > 0) {
            showToast('success', `تمت مزامنة ${synced} عملية ☁️`, 'رُفعت للخادم بنجاح');
            if (document.getElementById('page-sales').classList.contains('active')) loadSales();
            if (document.getElementById('page-dashboard').classList.contains('active')) loadDashboard();
        }
        const errs = getSaleQueue().filter(i => i.status === 'error').length;
        if (errs > 0) showToast('warning', `${errs} عملية بحاجة لمراجعة`, 'اضغط على شارة المزامنة بالأسفل للتفاصيل');
        if (document.getElementById('saleQueueModal')?.classList.contains('show')) renderQueueList();
    }

    /* ════════ خصم رصيد من زبون ════════ */
    function openDeductBalanceModal(customerId, customerName, currentBalance) {
        document.getElementById('dbCustomerId').value = customerId;
        document.getElementById('dbCustomerName').textContent = customerName;
        document.getElementById('dbCurrentBalance').textContent = money(currentBalance);
        document.getElementById('dbAmount').value = '';
        document.getElementById('dbNote').value = '';
        closeModal('customerDetailModal');
        openModal('deductBalanceModal');
    }

    async function submitDeductBalance() {
        const id = document.getElementById('dbCustomerId').value;
        const amount = parseFloat(document.getElementById('dbAmount').value);
        if (!amount || amount <= 0) return showToast('warning', 'تنبيه', 'أدخل مبلغاً صحيحاً أكبر من صفر');
        const btn = document.getElementById('dbSubmitBtn'); btn.disabled = true;
        const res = await apiPost('customer_deduct_balance', { id, amount, note: document.getElementById('dbNote').value.trim() });
        btn.disabled = false;
        if (res.success) {
            showToast('success', 'تم الخصم ✅', 'الرصيد الجديد: ' + money(res.new_balance));
            closeModal('deductBalanceModal');
            await loadCustomersCache();
            loadCustomers();
            openCustomerDetail(id);
        } else handleApiError(res);
    }

    /* ════════ سحب بطاقة من زبون ════════ */
    let WITHDRAW_CTX = { source: null, customerId: 0 };

    function openWithdrawCardModal(cardId, cardNumber, customerName, source, customerId) {
        WITHDRAW_CTX = { source: source || null, customerId: customerId || 0 };
        document.getElementById('wcCardId').value = cardId;
        document.getElementById('wcCardNumber').textContent = cardNumber;
        document.getElementById('wcCardInfo').textContent = customerName ? ('لدى الزبون: ' + customerName) : '';
        document.querySelector('input[name="wcMode"][value="pool"]').checked = true;
        document.getElementById('wcNote').value = '';
        if (source === 'detail') closeModal('customerDetailModal');
        openModal('withdrawCardModal');
    }

    async function submitWithdrawCard() {
        const cardId = document.getElementById('wcCardId').value;
        const mode = document.querySelector('input[name="wcMode"]:checked').value;
        const btn = document.getElementById('wcSubmitBtn'); btn.disabled = true;
        const res = await apiPost('card_withdraw', { card_id: cardId, mode, note: document.getElementById('wcNote').value.trim() });
        btn.disabled = false;
        if (res.success) {
            showToast('success', 'تم سحب البطاقة ✅', mode === 'pool' ? 'رجعت للمخزون وصارت متاحة للبيع من جديد' : 'حُذفت نهائياً — وبقي أثرها محفوظاً في سجل المسحوبات');
            closeModal('withdrawCardModal');
            if (WITHDRAW_CTX.source === 'detail' && WITHDRAW_CTX.customerId) openCustomerDetail(WITHDRAW_CTX.customerId);
            else if (WITHDRAW_CTX.source === 'log') loadCardLog();
            else if (WITHDRAW_CTX.source === 'check') loadCardCheck();
        } else handleApiError(res);
    }

    /* ════════ صفحة فحص بطاقة ════════ */
    function loadCardCheckPage() {
        const inp = document.getElementById('ccSearchInput');
        if (inp) { inp.focus(); if (inp.value.trim().length >= 2) loadCardCheck(); }
    }
    const ccSearchDebounced = debounce(loadCardCheck, 350);

    async function loadCardCheck() {
        const q = document.getElementById('ccSearchInput').value.trim();
        const box = document.getElementById('ccResultsBox');
        if (q.length < 2) {
            box.innerHTML = '<div class="empty-state"><i class="ph-duotone ph-magnifying-glass" style="font-size:44px; color:var(--text-muted);"></i><p style="color:var(--text-muted); margin-top:10px;">اكتب حرفين على الأقل للبحث</p></div>';
            return;
        }
        box.innerHTML = '<div style="text-align:center; padding:26px; color:var(--text-muted);">جارٍ البحث...</div>';
        const res = await apiGet('card_check', { q });
        if (!res.success) return handleApiError(res);
        const cards = res.cards || [], wds = res.withdrawals || [];
        if (!cards.length && !wds.length) {
            box.innerHTML = '<div class="empty-state"><i class="ph-duotone ph-cards" style="font-size:44px; color:var(--text-muted);"></i><div class="empty-state-title">لا نتائج مطابقة</div><div class="empty-state-sub">ما في بطاقة أو زبون بهذا الرقم/الاسم</div></div>';
            return;
        }
        let html = '';
        if (cards.length) {
            html += `<div class="card-title" style="margin-bottom:10px;"><i class="ph-duotone ph-cards"></i> نتائج البطاقات <span style="font-size:12px; color:var(--text-muted); font-weight:600;">(${cards.length})</span></div>`;
            html += cards.map(cd => {
                const sent = cd.status === 'sent';
                return `<div class="cc-card">
                    <div class="cc-top">
                        <span class="cc-num">${escapeHtml(cd.card_number)}</span>
                        ${sent ? '<span class="badge badge-purple">مُرسَلة لزبون</span>' : '<span class="badge badge-green">متاحة بالمخزون</span>'}
                        ${sent && parseInt(cd.sold_via_portal) === 1 ? '<span class="badge badge-gold">شراء ذاتي من البوابة</span>' : ''}
                        ${sent && can('inventory.manage') ? `<button class="btn btn-sm btn-outline danger" style="margin-inline-start:auto;" onclick="openWithdrawCardModal(${cd.id}, '${escapeHtml(cd.card_number)}', '${escapeHtml(cd.customer_name || '')}', 'check', 0)"><i class="ph-bold ph-arrow-u-up-left"></i> سحب</button>` : ''}
                    </div>
                    <div class="cc-grid">
                        <div class="cc-field">الفئة<b>${escapeHtml(cd.category_name || '—')}</b></div>
                        ${sent ? `<div class="cc-field">لدى الزبون<b>${escapeHtml(cd.customer_name || '—')}${cd.customer_username ? ' <span style=\"color:var(--text-muted); font-weight:600;\">@' + escapeHtml(cd.customer_username) + '</span>' : ''}</b></div>` : ''}
                        ${sent && cd.customer_phone ? `<div class="cc-field">جوال الزبون<b style="direction:ltr;">${escapeHtml(cd.customer_phone)}</b></div>` : ''}
                        ${sent ? `<div class="cc-field">تاريخ ووقت الإرسال<b>${formatDateTime(cd.sent_at)}</b></div>` : ''}
                        ${sent ? `<div class="cc-field">الطريقة<b>${parseInt(cd.sold_via_portal) === 1 ? 'اشتراها بنفسه من البوابة' : ('إرسال يدوي' + (cd.sender_name ? ' — بواسطة ' + escapeHtml(cd.sender_name) : ''))}</b></div>` : ''}
                        ${cd.sale_price ? `<div class="cc-field">سعر البيع<b>${money(cd.sale_price)}</b></div>` : ''}
                    </div>
                </div>`;
            }).join('');
        }
        if (wds.length) {
            html += `<div class="card-title" style="margin:18px 0 10px;"><i class="ph-duotone ph-arrow-u-up-left"></i> بطاقات مسحوبة مطابقة <span style="font-size:12px; color:var(--text-muted); font-weight:600;">(${wds.length})</span></div>`;
            html += wds.map(w => `<div class="cc-card" style="border-style:dashed; opacity:0.92;">
                <div class="cc-top">
                    <span class="cc-num">${escapeHtml(w.card_number)}</span>
                    <span class="badge badge-red">مسحوبة ${parseInt(w.returned_to_pool) === 1 ? '— رجعت للمخزون' : '— حُذفت نهائياً'}</span>
                </div>
                <div class="cc-grid">
                    <div class="cc-field">كانت لدى<b>${escapeHtml(w.customer_name || '—')}</b></div>
                    <div class="cc-field">الفئة<b>${escapeHtml(w.category_name || '—')}</b></div>
                    <div class="cc-field">سحبها<b>${escapeHtml(w.withdrawn_by_name || '—')}</b></div>
                    <div class="cc-field">وقت السحب<b>${formatDateTime(w.created_at)}</b></div>
                    ${w.note ? `<div class="cc-field">السبب<b>${escapeHtml(w.note)}</b></div>` : ''}
                </div>
            </div>`).join('');
        }
        box.innerHTML = html;
    }

    /* ════════ سجل التدقيق (للمالك فقط) ════════ */
    const auditSearchDebounced = debounce(loadAuditPage, 400);

    function auditMeta(action) {
        const a = action || '';
        if (a.includes('فاشلة') || a.includes('محظور')) return ['ph-warning', 'var(--danger)', 'var(--danger-soft)'];
        if (a.includes('خروج')) return ['ph-sign-out', 'var(--text-muted)', 'rgba(140,132,171,0.15)'];
        if (a.includes('دخول')) return ['ph-sign-in', 'var(--success)', 'var(--success-soft)'];
        if (a.includes('بيع') || a.includes('فاتورة')) return ['ph-cash-register', 'var(--primary)', 'var(--primary-soft)'];
        if (a.includes('حذف') || a.includes('سحب')) return ['ph-trash', 'var(--danger)', 'var(--danger-soft)'];
        if (a.includes('خصم')) return ['ph-minus-circle', 'var(--danger)', 'var(--danger-soft)'];
        if (a.includes('رصيد') || a.includes('شحن')) return ['ph-wallet', 'var(--success)', 'var(--success-soft)'];
        if (a.includes('تذكرة') || a.includes('دعم')) return ['ph-headset', 'var(--primary)', 'var(--primary-soft)'];
        if (a.includes('إشعار')) return ['ph-bell-ringing', 'var(--gold)', 'var(--gold-soft)'];
        if (a.includes('صيانة')) return ['ph-wrench', 'var(--danger)', 'var(--danger-soft)'];
        if (a.includes('بطاقة') || a.includes('مخزون')) return ['ph-cards', 'var(--primary)', 'var(--primary-soft)'];
        if (a.includes('دين') || a.includes('سداد')) return ['ph-hand-coins', 'var(--gold)', 'var(--gold-soft)'];
        if (a.includes('مصروف')) return ['ph-wallet', 'var(--danger)', 'var(--danger-soft)'];
        if (a.includes('موظف')) return ['ph-identification-badge', 'var(--primary)', 'var(--primary-soft)'];
        if (a.includes('إعداد') || a.includes('أيقونة') || a.includes('اسم')) return ['ph-gear-six', 'var(--text-muted)', 'rgba(140,132,171,0.15)'];
        if (a.includes('زبون') || a.includes('تسجيل')) return ['ph-users-three', 'var(--primary)', 'var(--primary-soft)'];
        if (a.includes('إيصال')) return ['ph-receipt', 'var(--gold)', 'var(--gold-soft)'];
        return ['ph-clipboard-text', 'var(--text-muted)', 'rgba(140,132,171,0.15)'];
    }

    async function loadAuditPage() {
        if (!IS_OWNER) return;
        const box = document.getElementById('auditListBox');
        box.innerHTML = '<div style="text-align:center; padding:26px; color:var(--text-muted);">جارٍ التحميل...</div>';
        const res = await apiGet('audit_logs_list', { search: document.getElementById('auditSearch').value.trim(), limit: document.getElementById('auditLimit').value });
        if (!res.success) { box.innerHTML = ''; return handleApiError(res); }
        if (!res.data.length) {
            box.innerHTML = '<div class="empty-state"><i class="ph-duotone ph-scroll" style="font-size:44px; color:var(--text-muted);"></i><div class="empty-state-title">لا أحداث مطابقة</div><div class="empty-state-sub">جرّب كلمة بحث مختلفة أو زد عدد الأحداث</div></div>';
            return;
        }
        box.innerHTML = res.data.map(l => {
            const [icon, color, bg] = auditMeta(l.action);
            return `<div class="audit-row">
                <div class="audit-ico" style="color:${color}; background:${bg};"><i class="ph-duotone ${icon}"></i></div>
                <div class="audit-main">
                    <div class="audit-action">${escapeHtml(l.action)}</div>
                    ${l.details ? `<div class="audit-details">${escapeHtml(l.details)}</div>` : ''}
                    <div class="audit-meta">
                        <span><i class="ph-bold ph-user-circle"></i> ${escapeHtml(l.user_name || 'النظام')}</span>
                        <span><i class="ph-bold ph-clock-counter-clockwise"></i> ${formatDateTime(l.created_at)}</span>
                        ${l.ip_address ? `<span style="direction:ltr;"><i class="ph-bold ph-wifi-high"></i> ${escapeHtml(l.ip_address)}</span>` : ''}
                    </div>
                </div>
            </div>`;
        }).join('');
    }

    /* ════════ الدعم الفني — محادثات الزبائن بنمط واتساب ════════ */
    let TICKETS_CACHE = [];
    let ticketFilter = 'open';
    let currentTicketId = null;
    let currentTicketStatus = 'open';
    let lastMsgId = 0;
    let supportTimer = null;

    function setTicketFilter(f) {
        ticketFilter = f;
        document.getElementById('tkTabOpen').classList.toggle('active', f === 'open');
        document.getElementById('tkTabClosed').classList.toggle('active', f === 'closed');
        document.getElementById('tkTabAll').classList.toggle('active', f === 'all');
        loadSupportPage();
    }

    async function loadSupportPage() {
        if (!can('support.manage')) return;
        const res = await apiGet('tickets_list', { status: ticketFilter });
        if (res.success) { TICKETS_CACHE = res.data || []; renderTicketRows(); }
        if (supportTimer) clearInterval(supportTimer);
        // تحديث تلقائي كل 5 ثوانٍ ما دامت صفحة الدعم مفتوحة — يتوقف تلقائياً عند مغادرتها
        supportTimer = setInterval(async () => {
            const page = document.getElementById('page-support');
            if (!page || !page.classList.contains('active')) { clearInterval(supportTimer); supportTimer = null; return; }
            const r = await apiGet('tickets_list', { status: ticketFilter });
            if (r.success) { TICKETS_CACHE = r.data || []; renderTicketRows(); }
            if (currentTicketId) pollTicketMessages();
        }, 5000);
    }

    function shortTime(dt) {
        if (!dt) return '';
        const d = new Date(String(dt).replace(' ', 'T'));
        if (isNaN(d)) return '';
        const now = new Date();
        return d.toDateString() === now.toDateString()
            ? d.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })
            : d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'short' });
    }

    function renderTicketRows() {
        const box = document.getElementById('ticketListBox');
        if (!box) return;
        const q = (document.getElementById('tkSearch').value || '').trim().toLowerCase();
        const list = TICKETS_CACHE.filter(t => !q || (t.customer_name || '').toLowerCase().includes(q) || (t.subject || '').toLowerCase().includes(q));
        if (!list.length) {
            box.innerHTML = '<div class="empty-state"><i class="ph-duotone ph-chats-circle" style="font-size:40px; color:var(--text-muted);"></i><p style="color:var(--text-muted); margin-top:8px;">لا توجد تذاكر هنا</p></div>';
        } else {
            box.innerHTML = list.map(t => {
                const unread = parseInt(t.unread_admin) || 0;
                const snippet = (t.last_sender === 'staff' ? 'أنت: ' : '') + (t.last_body || t.subject || '');
                return `<div class="ticket-item ${t.id == currentTicketId ? 'active' : ''}" onclick="openTicket(${t.id})">
                    <div class="ticket-avatar">${escapeHtml((t.customer_name || '؟').trim().charAt(0))}</div>
                    <div class="ticket-item-info">
                        <div class="ticket-item-name">${escapeHtml(t.customer_name || 'زبون')}</div>
                        <div class="ticket-item-snippet">${escapeHtml(snippet.slice(0, 48))}</div>
                    </div>
                    <div class="ticket-item-meta">
                        <span class="ticket-item-time">${shortTime(t.last_msg_at)}</span>
                        ${unread ? `<span class="ticket-unread">${unread}</span>` : `<span class="ticket-status-chip ${t.status}">${t.status === 'open' ? 'مفتوحة' : 'مغلقة'}</span>`}
                    </div>
                </div>`;
            }).join('');
        }
        if (ticketFilter !== 'closed') {
            const totalUnread = TICKETS_CACHE.filter(t => t.status === 'open').reduce((s, t) => s + (parseInt(t.unread_admin) || 0), 0);
            const sb = document.getElementById('supportBadge');
            if (sb) { if (totalUnread > 0) { sb.style.display = 'inline-block'; sb.textContent = totalUnread; } else sb.style.display = 'none'; }
        }
    }

    async function openTicket(id) {
        currentTicketId = id; lastMsgId = 0;
        document.getElementById('chatEmptyState').style.display = 'none';
        document.getElementById('chatActive').style.display = 'flex';
        document.getElementById('chatMessages').innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-muted);">جارٍ التحميل...</div>';
        document.getElementById('supportLayout').classList.add('show-chat');
        renderTicketRows();
        const res = await apiGet('ticket_messages', { ticket_id: id });
        if (!res.success) return handleApiError(res);
        const t = res.ticket;
        currentTicketStatus = t.status;
        document.getElementById('chatAvatar').textContent = (t.customer_name || '؟').trim().charAt(0);
        document.getElementById('chatCustName').textContent = t.customer_name || 'زبون';
        document.getElementById('chatCustSub').textContent = (t.customer_username ? '@' + t.customer_username : '') + (t.customer_phone ? ' · ' + t.customer_phone : '');
        const wa = document.getElementById('chatWaLink');
        if (t.customer_phone) { wa.style.display = ''; wa.href = 'https://wa.me/' + String(t.customer_phone).replace(/[^0-9]/g, ''); }
        else wa.style.display = 'none';
        updateChatStatusBtn();
        document.getElementById('chatMessages').innerHTML = '';
        appendMessages(res.messages || []);
        const tc = TICKETS_CACHE.find(x => x.id == id);
        if (tc) tc.unread_admin = 0;
        renderTicketRows();
    }

    function updateChatStatusBtn() {
        const btn = document.getElementById('chatStatusBtn');
        const lbl = document.getElementById('chatStatusBtnLabel');
        if (!btn || !lbl) return;
        if (currentTicketStatus === 'open') { btn.classList.add('danger'); lbl.textContent = 'إغلاق التذكرة'; }
        else { btn.classList.remove('danger'); lbl.textContent = 'إعادة فتح'; }
    }

    function appendMessages(msgs) {
        const boxEl = document.getElementById('chatMessages');
        msgs.forEach(m => {
            lastMsgId = Math.max(lastMsgId, parseInt(m.id) || 0);
            const cls = m.sender === 'staff' ? 'cb-me' : (m.sender === 'system' ? 'cb-system' : 'cb-them');
            const div = document.createElement('div');
            div.className = 'chat-bubble ' + cls;
            const meta = (m.sender === 'staff' && m.sender_name ? escapeHtml(m.sender_name) + ' · ' : '') + shortTime(m.created_at);
            div.innerHTML = escapeHtml(m.body) + '<span class="cb-meta">' + meta + '</span>';
            boxEl.appendChild(div);
        });
        if (msgs.length) boxEl.scrollTop = boxEl.scrollHeight;
    }

    async function pollTicketMessages() {
        if (!currentTicketId) return;
        const res = await apiGet('ticket_messages', { ticket_id: currentTicketId, after_id: lastMsgId });
        if (res.success) {
            if (res.messages && res.messages.length) appendMessages(res.messages);
            if (res.ticket) { currentTicketStatus = res.ticket.status; updateChatStatusBtn(); }
        }
    }

    async function sendTicketReply() {
        const input = document.getElementById('chatReplyInput');
        const body = input.value.trim();
        if (!body || !currentTicketId) return;
        input.value = '';
        const res = await apiPost('ticket_reply', { ticket_id: currentTicketId, body });
        if (res.success) { currentTicketStatus = 'open'; updateChatStatusBtn(); await pollTicketMessages(); loadTicketsSilent(); }
        else { input.value = body; handleApiError(res); }
    }

    async function loadTicketsSilent() {
        const r = await apiGet('tickets_list', { status: ticketFilter });
        if (r.success) { TICKETS_CACHE = r.data || []; renderTicketRows(); }
    }

    function toggleTicketStatus() {
        if (!currentTicketId) return;
        const to = currentTicketStatus === 'open' ? 'closed' : 'open';
        const doIt = async () => {
            const res = await apiPost('ticket_set_status', { ticket_id: currentTicketId, status: to });
            if (res.success) {
                currentTicketStatus = to; updateChatStatusBtn();
                await pollTicketMessages(); loadTicketsSilent();
                showToast('success', to === 'closed' ? 'أُغلقت التذكرة ✅' : 'أُعيد فتح التذكرة');
            } else handleApiError(res);
        };
        if (to === 'closed') showConfirm('إغلاق التذكرة', 'سيصل الزبون إشعار بالإغلاق، ويمكنه إعادة فتحها بإرسال رسالة جديدة', doIt, 'إغلاق التذكرة');
        else doIt();
    }

    function backToTicketList() {
        document.getElementById('supportLayout').classList.remove('show-chat');
        currentTicketId = null;
        renderTicketRows();
    }

    /* ════════ التهيئة الأولية ════════ */
    async function refreshSidebarBadges() {
        try {
            if (can('debts.view')) {
                const dRes = await apiGet('debts_summary');
                if (dRes.success) updateDebtsBadge(dRes.customers_count);
            }
            if (can('inventory.view')) {
                const cRes = await apiGet('categories_list');
                if (cRes.success) {
                    const lowCount = cRes.data.filter(c => c.is_active == 1 && parseInt(c.quantity_available) <= parseInt(c.low_stock_threshold)).length;
                    const badge = document.getElementById('lowStockBadge');
                    if (badge) {
                        if (lowCount > 0) { badge.style.display = 'inline-block'; badge.textContent = lowCount; }
                        else badge.style.display = 'none';
                    }
                }
            }
            const pRes = await apiGet('staff_portal_summary');
            if (pRes.success) {
                const rb = document.getElementById('receiptsBadge');
                if (rb) {
                    if (pRes.pending_receipts > 0) { rb.style.display = 'inline-block'; rb.textContent = pRes.pending_receipts; }
                    else rb.style.display = 'none';
                }
                const qb = document.getElementById('requestsBadge');
                if (qb) {
                    if (pRes.pending_requests > 0) { qb.style.display = 'inline-block'; qb.textContent = pRes.pending_requests; }
                    else qb.style.display = 'none';
                }
                const sb = document.getElementById('supportBadge');
                if (sb) {
                    if (pRes.support_unread > 0) { sb.style.display = 'inline-block'; sb.textContent = pRes.support_unread; }
                    else sb.style.display = 'none';
                }
            }
        } catch (e) { /* صامت */ }
    }

    (function initApp() {
        // تسجيل الـ Service Worker: أساس فتح النظام بدون نت وتثبيته كتطبيق
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.register('?action=sw').catch(() => {});
        }

        const hashPage = window.location.hash.replace('#', '');
        const validPages = ['dashboard','pos','sales','customers','debts','inventory','cardspool','cardlog','cardcheck','receipts','requests','expenses','reports','employees','support','audit','settings','profile'];
        const startPage = validPages.includes(hashPage) ? hashPage : 'dashboard';
        if (document.getElementById('page-' + startPage)) {
            goToPage(startPage);
            refreshSidebarBadges();

            // طابور المزامنة: تحديث الشارة + محاولة فورية + عند عودة الاتصال + كل 30 ثانية
            ensureQueueUI();
            updateQueueChip();
            syncSaleQueue();
            window.addEventListener('online', () => syncSaleQueue());
            setInterval(() => { if (getSaleQueue().some(i => i.status === 'pending')) syncSaleQueue(); }, 30000);
        }
    })();
    </script>
    <?php
}

